def now_iso() -> str:
    return datetime.now().astimezone().isoformat(timespec="seconds")


def ensure_private_directory(path: str | Path) -> Path:
    target = Path(path)
    target.mkdir(parents=True, exist_ok=True, mode=0o700)
    if os.name != "nt":
        target.chmod(0o700)
    return target


def ensure_private_file(path: str | Path) -> Path:
    target = Path(path)
    if os.name != "nt" and target.exists():
        target.chmod(0o600)
    return target


def atomic_write_private_json(path: str | Path, value: Any) -> Path:
    target = Path(path)
    payload = json.dumps(value, ensure_ascii=False, indent=2).encode("utf-8")
    parent = ensure_private_directory(target.parent)
    temporary = parent / f".{target.name}.tmp-{uuid.uuid4().hex}"
    descriptor = -1
    try:
        descriptor = os.open(
            temporary,
            os.O_WRONLY | os.O_CREAT | os.O_EXCL,
            0o600,
        )
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = -1
            handle.write(payload)
            handle.flush()
            os.fsync(handle.fileno())
        os.replace(temporary, target)
        ensure_private_file(target)
        if os.name != "nt":
            directory_descriptor = os.open(parent, os.O_RDONLY)
            try:
                os.fsync(directory_descriptor)
            finally:
                os.close(directory_descriptor)
        return target
    finally:
        if descriptor >= 0:
            os.close(descriptor)
        try:
            temporary.unlink(missing_ok=True)
        except OSError:
            pass


def _runtime_path_is_reparse(metadata: os.stat_result) -> bool:
    attributes = int(getattr(metadata, "st_file_attributes", 0) or 0)
    marker = int(getattr(stat, "FILE_ATTRIBUTE_REPARSE_POINT", 0x400) or 0x400)
    return bool(attributes & marker)


def _runtime_can_use_dir_fd() -> bool:
    return bool(
        os.name != "nt"
        and getattr(os, "O_NOFOLLOW", 0)
        and os.open in getattr(os, "supports_dir_fd", set())
        and os.mkdir in getattr(os, "supports_dir_fd", set())
    )


def _runtime_requires_windows_directory_locks() -> bool:
    return os.name == "nt"


def _windows_open_handle(
    path: Path,
    *,
    access: int,
    share: int,
    disposition: int,
    flags: int,
    missing_ok: bool = False,
) -> Any | None:
    if os.name != "nt":
        raise RuntimeError("Windows handle operations are unavailable.")
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    create_file = kernel32.CreateFileW
    create_file.argtypes = [
        wintypes.LPCWSTR,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.LPVOID,
        wintypes.DWORD,
        wintypes.DWORD,
        wintypes.HANDLE,
    ]
    create_file.restype = wintypes.HANDLE
    handle = create_file(
        str(path), access, share, None, disposition, flags, None
    )
    if handle == wintypes.HANDLE(-1).value:
        error = ctypes.get_last_error()
        if missing_ok and error in {2, 3}:
            return None
        raise OSError(error, ctypes.FormatError(error), str(path))
    return handle


def _windows_handle_information(handle: Any) -> dict[str, int]:
    if os.name != "nt":
        raise RuntimeError("Windows handle operations are unavailable.")
    import ctypes
    from ctypes import wintypes

    class ByHandleFileInformation(ctypes.Structure):
        _fields_ = [
            ("dwFileAttributes", wintypes.DWORD),
            ("ftCreationTime", wintypes.FILETIME),
            ("ftLastAccessTime", wintypes.FILETIME),
            ("ftLastWriteTime", wintypes.FILETIME),
            ("dwVolumeSerialNumber", wintypes.DWORD),
            ("nFileSizeHigh", wintypes.DWORD),
            ("nFileSizeLow", wintypes.DWORD),
            ("nNumberOfLinks", wintypes.DWORD),
            ("nFileIndexHigh", wintypes.DWORD),
            ("nFileIndexLow", wintypes.DWORD),
        ]

    class FileId128(ctypes.Structure):
        _fields_ = [("Identifier", wintypes.BYTE * 16)]

    class FileIdInformation(ctypes.Structure):
        _fields_ = [
            ("VolumeSerialNumber", ctypes.c_ulonglong),
            ("FileId", FileId128),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    get_information = kernel32.GetFileInformationByHandle
    get_information.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(ByHandleFileInformation),
    ]
    get_information.restype = wintypes.BOOL
    get_information_ex = kernel32.GetFileInformationByHandleEx
    get_information_ex.argtypes = [
        wintypes.HANDLE,
        ctypes.c_int,
        wintypes.LPVOID,
        wintypes.DWORD,
    ]
    get_information_ex.restype = wintypes.BOOL
    get_file_type = kernel32.GetFileType
    get_file_type.argtypes = [wintypes.HANDLE]
    get_file_type.restype = wintypes.DWORD
    information = ByHandleFileInformation()
    if not get_information(handle, ctypes.byref(information)):
        error = ctypes.get_last_error()
        raise OSError(error, ctypes.FormatError(error))
    identity = FileIdInformation()
    if not get_information_ex(
        handle, 0x12, ctypes.byref(identity), ctypes.sizeof(identity)
    ):
        error = ctypes.get_last_error()
        raise OSError(error, ctypes.FormatError(error))
    file_id = int.from_bytes(bytes(identity.FileId.Identifier), "little")
    if not _windows_file_id_is_trustworthy(file_id):
        raise ValueError(
            "Windows filesystem does not provide a trustworthy 128-bit file identity."
        )
    return {
        "attributes": int(information.dwFileAttributes),
        "file_type": int(get_file_type(handle)),
        "links": int(information.nNumberOfLinks),
        "size": (int(information.nFileSizeHigh) << 32)
        | int(information.nFileSizeLow),
        "volume": int(identity.VolumeSerialNumber),
        "file_id": file_id,
    }


def _windows_close_handle(handle: Any) -> None:
    if handle is None:
        return
    import ctypes
    from ctypes import wintypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    close_handle = kernel32.CloseHandle
    close_handle.argtypes = [wintypes.HANDLE]
    close_handle.restype = wintypes.BOOL
    close_handle(handle)


def _windows_file_id_is_trustworthy(file_id: int) -> bool:
    return 0 < file_id < (1 << 128) - 1


def _acquire_windows_directory_lock(
    path: Path,
) -> tuple[Any, Callable[[], None], dict[str, int]]:
    """Pin one real Windows directory and deny writes, rename, or deletion."""

    handle = _windows_open_handle(
        path,
        access=0x0080 | 0x0020,  # FILE_READ_ATTRIBUTES | FILE_TRAVERSE
        share=0x00000001,  # FILE_SHARE_READ; deliberately deny write/delete.
        disposition=3,  # OPEN_EXISTING
        flags=0x02000000 | 0x00200000,  # BACKUP_SEMANTICS | OPEN_REPARSE_POINT
    )
    try:
        information = _windows_handle_information(handle)
    except Exception:
        _windows_close_handle(handle)
        raise
    if information["file_type"] != 1 or not (
        information["attributes"] & 0x00000010
    ) or (
        information["attributes"] & 0x00000400
    ):
        _windows_close_handle(handle)
        raise ValueError("Project runtime ancestor is not a trustworthy real directory.")

    closed = False

    def release() -> None:
        nonlocal closed
        if not closed:
            closed = True
            _windows_close_handle(handle)

    return handle, release, information


def _windows_handle_identity_matches(
    first: dict[str, int], second: dict[str, int]
) -> bool:
    return bool(
        first["volume"] == second["volume"]
        and first["file_id"] == second["file_id"]
    )


def _windows_directory_information_for_path(path: Path) -> dict[str, int]:
    handle = _windows_open_handle(
        path,
        access=0x0080 | 0x0020,  # FILE_READ_ATTRIBUTES | FILE_TRAVERSE
        share=0x00000001 | 0x00000002 | 0x00000004,
        disposition=3,  # OPEN_EXISTING
        flags=0x02000000 | 0x00200000,  # BACKUP_SEMANTICS | OPEN_REPARSE_POINT
    )
    try:
        information = _windows_handle_information(handle)
    finally:
        _windows_close_handle(handle)
    if information["file_type"] != 1 or not (
        information["attributes"] & 0x00000010
    ) or (information["attributes"] & 0x00000400):
        raise ValueError(
            "Project runtime ancestor is not a trustworthy real directory."
        )
    return information


def _assert_real_runtime_directory(path: Path, trusted_root: Path) -> os.stat_result:
    try:
        metadata = os.lstat(path)
    except OSError as exc:
        raise ValueError("Project runtime directory is unavailable.") from exc
    if not stat.S_ISDIR(metadata.st_mode) or _runtime_path_is_reparse(metadata):
        raise ValueError("Project runtime directory is not a trustworthy real directory.")
    try:
        resolved = path.resolve(strict=True)
        resolved.relative_to(trusted_root)
    except (OSError, RuntimeError, ValueError) as exc:
        raise ValueError("Project runtime directory escapes its trusted project root.") from exc
    if resolved != path:
        raise ValueError("Project runtime directory contains a link or reparse point.")
    return metadata


def _open_trusted_project_runtime(
    context: ProjectContext, *, create: bool
) -> tuple[int | None, Path, Callable[[], None] | None, Any | None]:
    """Open one service-owned runtime scope without following path links."""

    root = Path(context.service_runtime_root)
    runtime_path = Path(context.runtime_dir)
    if runtime_path.parent != root or runtime_path.name != context.runtime_key:
        raise ValueError("Project runtime scope does not match its trusted service root.")
    if create:
        root.mkdir(parents=True, exist_ok=True, mode=0o700)
    elif not root.exists():
        raise FileNotFoundError(root)
    try:
        trusted_root = root.resolve(strict=True)
    except (OSError, RuntimeError) as exc:
        raise ValueError("Service runtime root is unavailable.") from exc
    if trusted_root != root:
        raise ValueError("Service runtime root contains a link or reparse point.")
    try:
        context.root.resolve(strict=True).relative_to(trusted_root)
    except ValueError:
        pass
    else:
        raise ValueError("Service runtime root must be outside project directories.")
    no_follow = getattr(os, "O_NOFOLLOW", 0)
    directory_flag = getattr(os, "O_DIRECTORY", 0)
    if _runtime_can_use_dir_fd():
        root_metadata = _assert_real_runtime_directory(root, trusted_root)
        root_fd = runtime_fd = None
        try:
            root_fd = os.open(root, os.O_RDONLY | directory_flag | no_follow)
            opened_root = os.fstat(root_fd)
            if (
                not stat.S_ISDIR(opened_root.st_mode)
                or _runtime_path_is_reparse(opened_root)
                or (opened_root.st_dev, opened_root.st_ino)
                != (root_metadata.st_dev, root_metadata.st_ino)
            ):
                raise ValueError("Service runtime root changed while opening a project scope.")
            try:
                runtime_fd = os.open(
                    context.runtime_key,
                    os.O_RDONLY | directory_flag | no_follow,
                    dir_fd=root_fd,
                )
            except FileNotFoundError:
                if not create:
                    raise
                try:
                    os.mkdir(context.runtime_key, 0o700, dir_fd=root_fd)
                except FileExistsError:
                    pass
                runtime_fd = os.open(
                    context.runtime_key,
                    os.O_RDONLY | directory_flag | no_follow,
                    dir_fd=root_fd,
                )
            opened_runtime = os.fstat(runtime_fd)
            if not stat.S_ISDIR(
                opened_runtime.st_mode
            ) or _runtime_path_is_reparse(opened_runtime):
                raise ValueError("Project runtime directory is not trustworthy.")
            if create:
                os.fchmod(runtime_fd, 0o700)
            descriptor = runtime_fd
            runtime_fd = None
            return descriptor, runtime_path, None, None
        finally:
            for descriptor in (runtime_fd, root_fd):
                if descriptor is not None:
                    os.close(descriptor)

    if not _runtime_requires_windows_directory_locks():
        raise RuntimeError(
            "Secure project runtime persistence requires no-follow dirfd support."
        )
    releases: list[Callable[[], None]] = []
    try:
        _root_handle, root_release, root_information = (
            _acquire_windows_directory_lock(root)
        )
        releases.append(root_release)
        if not _windows_handle_identity_matches(
            root_information, _windows_directory_information_for_path(root)
        ):
            raise ValueError("Service runtime root changed while acquiring its lock.")
        _assert_real_runtime_directory(root, trusted_root)
        if not runtime_path.exists() and not runtime_path.is_symlink():
            if not create:
                raise FileNotFoundError(runtime_path)
            try:
                os.mkdir(runtime_path, 0o700)
            except FileExistsError:
                pass
        runtime_handle, runtime_release, runtime_information = (
            _acquire_windows_directory_lock(runtime_path)
        )
        releases.append(runtime_release)
        if not _windows_handle_identity_matches(
            runtime_information,
            _windows_directory_information_for_path(runtime_path),
        ):
            raise ValueError(
                "Service runtime scope changed while acquiring its lock."
            )
        _assert_real_runtime_directory(root, trusted_root)
        _assert_real_runtime_directory(runtime_path, trusted_root)

        held = releases
        releases = []

        def release_all() -> None:
            while held:
                held.pop()()

        return None, runtime_path, release_all, runtime_handle
    finally:
        while releases:
            releases.pop()()


def _runtime_regular_file(metadata: os.stat_result) -> bool:
    return (
        stat.S_ISREG(metadata.st_mode)
        and not _runtime_path_is_reparse(metadata)
        and int(getattr(metadata, "st_nlink", 1) or 1) == 1
    )


def _windows_runtime_file_information(handle: Any) -> dict[str, int]:
    information = _windows_handle_information(handle)
    if (
        information["file_type"] != 1
        or information["attributes"] & 0x00000010
        or information["attributes"] & 0x00000400
        or information["links"] != 1
    ):
        raise ValueError("Project runtime session is not a trustworthy file.")
    return information


def _windows_runtime_information_for_path(target: Path) -> dict[str, int]:
    handle = _windows_open_handle(
        target,
        access=0x0080,  # FILE_READ_ATTRIBUTES
        share=0x00000001 | 0x00000002 | 0x00000004,
        disposition=3,  # OPEN_EXISTING
        flags=0x00000080 | 0x00200000,  # NORMAL | OPEN_REPARSE_POINT
    )
    try:
        return _windows_runtime_file_information(handle)
    finally:
        _windows_close_handle(handle)


def _windows_read_runtime_file(target: Path) -> bytes | None:
    import msvcrt

    handle = _windows_open_handle(
        target,
        access=0x80000000 | 0x0080,  # GENERIC_READ | FILE_READ_ATTRIBUTES
        share=0x00000001,  # FILE_SHARE_READ; deny mutation during validation/read.
        disposition=3,  # OPEN_EXISTING
        flags=0x00000080 | 0x00200000,  # NORMAL | OPEN_REPARSE_POINT
        missing_ok=True,
    )
    if handle is None:
        return None
    descriptor: int | None = None
    try:
        before = _windows_runtime_file_information(handle)
        descriptor = msvcrt.open_osfhandle(
            handle, os.O_RDONLY | getattr(os, "O_BINARY", 0)
        )
        handle = None
        metadata = os.fstat(descriptor)
        if not _runtime_regular_file(metadata):
            raise ValueError("Project runtime session is not a trustworthy file.")
        chunks: list[bytes] = []
        while True:
            chunk = os.read(descriptor, 1024 * 1024)
            if not chunk:
                break
            chunks.append(chunk)
        native_handle = msvcrt.get_osfhandle(descriptor)
        after = _windows_runtime_file_information(native_handle)
        if (
            after["volume"] != before["volume"]
            or after["file_id"] != before["file_id"]
            or after["size"] != before["size"]
        ):
            raise ValueError("Project runtime session changed while reading.")
        return b"".join(chunks)
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if handle is not None:
            _windows_close_handle(handle)


def _windows_rename_runtime_handle(
    handle: Any, runtime_handle: Any, target_name: str
) -> None:
    import ctypes
    from ctypes import wintypes

    if Path(target_name).name != target_name:
        raise ValueError("Project runtime target must be a simple file name.")
    encoded_filename = target_name.encode("utf-16-le")

    class FileRenameInformation(ctypes.Structure):
        _fields_ = [
            ("ReplaceIfExists", wintypes.DWORD),
            ("RootDirectory", wintypes.HANDLE),
            ("FileNameLength", wintypes.DWORD),
            ("FileName", wintypes.WCHAR * 1),
        ]

    buffer_size = (
        ctypes.sizeof(FileRenameInformation) + len(encoded_filename) + 2
    )
    buffer = ctypes.create_string_buffer(buffer_size)
    information = FileRenameInformation.from_buffer(buffer)
    information.ReplaceIfExists = 1
    information.RootDirectory = runtime_handle
    information.FileNameLength = len(encoded_filename)
    ctypes.memmove(
        ctypes.addressof(buffer) + FileRenameInformation.FileName.offset,
        encoded_filename,
        len(encoded_filename),
    )

    class IoStatusBlock(ctypes.Structure):
        _fields_ = [
            ("Status", wintypes.LONG),
            ("Information", ctypes.c_size_t),
        ]

    ntdll = ctypes.WinDLL("ntdll")
    rename = ntdll.NtSetInformationFile
    rename.argtypes = [
        wintypes.HANDLE,
        ctypes.POINTER(IoStatusBlock),
        wintypes.LPVOID,
        wintypes.ULONG,
        ctypes.c_int,
    ]
    rename.restype = wintypes.LONG
    status_block = IoStatusBlock()
    status = int(
        rename(handle, ctypes.byref(status_block), buffer, buffer_size, 10)
    )
    if status < 0:
        status_to_error = ntdll.RtlNtStatusToDosError
        status_to_error.argtypes = [wintypes.ULONG]
        status_to_error.restype = wintypes.ULONG
        error = int(status_to_error(wintypes.ULONG(status).value))
        raise OSError(error, ctypes.FormatError(error), target_name)


def _windows_write_runtime_file(
    runtime_path: Path,
    runtime_handle: Any,
    temporary_name: str,
    target_name: str,
    data: bytes,
) -> None:
    import msvcrt

    temporary = runtime_path / temporary_name
    target = runtime_path / target_name
    handle = _windows_open_handle(
        temporary,
        access=0x40000000 | 0x00010000,  # GENERIC_WRITE | DELETE
        share=0x00000001,  # Keep the temp/final identity pinned until verified.
        disposition=1,  # CREATE_NEW
        flags=0x00000080 | 0x00200000,  # NORMAL | OPEN_REPARSE_POINT
    )
    descriptor: int | None = None
    try:
        before = _windows_runtime_file_information(handle)
        descriptor = msvcrt.open_osfhandle(
            handle, os.O_WRONLY | getattr(os, "O_BINARY", 0)
        )
        handle = None
        view = memoryview(data)
        while view:
            written = os.write(descriptor, view)
            if written <= 0:
                raise OSError("Project runtime session write made no progress.")
            view = view[written:]
        os.fsync(descriptor)
        native_handle = msvcrt.get_osfhandle(descriptor)
        written = _windows_runtime_file_information(native_handle)
        if (
            written["volume"] != before["volume"]
            or written["file_id"] != before["file_id"]
            or written["size"] != len(data)
        ):
            raise ValueError("Project runtime session changed while writing.")
        _windows_rename_runtime_handle(native_handle, runtime_handle, target_name)
        published = _windows_runtime_file_information(native_handle)
        named = _windows_runtime_information_for_path(target)
        if (
            published["volume"] != before["volume"]
            or published["size"] != len(data)
            or not _windows_handle_identity_matches(published, named)
            or named["size"] != len(data)
        ):
            raise ValueError("Persisted project runtime session is not trustworthy.")
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if handle is not None:
            _windows_close_handle(handle)
        try:
            temporary.unlink()
        except OSError:
            pass


def read_trusted_project_runtime_file(
    context: ProjectContext, name: str
) -> bytes | None:
    if name not in {
        "research_session.json",
        "settings.json",
        FRAMING_STATE_FILE,
        "queued_chat_messages.json",
        RUNTIME_IMPORT_FILE,
        RUNTIME_RECOVERY_FILE,
        RUNTIME_RESTART_ACTIVATION_FILE,
    }:
        raise ValueError("Unsupported project runtime file.")
    runtime_fd: int | None = None
    release_runtime: Callable[[], None] | None = None
    windows_runtime_handle: Any | None = None
    descriptor: int | None = None
    try:
        try:
            (
                runtime_fd,
                runtime_path,
                release_runtime,
                windows_runtime_handle,
            ) = _open_trusted_project_runtime(context, create=False)
        except FileNotFoundError:
            return None
        no_follow = getattr(os, "O_NOFOLLOW", 0)
        if runtime_fd is not None:
            try:
                descriptor = os.open(
                    name, os.O_RDONLY | no_follow, dir_fd=runtime_fd
                )
            except FileNotFoundError:
                return None
            metadata = os.fstat(descriptor)
        else:
            _assert_real_runtime_directory(
                runtime_path, Path(context.service_runtime_root)
            )
            if windows_runtime_handle is None:
                raise RuntimeError("Windows project runtime handle is unavailable.")
            return _windows_read_runtime_file(runtime_path / name)
        if not _runtime_regular_file(metadata):
            raise ValueError("Project runtime session is not a trustworthy file.")
        with os.fdopen(descriptor, "rb") as handle:
            descriptor = None
            return handle.read()
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if runtime_fd is not None:
            os.close(runtime_fd)
        if release_runtime is not None:
            release_runtime()


def write_trusted_project_runtime_file(
    context: ProjectContext, name: str, data: bytes
) -> Path:
    if name not in {
        "research_session.json",
        "settings.json",
        FRAMING_STATE_FILE,
        "queued_chat_messages.json",
        RUNTIME_IMPORT_FILE,
        RUNTIME_RECOVERY_FILE,
        RUNTIME_RESTART_ACTIVATION_FILE,
    }:
        raise ValueError("Unsupported project runtime file.")
    runtime_fd: int | None = None
    release_runtime: Callable[[], None] | None = None
    windows_runtime_handle: Any | None = None
    descriptor: int | None = None
    temporary_name = f".{name}.tmp-{uuid.uuid4().hex}"
    try:
        (
            runtime_fd,
            runtime_path,
            release_runtime,
            windows_runtime_handle,
        ) = _open_trusted_project_runtime(context, create=True)
        no_follow = getattr(os, "O_NOFOLLOW", 0)
        flags = os.O_WRONLY | os.O_CREAT | os.O_EXCL | no_follow
        if runtime_fd is not None:
            descriptor = os.open(
                temporary_name, flags, 0o600, dir_fd=runtime_fd
            )
        else:
            _assert_real_runtime_directory(
                runtime_path, Path(context.service_runtime_root)
            )
            if windows_runtime_handle is None:
                raise RuntimeError("Windows project runtime handle is unavailable.")
            _windows_write_runtime_file(
                runtime_path,
                windows_runtime_handle,
                temporary_name,
                name,
                data,
            )
            return runtime_path / name
        with os.fdopen(descriptor, "wb") as handle:
            descriptor = None
            if hasattr(os, "fchmod"):
                os.fchmod(handle.fileno(), 0o600)
            handle.write(data)
            handle.flush()
            os.fsync(handle.fileno())
        if runtime_fd is not None:
            os.replace(
                temporary_name,
                name,
                src_dir_fd=runtime_fd,
                dst_dir_fd=runtime_fd,
            )
            os.fsync(runtime_fd)
            target_fd = os.open(name, os.O_RDONLY | no_follow, dir_fd=runtime_fd)
            try:
                if not _runtime_regular_file(os.fstat(target_fd)):
                    raise ValueError("Persisted project runtime session is not trustworthy.")
            finally:
                os.close(target_fd)
        return runtime_path / name
    finally:
        if descriptor is not None:
            os.close(descriptor)
        if runtime_fd is not None:
            try:
                os.unlink(temporary_name, dir_fd=runtime_fd)
            except OSError:
                pass
            os.close(runtime_fd)
        if release_runtime is not None:
            release_runtime()


def _legacy_runtime_file(context: ProjectContext, name: str) -> bytes | None:
    """Read one pre-v2.1 runtime file without following links or hardlinks."""

    if name not in {
        "research_session.json",
        "settings.json",
        "framing_messages.json",
        "framing_revision.json",
        "queued_chat_messages.json",
    }:
        raise ValueError("Unsupported legacy runtime file.")
    runtime = context.legacy_runtime_dir
    if not runtime.exists():
        return None
    root = context.root.resolve(strict=True)
    try:
        metadata = os.lstat(runtime)
        resolved_runtime = runtime.resolve(strict=True)
        resolved_runtime.relative_to(root)
    except (OSError, RuntimeError, ValueError) as exc:
        raise ValueError("Legacy project runtime directory is not trustworthy.") from exc
    if (
        not stat.S_ISDIR(metadata.st_mode)
        or _runtime_path_is_reparse(metadata)
        or resolved_runtime != runtime
    ):
        raise ValueError("Legacy project runtime directory is not trustworthy.")
    target = runtime / name
    try:
        before = os.lstat(target)
    except FileNotFoundError:
        return None
    if not _runtime_regular_file(before):
        raise ValueError(f"Legacy runtime file is not trustworthy: {name}")
    descriptor = os.open(target, os.O_RDONLY | getattr(os, "O_NOFOLLOW", 0))
    try:
        opened = os.fstat(descriptor)
        if not _runtime_regular_file(opened) or (
            opened.st_dev,
            opened.st_ino,
        ) != (before.st_dev, before.st_ino):
            raise ValueError(f"Legacy runtime file changed while opening: {name}")
        chunks: list[bytes] = []
        while chunk := os.read(descriptor, 1024 * 1024):
            chunks.append(chunk)
        after = os.fstat(descriptor)
        if (after.st_size, after.st_mtime_ns) != (opened.st_size, opened.st_mtime_ns):
            raise ValueError(f"Legacy runtime file changed while reading: {name}")
        return b"".join(chunks)
    finally:
        os.close(descriptor)


def _runtime_digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def import_legacy_project_runtime(context: ProjectContext) -> None:
    """Import project-local volatile state once; never dual-write it again."""

    existing_manifest = read_trusted_project_runtime_file(context, RUNTIME_IMPORT_FILE)
    if existing_manifest is not None:
        try:
            value = json.loads(existing_manifest.decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError("The service runtime import record is unreadable.") from exc
        if not isinstance(value, dict) or value.get("format_version") != 1:
            raise ValueError("The service runtime import record is invalid.")
        return

    sources: dict[str, bytes] = {}
    for name in (
        "research_session.json",
        "settings.json",
        "framing_messages.json",
        "framing_revision.json",
        "queued_chat_messages.json",
    ):
        data = _legacy_runtime_file(context, name)
        if data is not None:
            sources[name] = data

    imported: list[dict[str, Any]] = []

    def install(name: str, data: bytes, source_names: list[str]) -> None:
        current = read_trusted_project_runtime_file(context, name)
        if current is not None and current != data:
            raise ValueError(
                f"A partial legacy runtime import conflicts with {name}; recovery is required."
            )
        if current is None:
            write_trusted_project_runtime_file(context, name, data)
        imported.append(
            {
                "destination": name,
                "destination_sha256": _runtime_digest(data),
                "sources": [
                    {
                        "path": f"ui/.runtime/{source}",
                        "size": len(sources[source]),
                        "sha256": _runtime_digest(sources[source]),
                    }
                    for source in source_names
                    if source in sources
                ],
            }
        )

    if "research_session.json" in sources:
        install(
            "research_session.json",
            sources["research_session.json"],
            ["research_session.json"],
        )
    if "settings.json" in sources:
        try:
            legacy_settings = json.loads(sources["settings.json"].decode("utf-8"))
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError("Legacy project settings are unreadable.") from exc
        if not isinstance(legacy_settings, dict):
            raise ValueError("Legacy project settings must be a JSON object.")
        install(
            "settings.json",
            canonical_json_bytes(legacy_settings),
            ["settings.json"],
        )
    if "queued_chat_messages.json" in sources:
        install(
            "queued_chat_messages.json",
            sources["queued_chat_messages.json"],
            ["queued_chat_messages.json"],
        )
    if "framing_messages.json" in sources or "framing_revision.json" in sources:
        try:
            raw_messages = json.loads(
                sources.get("framing_messages.json", b"[]").decode("utf-8")
            )
            raw_authority = json.loads(
                sources.get("framing_revision.json", b"{}").decode("utf-8")
            )
        except (UnicodeError, json.JSONDecodeError) as exc:
            raise ValueError("Legacy framing state is unreadable.") from exc
        if not isinstance(raw_messages, list) or not isinstance(raw_authority, dict):
            raise ValueError("Legacy framing state is invalid.")
        clean_messages = bounded_framing_messages(raw_messages)
        generation = str(raw_authority.get("generation") or "legacy")[:120]
        try:
            revision = max(0, int(raw_authority.get("revision") or 0))
        except (TypeError, ValueError):
            revision = 0
        state = canonical_json_bytes(
            {
                "format_version": FRAMING_STATE_FORMAT_VERSION,
                "generation": generation,
                "revision": revision,
                "messages": clean_messages,
            }
        )
        install(
            FRAMING_STATE_FILE,
            state,
            ["framing_messages.json", "framing_revision.json"],
        )

    write_trusted_project_runtime_file(
        context,
        RUNTIME_IMPORT_FILE,
        canonical_json_bytes(
            {
                "format_version": 1,
                "project_id": context.id,
                "project_root_sha256": hashlib.sha256(
                    str(context.root).encode("utf-8")
                ).hexdigest(),
                "imported_at": now_iso(),
                "source_runtime": "ui/.runtime",
                "source_files_retained": True,
                "rollback": "Remove this service runtime scope to re-run the immutable source import.",
                "files": imported,
            }
        ),
    )


def now_id() -> str:
    return datetime.now().strftime("%Y%m%d_%H%M%S")


def parse_iso_datetime(value: Any) -> datetime | None:
    text = str(value or "").strip()
    if not text:
        return None
    if text.endswith("Z"):
        text = text[:-1] + "+00:00"
    try:
        parsed = datetime.fromisoformat(text)
    except ValueError:
        return None
    if parsed.tzinfo is None:
        parsed = parsed.astimezone()
    return parsed


def seconds_since_iso(value: Any) -> int | None:
    parsed = parse_iso_datetime(value)
    if parsed is None:
        return None
    return max(0, int((datetime.now().astimezone() - parsed.astimezone()).total_seconds()))


def agent_notice_from_event(line: str, display: str = "") -> dict[str, Any]:
    raw = str(line or "")
    if not raw.strip():
        return {}
    # Only genuine error/system signals count as rate limits. The model's own
    # output and tool results routinely mention "rate", "usage limit", "quota",
    # etc. while researching safety topics — scanning that text produced false
    # "Rate limit reported" notices. Restrict detection to error events and
    # non-JSON diagnostic (stderr) lines.
    is_error_signal = False
    event: Any = None
    try:
        event = json.loads(raw)
    except (json.JSONDecodeError, TypeError, ValueError):
        is_error_signal = True  # non-JSON line is diagnostic/stderr output
    if isinstance(event, dict):
        etype = str(event.get("type") or "").lower()
        subtype = str(event.get("subtype") or "").lower()
        has_error_field = bool(event.get("error") or event.get("is_error"))
        if etype in {"error", "system_error"} or "error" in subtype or has_error_field:
            is_error_signal = True
    if not is_error_signal:
        return {}
    text = "\n".join(part for part in (raw, display) if part).strip()
    if AGENT_RATE_LIMIT_PATTERN.search(text):
        message = compact_single_line(display or text, 260)
        return {
            "kind": "rate_limited",
            "message": message or "Agent reported a rate limit or quota limit.",
            "detected_at": now_iso(),
        }
    return {}


def agent_wait_state_from_values(running: bool, last_event_at: Any, last_event_summary: Any, notice: Any) -> dict[str, Any]:
    age_seconds = seconds_since_iso(last_event_at)
    notice_payload = notice if isinstance(notice, dict) else {}
    kind = str(notice_payload.get("kind") or "").strip()
    message = str(notice_payload.get("message") or "").strip()
    stale = bool(running and age_seconds is not None and age_seconds >= AGENT_IDLE_NOTICE_SECONDS)
    # A rate-limit notice is only meaningful while the agent is actually stalled.
    # If fresh events are still flowing, the limit has cleared — drop the notice
    # so it can't stick on screen after the agent resumes.
    if kind == "rate_limited" and age_seconds is not None and age_seconds < AGENT_RATE_LIMIT_CLEAR_SECONDS:
        kind = ""
        message = ""
    if kind == "rate_limited":
        message = message or "Agent reported a rate limit or quota limit."
    elif stale:
        kind = "idle"
        message = f"No agent events for {age_seconds} seconds; the process is still running."
    elif running:
        kind = "active"
        message = "Agent process is running."
    else:
        kind = "inactive"
        message = "No active agent process."
    return {
        "kind": kind,
        "message": message,
        "last_event_at": str(last_event_at or ""),
        "last_event_age_seconds": age_seconds,
        "last_event_summary": str(last_event_summary or ""),
        "idle_threshold_seconds": AGENT_IDLE_NOTICE_SECONDS,
        "notice": notice_payload,
    }


def research_session_runtime_payload(session: dict[str, Any]) -> dict[str, Any]:
    return {
        key: value
        for key, value in session.items()
        if key
        not in {
            "process",
            "process_thread",
            "streaming_transcript",
            "admission_pending",
        }
    }


def persist_research_session() -> None:
    if not current_project_writeable():
        return
    context = current_project_context()
    with RESEARCH_LOCK:
        payload = research_session_runtime_payload(RESEARCH_SESSION)
        # Keep capture and durable replacement in the same per-project critical
        # section so concurrent event threads cannot persist an older snapshot
        # after a newer one.
        write_trusted_project_runtime_file(
            context,
            "research_session.json",
            json.dumps(payload, ensure_ascii=False, indent=2).encode("utf-8"),
        )


def session_startup_without_process(status: Any, started_at: Any) -> bool:
    normalized = str(status or "").strip().lower()
    if normalized not in {"running", "stopping"}:
        return False
    age = seconds_since_iso(started_at)
    return age is not None and age < SESSION_STARTUP_GRACE_SECONDS


def reconcile_research_process_state() -> None:
    changed = False
    with RESEARCH_LOCK:
        proc = RESEARCH_SESSION.get("process")
        process_thread = RESEARCH_SESSION.get("process_thread")
        status = str(RESEARCH_SESSION.get("status") or "").strip().lower()
        control_boundary_owned = bool(
            (
                RESEARCH_SESSION.get("admission_pending")
                or RESEARCH_SESSION.get("boundary_audit_pending")
            )
            and isinstance(process_thread, threading.Thread)
            and process_thread.is_alive()
        )
        if proc is not None:
            returncode = proc.poll()
            if agent_process_tree_active(proc):
                return
            RESEARCH_SESSION["returncode"] = returncode
            if status in {"running", "stopping"}:
                RESEARCH_SESSION["status"] = "completed" if returncode == 0 else "failed"
            RESEARCH_SESSION["ended_at"] = RESEARCH_SESSION.get("ended_at") or now_iso()
            RESEARCH_SESSION["process"] = None
            RESEARCH_SESSION["process_thread"] = None
            changed = True
        elif status in {"running", "stopping"}:
            # A v2 monitor remains the authoritative owner while it audits the
            # just-finished guard and hands the same trial/stage to the next
            # phase.  Likewise, an accepted Resume admission can spend longer
            # than the process-start grace period recovering a retained guard.
            # Neither is an orphaned process=None session.  On server restart
            # process_thread is absent, so genuine abandoned boundaries still
            # reconcile to interrupted and enter normal recovery.
            if control_boundary_owned:
                return
            if session_startup_without_process(status, RESEARCH_SESSION.get("started_at")):
                return
            RESEARCH_SESSION["status"] = "interrupted"
            RESEARCH_SESSION["ended_at"] = RESEARCH_SESSION.get("ended_at") or now_iso()
            RESEARCH_SESSION["process_thread"] = None
            changed = True
    if changed:
        persist_research_session()


def load_research_session_runtime() -> None:
    if not SESSION_STATE_PATH.exists():
        return
    try:
        payload = json.loads(SESSION_STATE_PATH.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return
    with RESEARCH_LOCK:
        for key in (
            "id",
            "session_id",
            "backend",
            "mode",
            "command",
            "settings",
            "run_settings",
            "started_at",
            "ended_at",
            "returncode",
            "logs",
            "raw_logs",
            "transcript",
            "review_contexts",
            "loop_active",
            "loop_iteration",
            "loop_max_iterations",
            "loop_review_checkpoint_iteration",
            "loop_stop_reason",
            "loop_instruction",
            "gate",
            "last_event_at",
            "last_event_summary",
            "agent_notice",
            "app_thread_id",
            "app_turn_id",
            "session_id_source",
            "v2",
            "v2_trace_sequence",
            "v2_aux_guard_dir",
        ):
            if key in payload:
                RESEARCH_SESSION[key] = payload[key]
        previous_status = str(payload.get("status") or "idle")
        RESEARCH_SESSION["status"] = "interrupted" if previous_status in {"running", "stopping"} else previous_status
        RESEARCH_SESSION["process"] = None
        RESEARCH_SESSION["transcript"] = transcript_with_review_context(
            RESEARCH_SESSION.get("transcript", []), RESEARCH_SESSION.get("review_contexts")
        )


def load_ui_settings(settings_path: Path | None = None) -> dict[str, Any]:
    effective_path = Path(settings_path) if settings_path is not None else current_ui_settings_path()
    context = getattr(_CONTEXT, "project", None)
    trusted_project_settings = (
        isinstance(context, ProjectContext)
        and effective_path == context.ui_settings_path
    )
    settings = {
        "agent": {"backend": selected_agent_backend_from_env()},
        "codex": normalize_codex_settings({}),
        "claude": normalize_claude_settings({}),
        "env": {},
        "codex_env": {},
        "claude_env": {},
    }
    try:
        if trusted_project_settings:
            raw = read_trusted_project_runtime_file(context, "settings.json")
            if raw is None:
                return settings
            payload = json.loads(raw.decode("utf-8"))
        else:
            if not effective_path.exists():
                return settings
            payload = json.loads(effective_path.read_text(encoding="utf-8"))
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
        if trusted_project_settings:
            raise ValueError("Trusted project settings are unreadable or corrupt.") from exc
        return settings
    if not isinstance(payload, dict):
        if trusted_project_settings:
            raise ValueError("Trusted project settings must contain a JSON object.")
        return settings
    if isinstance(payload.get("agent"), dict):
        settings["agent"]["backend"] = normalize_agent_backend(payload["agent"].get("backend"))
    elif isinstance(payload.get("backend"), str):
        settings["agent"]["backend"] = normalize_agent_backend(payload.get("backend"))
    env_backend = valid_agent_backend_from_env()
    if env_backend:
        settings["agent"]["backend"] = env_backend
    if isinstance(payload.get("codex"), dict):
        settings["codex"] = normalize_codex_settings(payload["codex"], settings["codex"])
    if isinstance(payload.get("claude"), dict):
        settings["claude"] = normalize_claude_settings(payload["claude"], settings["claude"])
    if isinstance(payload.get("env"), dict):
        settings["env"] = {key: str(value) for key, value in payload["env"].items() if key in SECRET_ENV_KEYS and str(value)}
    if isinstance(payload.get("codex_env"), dict):
        settings["codex_env"] = normalize_codex_env_values(payload["codex_env"])
    if isinstance(payload.get("claude_env"), dict):
        settings["claude_env"] = normalize_claude_env_values(payload["claude_env"])
    return settings


def public_codex_env(settings: dict[str, Any]) -> dict[str, Any]:
    env = normalize_codex_env_values(settings.get("codex_env", {}))
    return {
        "provider": normalize_codex_provider(settings.get("codex", {}).get("provider")),
        "present": {key: bool(env.get(key)) for key in CODEX_ENV_KEYS},
        "masked": {key: ("Saved" if env.get(key) else "") for key in CODEX_SECRET_ENV_KEYS},
        "values": {key: env.get(key, "") for key in CODEX_NONSECRET_ENV_KEYS},
        "secret_keys": sorted(CODEX_SECRET_ENV_KEYS),
        "keys": CODEX_ENV_KEYS,
    }


def public_claude_env(settings: dict[str, Any]) -> dict[str, Any]:
    env = normalize_claude_env_values(settings.get("claude_env", {}))
    return {
        "provider": normalize_claude_provider(settings.get("claude", {}).get("provider")),
        "present": {key: bool(env.get(key)) for key in CLAUDE_ENV_KEYS},
        "masked": {key: ("Saved" if env.get(key) else "") for key in CLAUDE_SECRET_ENV_KEYS},
        "values": {key: env.get(key, "") for key in CLAUDE_NONSECRET_ENV_KEYS},
        "secret_keys": sorted(CLAUDE_SECRET_ENV_KEYS),
        "keys": CLAUDE_ENV_KEYS,
    }


def public_ui_settings(settings_path: Path | None = None) -> dict[str, Any]:
    effective_path = Path(settings_path) if settings_path is not None else current_ui_settings_path()
    settings = load_ui_settings(effective_path)
    agent_status = agent_backend_status_payload(
        settings["agent"].get("backend"), settings=settings
    )
    return {
        "agent": settings["agent"],
        "codex": settings["codex"],
        "claude": settings["claude"],
        "codex_env": public_codex_env(settings),
        "claude_env": public_claude_env(settings),
        "env_present": {key: bool(settings["env"].get(key)) for key in SECRET_ENV_KEYS},
        "env_masked": {key: ("Saved" if settings["env"].get(key) else "") for key in SECRET_ENV_KEYS},
        "agent_status": agent_status,
        "agent_env_override": agent_status.get("env_override", ""),
    }


def save_ui_settings(
    payload: dict[str, Any], settings_path: Path | None = None
) -> dict[str, Any]:
    effective_path = Path(settings_path) if settings_path is not None else current_ui_settings_path()
    current = load_ui_settings(effective_path)
    agent_payload = payload.get("agent") if isinstance(payload.get("agent"), dict) else {}
    merged_agent = {"backend": normalize_agent_backend(agent_payload.get("backend") or current["agent"].get("backend"))}

    codex = payload.get("codex") if isinstance(payload.get("codex"), dict) else {}
    claude = payload.get("claude") if isinstance(payload.get("claude"), dict) else {}
    merged_codex = normalize_codex_settings(codex, current["codex"])
    merged_claude = normalize_claude_settings(claude, current["claude"])

    env_values = payload.get("env") if isinstance(payload.get("env"), dict) else {}
    merged_env = dict(current["env"])
    for key in payload.get("clear_env", []) if isinstance(payload.get("clear_env"), list) else []:
        if key in SECRET_ENV_KEYS:
            merged_env.pop(key, None)
    for key, value in env_values.items():
        if key in SECRET_ENV_KEYS and str(value).strip():
            merged_env[key] = str(value).strip()

    codex_env_values = payload.get("codex_env") if isinstance(payload.get("codex_env"), dict) else {}
    merged_codex_env = dict(current.get("codex_env", {}))
    for key in payload.get("clear_codex_env", []) if isinstance(payload.get("clear_codex_env"), list) else []:
        if key in CODEX_ENV_KEYS:
            merged_codex_env.pop(key, None)
    for key, value in codex_env_values.items():
        if key in CODEX_ENV_KEYS:
            text = str(value).strip()
            if text:
                merged_codex_env[key] = text

    claude_env_values = payload.get("claude_env") if isinstance(payload.get("claude_env"), dict) else {}
    merged_claude_env = dict(current.get("claude_env", {}))
    for key in payload.get("clear_claude_env", []) if isinstance(payload.get("clear_claude_env"), list) else []:
        if key in CLAUDE_ENV_KEYS:
            merged_claude_env.pop(key, None)
    for key, value in claude_env_values.items():
        if key in CLAUDE_ENV_KEYS:
            text = str(value).strip()
            if text:
                merged_claude_env[key] = text

    saved_payload = {
        "agent": merged_agent,
        "codex": merged_codex,
        "claude": merged_claude,
        "env": merged_env,
        "codex_env": normalize_codex_env_values(merged_codex_env),
        "claude_env": normalize_claude_env_values(merged_claude_env),
    }
    context = getattr(_CONTEXT, "project", None)
    if isinstance(context, ProjectContext) and effective_path == context.ui_settings_path:
        write_trusted_project_runtime_file(
            context, "settings.json", canonical_json_bytes(saved_payload)
        )
    else:
        atomic_write_private_json(effective_path, saved_payload)
    return public_ui_settings(effective_path)


def save_current_project_ui_settings(payload: dict[str, Any]) -> dict[str, Any]:
    return save_ui_settings(payload)


def project_settings_revision() -> str:
    raw = read_trusted_project_runtime_file(
        current_project_context(), "settings.json"
    )
    return hashlib.sha256(raw).hexdigest() if raw is not None else ""


def next_v2_phase_settings(
    completed_settings: dict[str, Any], completed_revision: str
) -> tuple[dict[str, Any], bool]:
    """Bind the next phase to a newer explicit project setting, if any."""

    if project_settings_revision() == str(completed_revision or ""):
        return dict(completed_settings), True
    return implementation_settings_from_payload(None), False


def sanitize_framing_message(item: Any) -> dict[str, Any] | None:
    if not isinstance(item, dict):
        return None
    role = str(item.get("role") or "").strip()
    text = str(item.get("text") or "").strip()
    kind = str(item.get("kind") or "text").strip()
    if role not in {"user", "assistant"}:
        return None
    if kind not in {"text", "project", "plan", "goal-launch", "goal-restart", "command", "intervention-recorded"}:
        kind = "text"
    clean: dict[str, Any] = {
        "id": str(item.get("id") or "").strip()[:120],
        "role": role,
        "kind": kind,
        "text": text[:40_000],
        "created_at": str(item.get("created_at") or "").strip()[:80],
    }
    edited_at = str(item.get("edited_at") or "").strip()
    if edited_at:
        clean["edited_at"] = edited_at[:80]
    artifact = item.get("artifact")
    if isinstance(artifact, dict):
        if kind == "plan":
            plan_id = normalize_plan_id(artifact.get("id") or item.get("planId"))
            plan_text = str(artifact.get("plan_text") or artifact.get("text") or "").strip()
            plan_error = str(artifact.get("error") or "").strip()
            raw_steps = artifact.get("steps") if isinstance(artifact.get("steps"), list) else []
            steps = []
            for step in raw_steps[:80]:
                if not isinstance(step, dict):
                    continue
                step_text = str(step.get("step") or step.get("text") or "").strip()
                if step_text:
                    steps.append({"step": step_text[:1200], "status": str(step.get("status") or "").strip()[:80]})
            if plan_id:
                clean["artifact"] = {
                    "type": "plan",
                    "id": plan_id,
                    "provider": normalize_agent_backend(artifact.get("provider")),
                    "model": str(artifact.get("model") or "").strip()[:120],
                    "status": str(artifact.get("status") or "pending").strip()[:80],
                    "text": plan_text[:120_000],
                    "plan_text": plan_text[:120_000],
                    "steps": steps,
                    "explanation": str(artifact.get("explanation") or "").strip()[:4000],
                    "error": plan_error[:4000],
                    "created_at": str(artifact.get("created_at") or "").strip()[:80],
                    "updated_at": str(artifact.get("updated_at") or "").strip()[:80],
                    "approved_at": str(artifact.get("approved_at") or "").strip()[:80],
                    "implemented_run_id": str(artifact.get("implemented_run_id") or "").strip()[:120],
                }
                if not clean["text"]:
                    clean["text"] = (plan_text or plan_error or "Planning...")[:40_000]
        else:
            artifact_path = str(artifact.get("path") or "").strip()
            artifact_text = str(artifact.get("text") or "").strip()
            if artifact_path and artifact_text:
                clean["artifact"] = {
                    "path": artifact_path[:400],
                    "text": artifact_text[:120_000],
                }
    mode = str(item.get("mode") or "").strip()
    if mode in {"chat", "plan"}:
        clean["mode"] = mode
    revise_plan_id = normalize_plan_id(item.get("revisePlanId"))
    if revise_plan_id:
        clean["revisePlanId"] = revise_plan_id
    attachments = item.get("attachments")
    if isinstance(attachments, list):
        clean_attachments = []
        for attachment in attachments[:30]:
            if not isinstance(attachment, dict):
                continue
            attachment_kind = str(attachment.get("kind") or "").strip()
            name = str(attachment.get("name") or "").strip()
            category = str(attachment.get("category") or "").strip()
            if attachment_kind == "link":
                path = str(attachment.get("path") or "").strip()
                if path:
                    clean_attachments.append({
                        "kind": "link",
                        "path": path[:800],
                        "name": (name or Path(path).name)[:240],
                        "category": category[:80],
                    })
            elif attachment_kind == "upload":
                if name:
                    clean_attachments.append({
                        "kind": "upload",
                        "name": name[:240],
                        "category": category[:80],
                        "type": str(attachment.get("type") or "").strip()[:120],
                        "size": int(attachment.get("size") or 0),
                    })
        if clean_attachments:
            clean["attachments"] = clean_attachments
            if role == "user" and not clean["text"]:
                count = len(clean_attachments)
                clean["text"] = f"Attached {count} {'resource' if count == 1 else 'resources'}."
    resume_from_trial = item.get("resumeFromTrial")
    if isinstance(resume_from_trial, dict):
        resume_id = str(resume_from_trial.get("id") or "").strip()
        resume_path = str(resume_from_trial.get("path") or "").strip()
        if resume_id or resume_path:
            try:
                resume_iteration = int(resume_from_trial.get("iteration") or 0)
            except (TypeError, ValueError):
                resume_iteration = 0
            clean["resumeFromTrial"] = {
                "id": resume_id[:240],
                "path": resume_path[:800],
                "iteration": resume_iteration,
                "name": str(resume_from_trial.get("name") or resume_id or resume_path).strip()[:240],
                "reportPath": str(resume_from_trial.get("reportPath") or resume_from_trial.get("report_path") or "").strip()[:800],
                "checkpointPath": str(resume_from_trial.get("checkpointPath") or resume_from_trial.get("checkpoint_path") or "").strip()[:800],
                "checkpointExists": bool(resume_from_trial.get("checkpointExists") or resume_from_trial.get("checkpoint_exists")),
            }
    if not clean["text"] and not clean.get("artifact"):
        return None
    return {key: value for key, value in clean.items() if value is not None and value != ""}


def bounded_framing_messages(items: list[Any]) -> list[dict[str, Any]]:
    """Retain the immutable launch/restart control prefix plus a bounded tail."""

    messages = [
        clean
        for item in items
        if (clean := sanitize_framing_message(item)) is not None
    ]
    restart_indexes = [
        index for index, item in enumerate(messages) if item.get("kind") == "goal-restart"
    ]
    if restart_indexes:
        anchor = restart_indexes[-1]
    else:
        anchor = next(
            (
                index
                for index, item in enumerate(messages)
                if item.get("kind") == "goal-launch"
            ),
            -1,
        )
    if anchor < 0:
        return messages[-FRAMING_TAIL_MAX:]
    prefix = messages[: anchor + 1]
    if len(prefix) > FRAMING_CONTROL_PREFIX_MAX:
        raise ValueError("The authoritative launch/restart chat prefix is too large.")
    return [*prefix, *messages[anchor + 1 :][-FRAMING_TAIL_MAX:]]


def _empty_framing_state() -> dict[str, Any]:
    return {
        "format_version": FRAMING_STATE_FORMAT_VERSION,
        "generation": "legacy",
        "revision": 0,
        "messages": [],
    }


def load_framing_state() -> dict[str, Any]:
    """Load the atomic framing store or fail closed on trusted-state damage."""

    try:
        raw = read_trusted_project_runtime_file(
            current_project_context(), FRAMING_STATE_FILE
        )
        if raw is None:
            return _empty_framing_state()
        payload = json.loads(raw.decode("utf-8"))
    except (OSError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
        raise ValueError(
            "Trusted framing runtime is unreadable; explicit recovery is required."
        ) from exc
    if (
        not isinstance(payload, dict)
        or payload.get("format_version") != FRAMING_STATE_FORMAT_VERSION
        or not isinstance(payload.get("messages"), list)
    ):
        raise ValueError(
            "Trusted framing runtime has an invalid structure; explicit recovery is required."
        )
    try:
        messages = bounded_framing_messages(payload["messages"])
        revision = max(0, int(payload.get("revision") or 0))
    except (TypeError, ValueError) as exc:
        raise ValueError(
            "Trusted framing runtime contains invalid messages or revision."
        ) from exc
    generation_value = payload.get("generation")
    if not isinstance(generation_value, str) or not generation_value.strip():
        raise ValueError("Trusted framing runtime has no valid generation.")
    generation = generation_value.strip()
    if len(generation) > 120:
        raise ValueError("Trusted framing runtime generation is too long.")
    return {
        "format_version": FRAMING_STATE_FORMAT_VERSION,
        "generation": generation,
        "revision": revision,
        "messages": messages,
    }


def load_framing_messages() -> list[dict[str, Any]]:
    return list(load_framing_state()["messages"])


def load_framing_revision() -> dict[str, Any]:
    state = load_framing_state()
    return {"generation": state["generation"], "revision": state["revision"]}


def save_framing_messages(
    messages: list[dict[str, Any]], *, expected_generation: str | None = None
) -> list[dict[str, Any]]:
    ensure_current_project_writeable()
    context = current_project_context()
    with context.framing_lock:
        state = load_framing_state()
        if expected_generation is not None and expected_generation != state["generation"]:
            raise ValueError(
                "The framing conversation was replaced by Restart; this stale save was rejected."
            )
        clean_messages = bounded_framing_messages(messages)
        write_trusted_project_runtime_file(
            context,
            FRAMING_STATE_FILE,
            canonical_json_bytes(
                {
                    "format_version": FRAMING_STATE_FORMAT_VERSION,
                    "generation": state["generation"],
                    "revision": int(state["revision"]) + 1,
                    "messages": clean_messages,
                }
            ),
        )
    return clean_messages


def replace_framing_messages(
    messages: list[dict[str, Any]], *, generation: str | None = None
) -> dict[str, Any]:
    """Atomically replace the authoritative chat at a Restart boundary."""

    ensure_current_project_writeable()
    context = current_project_context()
    clean_messages = bounded_framing_messages(messages)
    state = {
        "format_version": FRAMING_STATE_FORMAT_VERSION,
        "generation": str(generation or uuid.uuid4().hex)[:120],
        "revision": 0,
        "messages": clean_messages,
    }
    with context.framing_lock:
        write_trusted_project_runtime_file(
            context,
            FRAMING_STATE_FILE,
            canonical_json_bytes(
            {
                **state,
            }
            ),
        )
    return state


def project_has_placeholders(text: str) -> bool:
    return bool(re.search(r"<[^>\n]+>", text or ""))


def update_framing_messages(payload: dict[str, Any]) -> list[dict[str, Any]]:
    if str(payload.get("clientVersion") or "").strip() != FRAMING_MESSAGES_CLIENT_VERSION:
        raise ValueError("UI is out of date. Refresh the page and try again.")
    messages = payload.get("messages")
    if not isinstance(messages, list):
        raise ValueError("messages must be a list.")
    authority = load_framing_revision()
    requested_generation = str(payload.get("generation") or "")
    if authority["generation"] != "legacy" and not requested_generation:
        raise ValueError(
            "The framing conversation was replaced by Restart; refresh before saving messages."
        )
    return save_framing_messages(
        messages,
        expected_generation=requested_generation or authority["generation"],
    )


def read_claude_settings_env(path: Path) -> dict[str, str]:
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return {}
    if not isinstance(payload, dict):
        return {}
    return normalize_claude_env_values(payload.get("env"))


def external_claude_settings_env() -> dict[str, str]:
    env: dict[str, str] = {}
    paths = [Path.home() / ".claude" / "settings.json"]
    try:
        repo_root = Path(os.fspath(REPO_ROOT))
        paths.extend([
            repo_root / ".claude" / "settings.json",
            repo_root / ".claude" / "settings.local.json",
        ])
    except ValueError:
        pass
    for path in paths:
        env.update(read_claude_settings_env(path))
    return env


def _first_env_value(key: str, *sources: dict[str, str]) -> str:
    for source in sources:
        value = str(source.get(key) or "").strip()
        if value:
            return value
    return ""


def _selected_claude_credential_env(saved: dict[str, str], ambient: dict[str, str]) -> dict[str, str]:
    # Source precedence is more important than credential-kind precedence:
    # an explicitly saved API key must not be silently replaced by an ambient
    # auth token.  Within one source, gateway auth token is the most explicit,
    # followed by an API key and then a Claude OAuth setup token.
    for source in (saved, ambient):
        for key in ("ANTHROPIC_AUTH_TOKEN", "ANTHROPIC_API_KEY", "CLAUDE_CODE_OAUTH_TOKEN"):
            value = str(source.get(key) or "").strip()
            if value:
                return {key: value}
    return {}


def _locale_key(value: Any) -> str:
    return re.sub(r"[^a-z0-9]", "", str(value or "").lower())


@lru_cache(maxsize=1)
def available_posix_locales() -> tuple[str, ...]:
    if os.name == "nt":
        return ()
    try:
        result = subprocess.run(
            ["locale", "-a"],
            env=POSIX_INSPECTION_ENV,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=2,
            check=False,
        )
    except (OSError, subprocess.SubprocessError):
        return ()
    if result.returncode != 0:
        return ()
    return tuple(line.strip() for line in result.stdout.splitlines() if line.strip())


def normalize_agent_process_locale(
    env: dict[str, str], available: tuple[str, ...] | None = None
) -> dict[str, str]:
    """Keep inherited locale settings from breaking tools in agent shells.

    Locale names are platform-specific: Linux commonly exposes ``C.UTF-8``
    while macOS does not.  A server launched from an environment carrying an
    unavailable name can still start, but child tools such as Perl/shasum fail
    before doing any work.  Preserve a valid caller locale; only replace an
    unavailable effective locale with a UTF-8 locale that the host actually
    advertises, falling back to the portable ``C`` locale.
    """
    if os.name == "nt":
        return env
    effective = str(env.get("LC_ALL") or env.get("LC_CTYPE") or env.get("LANG") or "").strip()
    if not effective or _locale_key(effective) in {"c", "posix"}:
        return env
    names = available if available is not None else available_posix_locales()
    by_key = {_locale_key(name): name for name in names}
    if not by_key or _locale_key(effective) in by_key:
        return env

    language = re.split(r"[_.@-]", effective, maxsplit=1)[0].lower()
    utf8_names = [name for name in names if "utf8" in _locale_key(name)]
    fallback = next(
        (name for name in utf8_names if name.lower().startswith(language + "_")),
        None,
    )
    if fallback is None:
        fallback = next(
            (by_key[key] for key in ("enususutf8", "enusutf8", "cutf8") if key in by_key),
            None,
        )
    fallback = fallback or "C"
    env["LANG"] = fallback
    env["LC_ALL"] = fallback
    env["LC_CTYPE"] = fallback
    return env


def agent_process_env(backend: str = "", provider_settings: dict[str, Any] | None = None) -> dict[str, str]:
    backend = normalize_agent_backend(backend)
    env = os.environ.copy()
    settings = load_ui_settings()
    env.update(settings.get("env", {}))
    normalize_agent_process_locale(env)
    # A managed project may itself live below an unrelated Git checkout (for
    # example, the dashboard's source tree during local development).  Keep
    # Git-based tools from walking into that parent checkout: it is not part of
    # the research workspace and leaking its status/instructions into an agent
    # run can contaminate both routing and write-scope decisions.
    try:
        project_root = Path(os.fspath(REPO_ROOT)).resolve()
        env["GIT_CEILING_DIRECTORIES"] = os.fspath(project_root.parent)
    except (OSError, RuntimeError, ValueError):
        pass
    # Agent-invoked project validators must not create __pycache__ outside the
    # phase write boundary merely by importing the project's Python modules.
    env["PYTHONDONTWRITEBYTECODE"] = "1"
    if backend == "codex":
        for key in CLAUDE_ENV_KEYS:
            env.pop(key, None)
        selected = normalize_codex_settings(provider_settings or {}, settings.get("codex", {}))
        provider = normalize_codex_provider(selected.get("provider"))
        if provider == "cli":
            for key in CODEX_ENV_KEYS:
                env.pop(key, None)
        else:
            saved = codex_env_for_provider(provider, settings.get("codex_env", {}))
            if saved.get("OPENAI_API_KEY"):
                env["OPENAI_API_KEY"] = saved["OPENAI_API_KEY"]
        return env

    if backend == "claude":
        for key in CODEX_ENV_KEYS:
            env.pop(key, None)
        selected = normalize_claude_settings(provider_settings or {}, settings.get("claude", {}))
        provider = normalize_claude_provider(selected.get("provider"))
        external_env = external_claude_settings_env()
        if provider == "external":
            env.update(external_env)
            return env

        ambient = dict(env)
        ambient.update(external_env)
        saved = normalize_claude_env_values(settings.get("claude_env", {}))
        for key in CLAUDE_ENV_KEYS:
            env.pop(key, None)

        if provider == "anthropic_api_key":
            api_key = _first_env_value("ANTHROPIC_API_KEY", saved, ambient)
            if api_key:
                env["ANTHROPIC_API_KEY"] = api_key
            return env

        provider_env = claude_env_for_provider(provider, saved)
        if provider == "custom_anthropic":
            base_url = _first_env_value("ANTHROPIC_BASE_URL", saved, ambient)
            if base_url:
                provider_env["ANTHROPIC_BASE_URL"] = base_url
            for key in ("ANTHROPIC_MODEL", "ANTHROPIC_DEFAULT_FABLE_MODEL", "ANTHROPIC_DEFAULT_HAIKU_MODEL", "ANTHROPIC_DEFAULT_SONNET_MODEL", "ANTHROPIC_DEFAULT_OPUS_MODEL", "API_TIMEOUT_MS", "CLAUDE_CODE_AUTO_COMPACT_WINDOW", "CLAUDE_CODE_DISABLE_NONESSENTIAL_TRAFFIC"):
                value = _first_env_value(key, saved, ambient)
                if value:
                    provider_env[key] = value
        credential_env = _selected_claude_credential_env(saved, ambient)
        provider_env.pop("ANTHROPIC_AUTH_TOKEN", None)
        provider_env.pop("ANTHROPIC_API_KEY", None)
        provider_env.pop("CLAUDE_CODE_OAUTH_TOKEN", None)
        provider_env.update(credential_env)
        env.update(provider_env)
    return env


def codex_process_env() -> dict[str, str]:
    return agent_process_env("codex")


def agent_executable_names(backend: str, windows: bool | None = None) -> list[str]:
    is_windows = os.name == "nt" if windows is None else windows
    base = "claude" if normalize_agent_backend(backend) == "claude" else "codex"
    if is_windows:
        return [f"{base}.cmd", f"{base}.exe", f"{base}.bat", base]
    return [base]


def codex_executable_names(windows: bool | None = None) -> list[str]:
    return agent_executable_names("codex", windows)


def claude_executable_names(windows: bool | None = None) -> list[str]:
    return agent_executable_names("claude", windows)


def agent_executable_env_vars(backend: str) -> tuple[str, str]:
    return ("COAUTO_CLAUDE", "CLAUDE_BIN") if normalize_agent_backend(backend) == "claude" else ("COAUTO_CODEX", "CODEX_BIN")


def agent_display_name(backend: str) -> str:
    return "Claude Code" if normalize_agent_backend(backend) == "claude" else "Codex"


def _codex_cli_version_key(text: str) -> tuple[int, int, int, int, int]:
    match = re.search(r"\b(\d+)\.(\d+)\.(\d+)(?:-([a-z]+)(?:\.(\d+))?)?", str(text or ""), re.IGNORECASE)
    if not match:
        return (-1, -1, -1, -1, -1)
    prerelease = match.group(4)
    return (
        int(match.group(1)),
        int(match.group(2)),
        int(match.group(3)),
        1 if not prerelease else 0,
        int(match.group(5) or 0),
    )


def _preferred_macos_codex_executable(path_executable: str, env: dict[str, str]) -> str:
    if sys.platform != "darwin" or str(env.get("PATH") or "") != str(os.environ.get("PATH") or ""):
        return path_executable
    candidates = [
        path_executable,
        "/Applications/ChatGPT.app/Contents/Resources/codex",
        "/Applications/Codex.app/Contents/Resources/codex",
    ]
    available = list(dict.fromkeys(candidate for candidate in candidates if candidate and Path(candidate).is_file()))
    if len(available) < 2:
        return available[0] if available else ""

    def version(executable: str) -> tuple[int, int, int, int, int]:
        try:
            probe = subprocess.run(
                [executable, "--version"],
                env=env,
                stdout=subprocess.PIPE,
                stderr=subprocess.STDOUT,
                text=True,
                timeout=2.0,
                check=False,
            )
        except (OSError, subprocess.TimeoutExpired):
            return (-1, -1, -1, -1, -1)
        return _codex_cli_version_key(probe.stdout)

    return max(available, key=version)


def resolve_agent_executable(backend: str, env: dict[str, str] | None = None, windows: bool | None = None) -> str:
    backend = normalize_agent_backend(backend)
    process_env = env if env is not None else os.environ
    search_path = process_env.get("PATH") or None
    primary_env, fallback_env = agent_executable_env_vars(backend)
    configured = str(process_env.get(primary_env) or process_env.get(fallback_env) or "").strip().strip('"')
    if configured:
        expanded = os.path.expandvars(os.path.expanduser(configured))
        configured_path = Path(expanded)
        if configured_path.is_file():
            return str(configured_path)
        found = shutil.which(expanded, path=search_path)
        if found:
            return found
        label = agent_display_name(backend)
        executable_hint = "claude.cmd, claude.exe, or claude" if backend == "claude" else "codex.cmd, codex.exe, or codex"
        raise FileNotFoundError(
            f"Configured {label} executable was not found: {configured}. "
            f"Set {primary_env} to the full path of {executable_hint}."
        )

    for name in agent_executable_names(backend, windows):
        found = shutil.which(name, path=search_path)
        if found:
            if backend == "codex":
                return _preferred_macos_codex_executable(found, process_env) or found
            return found
    if backend == "codex":
        packaged = _preferred_macos_codex_executable("", process_env)
        if packaged:
            return packaged
    names = ", ".join(agent_executable_names(backend, windows))
    label = agent_display_name(backend)
    install_hint = "Install Claude Code CLI" if backend == "claude" else "Install Codex CLI"
    env_hint = "COAUTO_CLAUDE" if backend == "claude" else "COAUTO_CODEX"
    binary_hint = "claude.cmd/claude" if backend == "claude" else "codex.cmd/codex"
    raise FileNotFoundError(
        f"{label} CLI executable not found on PATH. Tried: {names}. "
        f"{install_hint}, start the UI from a terminal where `{agent_executable_names(backend, False)[0]} --version` works, "
        f"or set {env_hint} to the full path of {binary_hint}."
    )


def resolve_codex_executable(env: dict[str, str] | None = None, windows: bool | None = None) -> str:
    return resolve_agent_executable("codex", env, windows)


def resolve_claude_executable(env: dict[str, str] | None = None, windows: bool | None = None) -> str:
    return resolve_agent_executable("claude", env, windows)


def agent_start_error_message(exc: OSError, command: list[str], backend: str) -> str:
    backend = normalize_agent_backend(backend)
    executable = command[0] if command else ("claude" if backend == "claude" else "codex")
    label = agent_display_name(backend)
    env_hint = "COAUTO_CLAUDE" if backend == "claude" else "COAUTO_CODEX"
    shim = "claude.cmd" if backend == "claude" else "codex.cmd"
    version_command = "claude --version" if backend == "claude" else "codex --version"
    if isinstance(exc, FileNotFoundError) or getattr(exc, "winerror", None) == 2:
        return (
            f"Failed to start {label}: executable not found. "
            f"Tried `{executable}`. On Windows, npm installs CLI shims as `{shim}`; "
            f"start the UI from a terminal where `{version_command}` works, or set "
            f"{env_hint} to the full path of {shim}."
        )
    return f"Failed to start {label} using `{executable}`: {exc}"


def codex_start_error_message(exc: OSError, command: list[str]) -> str:
    return agent_start_error_message(exc, command, "codex")


def windows_agent_command_argv(
    command: list[str],
    env: dict[str, str],
    windows: bool | None = None,
) -> list[str]:
    is_windows = os.name == "nt" if windows is None else windows
    if not is_windows or not command:
        return command
    executable = Path(str(command[0]))
    suffix = executable.suffix.lower()
    if suffix not in {".cmd", ".bat", ".ps1"}:
        return command
    shim = executable if suffix == ".ps1" else executable.with_suffix(".ps1")
    if not shim.is_file():
        raise ValueError(
            f"Refusing to launch Windows batch shim without shell interpolation: {executable}. "
            f"Install the npm PowerShell shim at {shim} or configure the native .exe."
        )
    system_root = str(env.get("SystemRoot") or env.get("SYSTEMROOT") or "").strip()
    system_powershell = (
        Path(system_root) / "System32" / "WindowsPowerShell" / "v1.0" / "powershell.exe"
        if system_root
        else None
    )
    powershell = (
        str(system_powershell)
        if system_powershell and system_powershell.is_file()
        else shutil.which("powershell.exe", path=env.get("PATH") or None)
        or shutil.which("pwsh.exe", path=env.get("PATH") or None)
    )
    if not powershell:
        raise FileNotFoundError("PowerShell is required to launch the npm agent shim safely on Windows.")
    return [
        powershell,
        "-NoLogo",
        "-NoProfile",
        "-NonInteractive",
        "-ExecutionPolicy",
        "Bypass",
        "-File",
        str(shim),
        *command[1:],
    ]


def agent_version_command(backend: str) -> list[str]:
    return ["--version"]


def agent_auth_command(backend: str) -> list[str]:
    return ["auth", "status"] if normalize_agent_backend(backend) == "claude" else ["login", "status"]


def agent_login_command_text(backend: str) -> str:
    return "claude auth login" if normalize_agent_backend(backend) == "claude" else "codex login"


def agent_auth_status_command_text(backend: str) -> str:
    return "claude auth status" if normalize_agent_backend(backend) == "claude" else "codex login status"


def agent_version_command_text(backend: str) -> str:
    return "claude --version" if normalize_agent_backend(backend) == "claude" else "codex --version"


def agent_install_hint(backend: str) -> str:
    return "Install Claude Code CLI" if normalize_agent_backend(backend) == "claude" else "Install Codex CLI"


def agent_env_hint(backend: str) -> str:
    primary, fallback = agent_executable_env_vars(backend)
    return f"{primary}/{fallback}"


def agent_settings_for_probe(backend: str, settings: dict[str, Any] | None = None) -> dict[str, Any]:
    backend = normalize_agent_backend(backend)
    saved = load_ui_settings()
    values = settings if isinstance(settings, dict) and normalize_agent_backend(settings.get("backend") or backend) == backend else {}
    if backend == "claude":
        normalized = normalize_claude_settings(values, saved.get("claude", {}))
    else:
        normalized = normalize_codex_settings(values, saved.get("codex", {}))
    normalized["backend"] = backend
    return normalized


def spawn_agent_probe_process(command: Any, **popen_kwargs: Any) -> subprocess.Popen[str]:
    """Launch a bounded CLI probe without the long-lived research sentinel.

    A version/auth/catalog probe is not an agent run. Giving it the research
    sentinel meant a server shutdown in the middle of a settings request could
    orphan that sentinel indefinitely. POSIX probes instead get a disposable
    process group; Windows keeps the existing kill-on-close Job Object.
    """

    if os.name == "nt":
        return spawn_agent_process(command, **popen_kwargs)
    kwargs = dict(popen_kwargs)
    kwargs["start_new_session"] = True
    proc = subprocess.Popen(command, **kwargs)
    setattr(proc, "_coauto_probe_process_group_id", int(proc.pid))
    return proc


def drain_agent_probe_process(proc: subprocess.Popen[str]) -> None:
    if os.name == "nt":
        drain_agent_process_tree(proc, grace_seconds=0.0, kill_seconds=1.0)
        return
    process_group_id = int(
        getattr(proc, "_coauto_probe_process_group_id", 0) or 0
    )
    if process_group_id <= 0 or process_group_id != int(proc.pid):
        raise RuntimeError("CLI probe has no isolated POSIX process group.")
    try:
        os.killpg(process_group_id, signal.SIGTERM)
    except ProcessLookupError:
        pass
    deadline = time.monotonic() + 0.5
    while time.monotonic() < deadline:
        try:
            os.killpg(process_group_id, 0)
        except ProcessLookupError:
            break
        time.sleep(0.02)
    else:
        try:
            os.killpg(process_group_id, signal.SIGKILL)
        except ProcessLookupError:
            pass
    try:
        proc.wait(timeout=1.0)
    except subprocess.TimeoutExpired as exc:
        raise RuntimeError("CLI probe process group did not drain.") from exc


def run_agent_probe(backend: str, executable: str, args: list[str], env: dict[str, str] | None = None, timeout: float = 6.0, settings: dict[str, Any] | None = None, input_data: str | None = None) -> dict[str, Any]:
    backend = normalize_agent_backend(backend)
    command = [executable, *args]
    process_env = env if env is not None else os.environ
    wrapper_path: Path | None = None
    proc: subprocess.Popen[str] | None = None
    try:
        try:
            probe_cwd = os.fspath(REPO_ROOT)
        except ValueError:
            probe_cwd = None
        popen_command, use_shell, wrapper_path = popen_command_for_agent(command, agent_settings_for_probe(backend, settings), process_env)
        proc = spawn_agent_probe_process(
            popen_command,
            env=process_env,
            cwd=probe_cwd,
            stdin=subprocess.PIPE if input_data is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            shell=use_shell,
        )
        stdout, stderr = proc.communicate(input=input_data, timeout=timeout)
    except FileNotFoundError as exc:
        return {"ok": False, "returncode": 127, "output": str(exc), "error": str(exc), "timeout": False}
    except subprocess.TimeoutExpired as exc:
        if proc is not None:
            try:
                drain_agent_probe_process(proc)
            except (OSError, RuntimeError):
                pass
            try:
                stdout, stderr = proc.communicate(timeout=1)
            except subprocess.TimeoutExpired:
                stdout, stderr = exc.stdout or "", exc.stderr or ""
        else:
            stdout, stderr = exc.stdout or "", exc.stderr or ""
        output = "\n".join(filter(None, [str(exc.stdout or ""), str(exc.stderr or "")])).strip()
        if not output:
            output = "\n".join(filter(None, [str(stdout or ""), str(stderr or "")])).strip()
        return {"ok": False, "returncode": None, "output": output or "Command timed out.", "error": "timeout", "timeout": True}
    except OSError as exc:
        return {"ok": False, "returncode": 126, "output": str(exc), "error": str(exc), "timeout": False}
    except ValueError as exc:
        return {"ok": False, "returncode": 126, "output": str(exc), "error": str(exc), "timeout": False}
    finally:
        if proc is not None:
            drain_agent_probe_process(proc)
        if wrapper_path:
            try:
                wrapper_path.unlink(missing_ok=True)
            except OSError:
                pass
    output = "\n".join(filter(None, [stdout, stderr])).strip()
    return {"ok": proc.returncode == 0 if proc is not None else False, "returncode": proc.returncode if proc is not None else None, "output": output, "error": "", "timeout": False}


def claude_gateway_status_from_env(env: dict[str, str] | None = None) -> dict[str, Any]:
    process_env = env if env is not None else agent_process_env("claude")
    base_url = str(process_env.get("ANTHROPIC_BASE_URL") or "").strip()
    auth_token = str(process_env.get("ANTHROPIC_AUTH_TOKEN") or "").strip()
    api_key = str(process_env.get("ANTHROPIC_API_KEY") or "").strip()
    oauth_token = str(process_env.get("CLAUDE_CODE_OAUTH_TOKEN") or "").strip()
    credential_key = (
        "ANTHROPIC_AUTH_TOKEN"
        if auth_token
        else "ANTHROPIC_API_KEY"
        if api_key
        else "CLAUDE_CODE_OAUTH_TOKEN"
        if oauth_token
        else ""
    )
    model_mappings = {
        key: str(process_env.get(key) or "").strip()
        for key in ("ANTHROPIC_DEFAULT_FABLE_MODEL", "ANTHROPIC_DEFAULT_HAIKU_MODEL", "ANTHROPIC_DEFAULT_SONNET_MODEL", "ANTHROPIC_DEFAULT_OPUS_MODEL")
        if str(process_env.get(key) or "").strip()
    }
    return {
        "configured": bool(base_url or credential_key or model_mappings),
        "base_url": base_url,
        "credential_key": credential_key,
        "has_credential": bool(credential_key),
        "complete": bool(base_url and credential_key),
        "model_mappings": model_mappings,
    }


def _json_object_from_probe_output(output: str) -> dict[str, Any] | None:
    text = str(output or "").strip()
    candidates = [text, *[line.strip() for line in text.splitlines() if line.strip().startswith("{")]]
    for candidate in candidates:
        if not candidate:
            continue
        try:
            payload = json.loads(candidate)
        except json.JSONDecodeError:
            continue
        if isinstance(payload, dict):
            return payload
    return None


def _claude_auth_status_from_json(payload: dict[str, Any]) -> str:
    true_keys = ("authenticated", "logged_in", "loggedIn", "is_authenticated", "isAuthenticated")
    for key in true_keys:
        if key in payload:
            return "ok" if bool(payload.get(key)) else "missing"
    string_keys = ("status", "state", "auth", "authentication", "login_status", "loginStatus")
    for key in string_keys:
        value = str(payload.get(key) or "").strip().lower().replace("-", "_").replace(" ", "_")
        if not value:
            continue
        if any(marker in value for marker in ("unauthenticated", "logged_out", "not_logged_in", "signed_out", "missing", "unauthorized")):
            return "missing"
        if any(marker in value for marker in ("authenticated", "logged_in", "signed_in", "authorized")):
            return "ok"
    return ""


def auth_probe_status(backend: str, probe: dict[str, Any]) -> str:
    normalized = normalize_agent_backend(backend)
    text = str(probe.get("output") or probe.get("error") or "")
    lowered = text.lower()
    if probe.get("timeout"):
        return "unknown"
    unknown_markers = [
        "unknown command",
        "unrecognized command",
        "unrecognised command",
        "invalid command",
        "no such command",
        "unknown subcommand",
        "unrecognized subcommand",
        "unrecognised subcommand",
        "unexpected argument",
        "invalid option",
        "unknown option",
        "not enough arguments",
    ]
    if any(marker in lowered for marker in unknown_markers):
        return "unknown"
    if normalized == "claude":
        json_status = _claude_auth_status_from_json(_json_object_from_probe_output(str(probe.get("output") or "")) or {})
        if json_status:
            return json_status
    if probe.get("returncode") == 0 or probe.get("ok"):
        return "ok"
    missing_markers = [
        "not logged",
        "not authenticated",
        "not signed",
        "unauthenticated",
        "authentication required",
        "login required",
        "please login",
        "please log in",
        "no credentials",
        "no api key",
        "not authorized",
        "not authorised",
    ]
    if any(marker in lowered for marker in missing_markers):
        return "missing"
    return "missing" if probe.get("returncode") not in (None, 0) else "unknown"


def agent_setup_instruction(backend: str, reason: str) -> str:
    label = agent_display_name(backend)
    if reason == "missing":
        return (
            f"{label} CLI is not available. {agent_install_hint(backend)}, verify `{agent_version_command_text(backend)}`, "
            f"or set {agent_env_hint(backend)} to the CLI executable."
        )
    if reason == "version":
        return (
            f"{label} CLI was found but `{agent_version_command_text(backend)}` failed. "
            f"Verify the install or set {agent_env_hint(backend)} to a working executable."
        )
    if reason == "auth":
        return (
            f"{label} is not authenticated. Run `{agent_login_command_text(backend)}` and verify "
            f"`{agent_auth_status_command_text(backend)}` before starting a run."
        )
    if reason == "auth_status":
        return (
            f"{label} authentication status could not be verified. Run `{agent_auth_status_command_text(backend)}` "
            f"or update {label} CLI, then try again."
        )
    if reason == "openai_api_key":
        return "OpenAI API key is missing. Add it in Settings or start the UI with OPENAI_API_KEY."
    if reason == "anthropic_api_key":
        return "Anthropic API key is missing. Add it in Settings or start the UI with ANTHROPIC_API_KEY."
    if reason == "zai_glm":
        return "Z.AI GLM Coding Plan needs a Z.AI API key. Add it in Settings or set ANTHROPIC_AUTH_TOKEN."
    if reason == "custom_anthropic":
        return "Custom Anthropic-compatible gateway needs a base URL and credential. Add them in Settings."
    return f"{label} readiness could not be determined."


def agent_setup_status(backend: str, env: dict[str, str] | None = None, settings: dict[str, Any] | None = None) -> dict[str, Any]:
    backend = normalize_agent_backend(backend)
    label = agent_display_name(backend)
    probe_settings = agent_settings_for_probe(backend, settings)
    process_env = env if env is not None else agent_process_env(backend, probe_settings)
    provider = (
        normalize_claude_provider(probe_settings.get("provider"))
        if backend == "claude"
        else normalize_codex_provider(probe_settings.get("provider"))
    )
    gateway_status = claude_gateway_status_from_env(process_env) if backend == "claude" else {}
    base: dict[str, Any] = {
        "backend": backend,
        "label": label,
        "platform": sys.platform,
        "provider": provider,
        "ok": False,
        "blocking": False,
        "installed": False,
        "auth": "unknown",
        "executable": "",
        "version": "",
        "message": "",
        "env_vars": list(agent_executable_env_vars(backend)),
        "version_command": agent_version_command_text(backend),
        "login_command": agent_login_command_text(backend),
        "auth_status_command": agent_auth_status_command_text(backend),
        "gateway": gateway_status,
    }
    try:
        executable = resolve_agent_executable(backend, process_env)
    except FileNotFoundError as exc:
        base.update({
            "blocking": True,
            "installed": False,
            "message": agent_setup_instruction(backend, "missing"),
            "details": str(exc),
        })
        return base

    base["executable"] = executable
    version_probe = run_agent_probe(backend, executable, agent_version_command(backend), process_env, settings=probe_settings)
    if not version_probe.get("ok"):
        base.update({
            "blocking": True,
            "installed": False,
            "message": agent_setup_instruction(backend, "version"),
            "details": str(version_probe.get("output") or version_probe.get("error") or ""),
        })
        return base

    base["installed"] = True
    base["version"] = str(version_probe.get("output") or "").splitlines()[0][:240]

    if backend == "codex" and provider == "openai_api_key":
        if str(process_env.get("OPENAI_API_KEY") or "").strip():
            base.update({
                "ok": True,
                "blocking": False,
                "auth": "api_key",
                "message": "Codex CLI is installed and OpenAI API key is available.",
            })
            return base
        base.update({
            "blocking": True,
            "auth": "missing",
            "message": agent_setup_instruction(backend, "openai_api_key"),
            "details": "Selected provider is OpenAI API key, but OPENAI_API_KEY is not available to this UI process.",
        })
        return base

    if backend == "claude" and provider == "anthropic_api_key":
        if str(process_env.get("ANTHROPIC_API_KEY") or "").strip():
            base.update({
                "ok": True,
                "blocking": False,
                "auth": "api_key",
                "message": "Claude Code CLI is installed and Anthropic API key is available.",
            })
            return base
        base.update({
            "blocking": True,
            "auth": "missing",
            "message": agent_setup_instruction(backend, "anthropic_api_key"),
            "details": "Selected provider is Anthropic API key, but ANTHROPIC_API_KEY is not available to this UI process.",
        })
        return base

    if backend == "claude" and provider == "external" and str(process_env.get("CLAUDE_CODE_OAUTH_TOKEN") or "").strip():
        base.update({
            "ok": True,
            "blocking": False,
            "auth": "oauth_token",
            "message": "Claude Code CLI is installed and a Claude OAuth token is available.",
        })
        return base

    if backend == "claude" and provider in {"zai_glm", "custom_anthropic"}:
        base["gateway"] = gateway_status
        if gateway_status.get("complete"):
            base.update({
                "ok": True,
                "blocking": False,
                "auth": "gateway",
                "message": (
                    "Claude Code CLI is installed and an Anthropic-compatible gateway is configured "
                    f"via {gateway_status.get('credential_key') or 'environment credentials'}."
                ),
            })
            return base
        base.update({
            "blocking": True,
            "auth": "missing",
            "message": agent_setup_instruction(backend, provider),
            "details": (
                "Missing gateway base URL."
                if not gateway_status.get("base_url")
                else "Missing gateway credential."
            ),
        })
        return base

    auth_probe = run_agent_probe(backend, executable, agent_auth_command(backend), process_env, settings=probe_settings)
    auth = auth_probe_status(backend, auth_probe)
    base["auth"] = auth
    if backend == "claude" and gateway_status.get("base_url") and not gateway_status.get("has_credential") and auth != "ok":
        base.update({
            "blocking": True,
            "message": (
                "Claude Code has an Anthropic-compatible gateway base URL configured, but no "
                "ANTHROPIC_AUTH_TOKEN, ANTHROPIC_API_KEY, or CLAUDE_CODE_OAUTH_TOKEN is available to this UI process."
            ),
            "details": "Set the gateway credential in Settings, ~/.claude/settings.json, or the terminal environment that starts CoAutoResearch.",
        })
        return base
    if backend == "claude" and gateway_status.get("complete") and auth in {"missing", "unknown"}:
        base.update({
            "ok": True,
            "blocking": False,
            "auth": "gateway",
            "message": (
                "Claude Code CLI is installed and an Anthropic-compatible gateway is configured "
                f"via {gateway_status.get('credential_key') or 'environment credentials'}."
            ),
            "details": str(auth_probe.get("output") or auth_probe.get("error") or ""),
        })
        return base
    if auth == "missing":
        base.update({
            "blocking": True,
            "message": agent_setup_instruction(backend, "auth"),
            "details": str(auth_probe.get("output") or auth_probe.get("error") or ""),
        })
        return base
    if auth == "unknown":
        base.update({
            "ok": False,
            "blocking": True,
            "message": (
                agent_setup_instruction(backend, "auth_status")
            ),
            "details": str(auth_probe.get("output") or auth_probe.get("error") or ""),
        })
        return base

    base.update({
        "ok": True,
        "blocking": False,
        "message": f"{label} CLI is installed and authenticated.",
    })
    return base


_AGENT_MODELS_CACHE: dict[str, dict[str, Any]] = {}


def _format_claude_model_label(value: str) -> str:
    """Turn an underlying CLI value like `claude-opus-4-8` or `opus` into a human label."""
    raw = str(value or "").strip()
    if not raw:
        return ""
    full_match = re.match(r"^claude-(opus|sonnet|haiku|fable|mythos)-(\d+)(?:-(\d+))?(?:-(\d{6,8}))?$", raw, re.IGNORECASE)
    if full_match:
        tier = full_match.group(1).capitalize()
        major = full_match.group(2)
        minor = full_match.group(3)
        version = f"{major}.{minor}" if minor else major
        return f"Claude {tier} {version}"
    if raw.lower() in {"opus", "sonnet", "haiku", "fable", "mythos"}:
        return f"Claude {raw.capitalize()}"
    return raw


def _format_codex_model_label(value: str) -> str:
    raw = str(value or "").strip()
    if not raw:
        return ""
    if re.match(r"^gpt-\d", raw, re.IGNORECASE):
        upper = raw.upper().replace("CODEX", "Codex").replace("MINI", "Mini").replace("SPARK", "Spark")
        return upper
    return raw


def _parse_claude_models_from_help(help_text: str) -> list[tuple[str, str]]:
    lines = str(help_text or "").splitlines()
    model_lines: list[str] = []
    for index, line in enumerate(lines):
        if not re.search(r"(?:^|\s)--model\s+<model>(?:\s|$)", line):
            continue
        model_lines.append(line)
        for continuation in lines[index + 1:]:
            if re.match(r"^\s*(?:-[A-Za-z],\s*)?--[A-Za-z]", continuation):
                break
            model_lines.append(continuation)
        break
    # Do not infer aliases from examples for unrelated options.  The model
    # option itself is the CLI's declaration of what it accepts.
    text = "\n".join(model_lines)
    found: dict[str, str] = {}
    # Only aliases actually named by this installed CLI are selectable.  This
    # covers the current quoted examples and older comma/choice formats.
    alias_pattern = r"(?<![A-Za-z0-9_-])(best|default|fable|haiku|mythos|opusplan(?:\[1m\])?|opus(?:\[1m\])?|sonnet(?:\[1m\])?)(?![A-Za-z0-9_-])"
    for match in re.finditer(alias_pattern, text, re.IGNORECASE):
        value = match.group(1).lower()
        found.setdefault(value, _format_claude_model_label(value))
    return [(value, label) for value, label in found.items()]


def _parse_codex_models_from_help(help_text: str) -> list[tuple[str, str]]:
    text = str(help_text or "")
    found: dict[str, str] = {}
    for match in re.finditer(r"\bgpt-\d+(?:\.\d+)?(?:-[a-z0-9-]+)?\b", text, re.IGNORECASE):
        value = match.group(0).lower()
        found.setdefault(value, _format_codex_model_label(value))
    return [(value, label) for value, label in found.items()]


def _claude_model_sort_key(item: tuple[str, str]) -> tuple[int, int, int, str]:
    value, _ = item
    tier_order = {"fable": -2, "mythos": -1, "opus": 0, "sonnet": 1, "haiku": 2}
    full = re.match(r"^claude-(opus|sonnet|haiku|fable|mythos)-(\d+)(?:-(\d+))?", value, re.IGNORECASE)
    if full:
        tier = tier_order.get(full.group(1).lower(), 99)
        # Newer versions first: negate major/minor for stable sort.
        major = -int(full.group(2))
        minor = -int(full.group(3) or 0)
        return (tier, major, minor, value)
    if value in tier_order:
        return (tier_order[value], 0, 0, value)
    return (99, 0, 0, value)


def _codex_model_sort_key(item: tuple[str, str]) -> tuple[int, int, str]:
    value, _ = item
    match = re.match(r"^gpt-(\d+)(?:\.(\d+))?", value, re.IGNORECASE)
    if match:
        major = -int(match.group(1))
        minor = -int(match.group(2) or 0)
        return (major, minor, value)
    return (99, 0, value)


def _model_entries(pairs: list[tuple[str, str]]) -> list[dict[str, Any]]:
    seen: set[str] = set()
    entries: list[dict[str, Any]] = []
    for value, label in pairs:
        model = str(value or "").strip()
        if not model or model in seen:
            continue
        seen.add(model)
        entries.append({"value": model, "label": str(label or model).strip() or model})
    return entries


def _codex_catalog_entries(payload: dict[str, Any]) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for item in payload.get("models", []) if isinstance(payload.get("models"), list) else []:
        if not isinstance(item, dict) or str(item.get("visibility") or "list") != "list":
            continue
        value = str(item.get("slug") or "").strip()
        if not value:
            continue
        reasoning = [
            str(level.get("effort") or "").strip()
            for level in item.get("supported_reasoning_levels", [])
            if isinstance(level, dict) and str(level.get("effort") or "").strip() in ALLOWED_CODEX_REASONING_EFFORTS
        ]
        entry: dict[str, Any] = {
            "value": value,
            "label": str(item.get("display_name") or _format_codex_model_label(value)).strip(),
        }
        if reasoning:
            entry["reasoning_efforts"] = reasoning
        entries.append(entry)
    return entries


def _compatible_codex_catalog_entries(
    remote_payload: dict[str, Any],
    bundled_payload: dict[str, Any],
) -> list[dict[str, Any]]:
    """Return models advertised remotely and supported by this Codex binary."""
    remote = _codex_catalog_entries(remote_payload)
    # `visibility` is a remote presentation decision.  A bundled entry hidden
    # from the local picker still proves that this binary knows how to execute
    # the slug, so intersect remote-visible slugs with every bundled slug.
    bundled_values = {
        str(item.get("slug") or "").strip()
        for item in bundled_payload.get("models", [])
        if isinstance(item, dict) and str(item.get("slug") or "").strip()
    }
    return [item for item in remote if item["value"] in bundled_values]


def _claude_alias_pairs(env: dict[str, str], help_text: str = "") -> list[tuple[str, str]]:
    # `default` delegates selection to Claude Code.  Every other alias must be
    # declared by this installed CLI or backed by an explicit environment
    # mapping; static future-facing aliases become stale surprisingly quickly.
    pairs = [("default", "Claude default")]
    pairs.extend(_parse_claude_models_from_help(help_text))
    pairs.extend(_claude_configured_model_pairs(env))
    return pairs


def _claude_cli_model_entries(output: str) -> list[dict[str, Any]] | None:
    """Read the same initialization models used by Agent SDK supportedModels()."""
    for line in output.splitlines():
        try:
            event = json.loads(line)
        except (ValueError, TypeError):
            continue
        if not isinstance(event, dict) or event.get("type") != "control_response":
            continue
        response = event.get("response", {})
        if not isinstance(response, dict) or response.get("request_id") != "coauto_models" or response.get("subtype") != "success":
            continue
        payload = response.get("response", {})
        rows = payload.get("models") if isinstance(payload, dict) else None
        if not isinstance(rows, list):
            continue
        entries = []
        for row in rows:
            if not isinstance(row, dict) or not str(row.get("value") or "").strip():
                continue
            value = row["value"].strip()
            resolved = str(row.get("resolvedModel") or "").strip()
            label = _format_claude_model_label(resolved) if resolved else str(row.get("displayName") or value)
            if value == "default":
                label = f"Default ({label})"
            entry = {"value": value, "label": label, "resolved_model": resolved}
            if isinstance(row.get("supportedEffortLevels"), list):
                entry["reasoning_efforts"] = [level for level in row["supportedEffortLevels"] if level in {"low", "medium", "high", "xhigh", "max"}]
            elif not row.get("supportsEffort"):
                entry["reasoning_efforts"] = []
            entries.append(entry)
        return entries
    return None


def _claude_configured_model_pairs(env: dict[str, str]) -> list[tuple[str, str]]:
    pairs: list[tuple[str, str]] = []
    for key, alias, label in (
        ("ANTHROPIC_DEFAULT_FABLE_MODEL", "fable", "Configured Fable model"),
        ("ANTHROPIC_DEFAULT_OPUS_MODEL", "opus", "Configured Opus model"),
        ("ANTHROPIC_DEFAULT_SONNET_MODEL", "sonnet", "Configured Sonnet model"),
        ("ANTHROPIC_DEFAULT_HAIKU_MODEL", "haiku", "Configured Haiku model"),
    ):
        value = str(env.get(key) or "").strip()
        if value:
            pairs.append((alias, f"Claude {alias.capitalize()} ({value})"))
            pairs.append((value, f"{_format_claude_model_label(value)} ({label})"))
    configured_default = str(env.get("ANTHROPIC_MODEL") or "").strip()
    if configured_default:
        pairs.append((configured_default, f"{_format_claude_model_label(configured_default)} (Configured Claude model)"))
    custom = str(env.get("ANTHROPIC_CUSTOM_MODEL_OPTION") or "").strip()
    if custom:
        pairs.append((custom, str(env.get("ANTHROPIC_CUSTOM_MODEL_OPTION_NAME") or _format_claude_model_label(custom))))
    return pairs


def _claude_models_url(base_url: str) -> str:
    base = str(base_url or "https://api.anthropic.com").strip().rstrip("/")
    parsed = urlparse(base)
    if parsed.scheme not in {"http", "https"} or not parsed.netloc:
        raise ValueError("Anthropic model discovery requires an http(s) base URL.")
    suffix = "/models" if parsed.path.rstrip("/").endswith("/v1") else "/v1/models"
    return f"{base}{suffix}?limit=1000"


def _claude_reasoning_efforts_from_api_model(item: dict[str, Any]) -> list[str] | None:
    capabilities = item.get("capabilities")
    if not isinstance(capabilities, dict) or "effort" not in capabilities:
        return None
    effort = capabilities.get("effort")
    if effort in (False, None):
        return []
    candidates: Any = effort
    if isinstance(effort, dict):
        ordered_levels = ("low", "medium", "high", "xhigh", "max")
        if any(level in effort for level in ordered_levels):
            return [
                level
                for level in ordered_levels
                if effort.get(level) is True
                or (isinstance(effort.get(level), dict) and effort[level].get("supported") is True)
            ]
        if effort.get("supported") is False:
            return []
        candidates = next(
            (
                effort.get(key)
                for key in ("levels", "values", "choices", "supported_values", "supported_levels")
                if isinstance(effort.get(key), (list, tuple, set, str))
            ),
            [],
        )
        if not candidates and effort.get("supported") is True:
            return None
    elif effort is True:
        return None
    if isinstance(candidates, str):
        candidates = re.split(r"[,\s]+", candidates)
    if not isinstance(candidates, (list, tuple, set)):
        return []
    allowed = {"low", "medium", "high", "xhigh", "max"}
    return list(dict.fromkeys(str(value or "").strip() for value in candidates if str(value or "").strip() in allowed))


def _discover_claude_api_models(env: dict[str, str]) -> list[dict[str, Any]]:
    headers = {"accept": "application/json", "anthropic-version": "2023-06-01"}
    api_key = str(env.get("ANTHROPIC_API_KEY") or "").strip()
    auth_token = str(env.get("ANTHROPIC_AUTH_TOKEN") or "").strip()
    oauth_token = str(env.get("CLAUDE_CODE_OAUTH_TOKEN") or "").strip()
    if auth_token:
        headers["authorization"] = f"Bearer {auth_token}"
    elif api_key:
        headers["x-api-key"] = api_key
    elif oauth_token:
        headers["authorization"] = f"Bearer {oauth_token}"
    request = Request(_claude_models_url(str(env.get("ANTHROPIC_BASE_URL") or "")), headers=headers)
    try:
        with urlopen(request, timeout=8.0) as response:
            body = response.read(AGENT_MODELS_RESPONSE_MAX_BYTES + 1)
    except HTTPError as exc:
        raise RuntimeError(f"Model endpoint returned HTTP {exc.code}.") from exc
    except (URLError, TimeoutError, OSError) as exc:
        raise RuntimeError(f"Model endpoint could not be reached: {exc}.") from exc
    if len(body) > AGENT_MODELS_RESPONSE_MAX_BYTES:
        raise RuntimeError("Model endpoint response is too large.")
    try:
        payload = json.loads(body.decode("utf-8"))
    except (UnicodeDecodeError, json.JSONDecodeError) as exc:
        raise RuntimeError("Model endpoint did not return valid JSON.") from exc
    rows = payload.get("data", []) if isinstance(payload, dict) else []
    entries: list[dict[str, Any]] = []
    seen: set[str] = set()
    for item in rows:
        if not isinstance(item, dict):
            continue
        value = str(item.get("id") or "").strip()
        if not value or value in seen:
            continue
        seen.add(value)
        entry: dict[str, Any] = {
            "value": value,
            "label": str(item.get("display_name") or value).strip() or value,
        }
        efforts = _claude_reasoning_efforts_from_api_model(item)
        if efforts is not None:
            entry["reasoning_efforts"] = efforts
        entries.append(entry)
    return entries


def _agent_models_cache_key(backend: str, executable: str, settings: dict[str, Any], env: dict[str, str]) -> str:
    provider = normalize_claude_provider(settings.get("provider")) if backend == "claude" else normalize_codex_provider(settings.get("provider"))
    sensitive_context = "\0".join(
        str(env.get(key) or "")
        for key in ("OPENAI_API_KEY", "ANTHROPIC_API_KEY", "ANTHROPIC_AUTH_TOKEN", "CLAUDE_CODE_OAUTH_TOKEN")
    )
    context_hash = hashlib.sha256(sensitive_context.encode("utf-8")).hexdigest()[:12]
    pre_exec_hash = hashlib.sha1(pre_exec_script_for_settings(settings).encode("utf-8")).hexdigest()[:12]
    base_url = str(env.get("ANTHROPIC_BASE_URL") or "") if backend == "claude" else ""
    return f"{current_ui_settings_path()}::{backend}::{provider}::{executable}::{base_url}::{context_hash}::{pre_exec_hash}"


def agent_available_models(
    backend: str,
    env: dict[str, str] | None = None,
    settings: dict[str, Any] | None = None,
    force_refresh: bool = False,
) -> dict[str, Any]:
    backend = normalize_agent_backend(backend)
    probe_settings = agent_settings_for_probe(backend, settings)
    process_env = env if env is not None else agent_process_env(backend, probe_settings)
    try:
        executable = resolve_agent_executable(backend, process_env)
    except FileNotFoundError as exc:
        return {
            "backend": backend,
            "provider": normalize_claude_provider(probe_settings.get("provider")) if backend == "claude" else normalize_codex_provider(probe_settings.get("provider")),
            "source": "unavailable",
            "models": [],
            "probe_error": str(exc),
            "executable": "",
            "authoritative": False,
            "stale": False,
            "cached": False,
        }
    cache_key = _agent_models_cache_key(backend, executable, probe_settings, process_env)
    cached = _AGENT_MODELS_CACHE.get(cache_key)
    age = time.monotonic() - float(cached.get("cached_at", 0)) if cached else float("inf")
    if cached and not force_refresh and age < AGENT_MODELS_CACHE_TTL_SECONDS:
        return {**cached["result"], "cached": True, "stale": False, "cache_age_seconds": round(age, 3)}

    provider = normalize_claude_provider(probe_settings.get("provider")) if backend == "claude" else normalize_codex_provider(probe_settings.get("provider"))
    probe_error = ""
    authoritative = False
    if backend == "codex":
        catalog_probe = run_agent_probe(backend, executable, ["debug", "models"], process_env, timeout=15.0, settings=probe_settings)
        catalog = _json_object_from_probe_output(str(catalog_probe.get("output") or "")) if catalog_probe.get("ok") else None
        bundled_probe = run_agent_probe(backend, executable, ["debug", "models", "--bundled"], process_env, timeout=8.0, settings=probe_settings)
        bundled_catalog = _json_object_from_probe_output(str(bundled_probe.get("output") or "")) if bundled_probe.get("ok") else None
        authoritative = catalog is not None and bundled_catalog is not None
        models = _compatible_codex_catalog_entries(catalog, bundled_catalog) if authoritative else []
        source = "codex_cli_compatible" if authoritative else "unavailable"
        if not authoritative:
            failures: list[str] = []
            if catalog is None:
                failures.append("live catalog probe failed: " + str(catalog_probe.get("output") or catalog_probe.get("error") or "invalid JSON"))
            if bundled_catalog is None:
                failures.append("bundled catalog probe failed: " + str(bundled_probe.get("output") or bundled_probe.get("error") or "invalid JSON"))
            probe_error = "; ".join(failures)[:500]
    else:
        if provider == "external":
            # Initialization only: no user prompt, inference, or saved session.
            probe = run_agent_probe(
                backend, executable,
                ["-p", "--input-format", "stream-json", "--output-format", "stream-json", "--verbose", "--no-session-persistence", "--strict-mcp-config", '{"mcpServers":{}}'],
                process_env, timeout=6.0, settings=probe_settings,
                input_data=json.dumps({"type": "control_request", "request_id": "coauto_models", "request": {"subtype": "initialize"}}) + "\n",
            )
            models = _claude_cli_model_entries(str(probe.get("output") or "")) if probe.get("ok") else None
            authoritative = models is not None
            source = "claude_cli" if authoritative else "claude_cli_help"
            if models is None:
                help_probe = run_agent_probe(backend, executable, ["--help"], process_env, timeout=6.0, settings=probe_settings)
                help_text = str(help_probe.get("output") or "") if help_probe.get("ok") else ""
                models = _model_entries(_claude_alias_pairs(process_env, help_text))
                probe_error = "Could not load the Claude Code model picker. Update Claude Code and re-check; only declared aliases and configured models are shown."
        else:
            try:
                models = _discover_claude_api_models(process_env)
                source = "claude_api"
                authoritative = True
            except (RuntimeError, ValueError) as exc:
                # A gateway without a working /v1/models endpoint cannot prove
                # arbitrary aliases.  Expose only mappings the operator has
                # explicitly configured and mark the result non-authoritative.
                models = _model_entries(_claude_configured_model_pairs(process_env))
                source = "claude_configured" if models else "unavailable"
                probe_error = str(exc)

    result = {
        "backend": backend,
        "provider": provider,
        "source": source,
        "models": models,
        "probe_error": probe_error or None,
        "executable": executable,
        "refreshed_at": now_iso(),
        "cached": False,
        "authoritative": authoritative,
        "stale": False,
    }
    # Never revive stale options after a failed refresh.  Successful catalogs
    # and stable external-CLI declarations may still use the short TTL cache.
    if authoritative or (backend == "claude" and provider == "external" and not probe_error):
        _AGENT_MODELS_CACHE[cache_key] = {"cached_at": time.monotonic(), "result": result}
    return result


def agent_backend_status_payload(
    selected_backend: Any = "", settings: dict[str, Any] | None = None
) -> dict[str, Any]:
    selected = normalize_agent_backend(selected_backend or selected_agent_backend_from_env())
    statuses = {
        backend: agent_setup_status(backend, settings=settings)
        for backend in sorted(ALLOWED_AGENT_BACKENDS)
    }
    env_override = valid_agent_backend_from_env()
    env_override_raw = raw_agent_backend_from_env()
    return {
        "selected": selected,
        "env_override": env_override,
        "env_override_raw": env_override_raw,
        "env_warning": agent_backend_env_warning(),
        "backends": statuses,
    }


def agent_unavailable_message(status: dict[str, Any], statuses: dict[str, Any] | None = None) -> str:
    message = str(status.get("message") or "").strip() or agent_setup_instruction(status.get("backend", "codex"), "missing")
    backend = normalize_agent_backend(status.get("backend"))
    all_statuses = statuses or {}
    for other_backend, other_status in all_statuses.items():
        normalized_other = normalize_agent_backend(other_backend)
        if normalized_other == backend:
            continue
        if isinstance(other_status, dict) and other_status.get("ok") and not other_status.get("blocking"):
            message += f" {agent_display_name(normalized_other)} is available; select it in Settings if you want to use it."
            break
    return message


def claude_permission_mode_from_settings(settings: dict[str, Any] | None = None) -> str:
    preset = infer_claude_permission_preset(settings or {})
    return CLAUDE_PERMISSION_PRESETS[preset]["permissionMode"]


def claude_permission_modes_from_help(help_text: str) -> set[str]:
    text = str(help_text or "")
    marker = "--permission-mode"
    index = text.find(marker)
    if index < 0:
        return set()
    snippet = text[index:index + 800]
    modes = set(re.findall(r'"([^"]+)"', snippet))
    known_modes = {"acceptEdits", "auto", "bypassPermissions", "default", "manual", "dontAsk", "plan"}
    return modes & known_modes


def claude_permission_mode_status(settings: dict[str, Any] | None = None, env: dict[str, str] | None = None) -> dict[str, Any]:
    mode = claude_permission_mode_from_settings(settings)
    probe_settings = agent_settings_for_probe("claude", settings)
    process_env = env if env is not None else agent_process_env("claude", probe_settings)
    try:
        executable = resolve_agent_executable("claude", process_env)
    except FileNotFoundError as exc:
        return {"ok": False, "blocking": True, "mode": mode, "message": str(exc)}
    help_probe = run_agent_probe("claude", executable, ["--help"], process_env, settings=probe_settings)
    if not help_probe.get("ok"):
        return {
            "ok": True,
            "blocking": False,
            "mode": mode,
            "message": "Claude Code permission-mode support could not be probed; startup will continue.",
            "details": str(help_probe.get("output") or help_probe.get("error") or ""),
        }
    modes = claude_permission_modes_from_help(str(help_probe.get("output") or ""))
    if not modes or mode in modes:
        return {"ok": True, "blocking": False, "mode": mode, "supported_modes": sorted(modes)}
    return {
        "ok": False,
        "blocking": True,
        "mode": mode,
        "supported_modes": sorted(modes),
        "message": (
            f"Claude Code CLI does not support permission mode `{mode}`. "
            "Update Claude Code or choose a different permission preset in Settings."
        ),
    }


def ensure_selected_model_available(
    backend: str,
    settings: dict[str, Any] | None = None,
    env: dict[str, str] | None = None,
    force_refresh: bool = True,
) -> dict[str, Any]:
    """Validate model membership and advertised effort before launch.

    Codex fails closed unless both catalogs agree. Claude API catalogs are
    authoritative; external CLI aliases and failed-gateway fallbacks are
    limited to values the CLI or operator explicitly declared.
    """
    backend = normalize_agent_backend(backend)
    probe_settings = agent_settings_for_probe(backend, settings)
    process_env = env if env is not None else agent_process_env(backend, probe_settings)
    catalog = agent_available_models(
        backend,
        env=process_env,
        settings=probe_settings,
        force_refresh=force_refresh,
    )
    selected_model = (
        normalize_claude_model(probe_settings.get("model"))
        if backend == "claude"
        else normalize_codex_model(probe_settings.get("model"))
    )
    entries = {
        str(item.get("value") or "").strip(): item
        for item in catalog.get("models", [])
        if isinstance(item, dict) and str(item.get("value") or "").strip()
    }
    if not catalog.get("authoritative"):
        if backend == "codex":
            detail = str(catalog.get("probe_error") or "the live and bundled catalogs did not both return valid data")
            raise ValueError(
                "Codex model availability could not be verified, so the run was not started. "
                f"{detail}"
            )
        # Claude Code has no authoritative catalog command for external login.
        # It may run only aliases declared by the installed CLI (or explicit
        # environment mappings).  API/gateway failures follow the same rule:
        # only their explicit configured mappings remain eligible.
        if selected_model in entries:
            return catalog
        provider = normalize_claude_provider(probe_settings.get("provider"))
        detail = str(catalog.get("probe_error") or "no provider catalog or explicit mapping was available")
        raise ValueError(
            f"Claude Code model `{selected_model}` could not be verified for provider `{provider}`, so the run was not started. "
            f"{detail}"
        )

    if selected_model not in entries:
        available = ", ".join(entries) or "none"
        raise ValueError(
            f"{agent_display_name(backend)} model `{selected_model}` is not available for the selected provider "
            f"and installed CLI. Available models: {available}. Refresh Settings and choose an available model."
        )

    entry = entries[selected_model]
    requested_effort = str(probe_settings.get("reasoningEffort") or "").strip()
    if requested_effort and "reasoning_efforts" in entry:
        supported_efforts = [str(value) for value in entry.get("reasoning_efforts", []) if str(value)]
        if requested_effort not in supported_efforts:
            supported = ", ".join(supported_efforts) or "none"
            raise ValueError(
                f"{agent_display_name(backend)} model `{selected_model}` does not support reasoning effort "
                f"`{requested_effort}`. Supported efforts: {supported}."
            )
    return catalog


def ensure_agent_ready(
    backend: str,
    env: dict[str, str] | None = None,
    settings: dict[str, Any] | None = None,
    force_refresh: bool = True,
) -> dict[str, Any]:
    backend = normalize_agent_backend(backend)
    selected = agent_setup_status(backend, env, settings)
    if selected.get("blocking"):
        statuses = {backend: selected}
        for name in sorted(ALLOWED_AGENT_BACKENDS - {backend}):
            statuses[name] = agent_setup_status(name)
        raise ValueError(agent_unavailable_message(selected, statuses))
    if backend == "claude":
        permission_status = claude_permission_mode_status(settings, env)
        if permission_status.get("blocking"):
            message = str(permission_status.get("message") or "Claude Code permission mode is not supported.")
            other = agent_setup_status("codex")
            if isinstance(other, dict) and other.get("ok") and not other.get("blocking"):
                message += " Codex is available; select it in Settings if you want to use it."
            raise ValueError(message)
    ensure_selected_model_available(backend, settings=settings, env=env, force_refresh=force_refresh)
    return selected


def valid_review_context(value: Any) -> dict[str, str]:
    if not isinstance(value, dict):
        return {}
    trial_id, stage_id = value.get("trial_id"), value.get("stage_id")
    if not v2_valid_id("trial", trial_id) or not v2_valid_id("stage", stage_id):
        return {}
    if not stage_id.startswith(f"STAGE-{trial_id[:6]}-"):
        return {}
    return {"trial_id": trial_id, "stage_id": stage_id}


def transcript_with_review_context(entries: list[Any], contexts: Any = None) -> list[Any]:
    """Bind old entries only to an unambiguous service launch in the same run."""
    bindings = {
        str(key): context for key, value in (contexts.items() if isinstance(contexts, dict) else [])
        if (context := valid_review_context(value))
    }
    markers: dict[str, set[tuple[str, str]]] = {}
    for entry in entries:
        if not isinstance(entry, dict) or entry.get("raw_type") != "ui.v2_trial":
            continue
        run_id = str(entry.get("run_id") or "")
        if not re.fullmatch(r"S[0-9]{8}_[0-9]{6}_v2_trial(?:_[a-f0-9]{8})?", run_id):
            continue
        if entry.get("role") != "user" or entry.get("kind") != "user" or entry.get("title") != "User" or entry.get("editable") is not False:
            continue
        match = re.fullmatch(r"V2 (?:plan|prepare|repair|review): ([^ /]+) / ([^ /]+)", str(entry.get("content") or ""))
        if not match:
            continue
        context = valid_review_context({"trial_id": match[1], "stage_id": match[2]})
        if context:
            markers.setdefault(run_id, set()).add((context["trial_id"], context["stage_id"]))
    for run_id, values in markers.items():
        if run_id not in bindings and len(values) == 1:
            trial_id, stage_id = next(iter(values))
            bindings[run_id] = {"trial_id": trial_id, "stage_id": stage_id}
    projected = []
    for entry in entries:
        if not isinstance(entry, dict):
            projected.append(entry)
            continue
        item = dict(entry)
        context = valid_review_context(item.get("review_context")) or bindings.get(str(item.get("run_id") or ""))
        item.pop("review_context", None)
        if context:
            item["review_context"] = dict(context)
        projected.append(item)
    return projected


def transcript_entry(role: str, kind: str, title: str, content: str, raw_type: str = "", editable: bool = False, *, run_id: str = "") -> dict[str, Any]:
    run_id = run_id or str(RESEARCH_SESSION.get("id") or "")
    entry = {
        "id": f"T{now_id()}_{len(RESEARCH_SESSION.get('transcript', [])) + 1:04d}",
        "role": role,
        "kind": kind,
        "title": title,
        "content": str(content or "").strip(),
        "raw_type": raw_type,
        "editable": editable,
        "created_at": now_iso(),
        "iteration": int(RESEARCH_SESSION.get("loop_iteration") or 0),
        "run_id": run_id,
    }
    contexts = RESEARCH_SESSION.get("review_contexts")
    context = valid_review_context(contexts.get(run_id)) if isinstance(contexts, dict) else {}
    if context:
        entry["review_context"] = context
    return entry


def append_transcript(role: str, kind: str, title: str, content: str, raw_type: str = "", editable: bool = False) -> None:
    text = str(content or "").strip()
    if not text:
        return
    with RESEARCH_LOCK:
        RESEARCH_SESSION["transcript"].append(transcript_entry(role, kind, title, text, raw_type, editable))
        trim_transcript_locked()
    persist_research_session()


def event_payload_text(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value.strip()
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, list):
        parts = [event_payload_text(item) for item in value]
        return "\n".join(part for part in parts if part).strip()
    if isinstance(value, dict):
        for key in ("text", "message", "summary", "content", "output", "result", "success", "error", "stdout", "stderr"):
            text = event_payload_text(value.get(key))
            if text:
                return text
        if "command" in value:
            command = value.get("command")
            if isinstance(command, list):
                return " ".join(str(part) for part in command)
            return str(command)
        parts = [event_payload_text(item) for item in value.values()]
        return "\n".join(part for part in parts if part).strip()
    return ""


def codex_web_search_query(value: Any) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        text = compact_single_line(value, 260)
        lowered = text.lower()
        if (
            not text
            or text.startswith("ws_")
            or lowered in {"web_search", "web_search_call", "completed", "in_progress", "queued"}
            or re.match(r"^(?:item|turn|response|session)[._/-]", lowered)
        ):
            return ""
        return text
    if isinstance(value, list):
        for item in value:
            text = codex_web_search_query(item)
            if text:
                return text
        return ""
    if isinstance(value, dict):
        for key in ("query", "search_query", "searchQuery", "q", "keywords", "search_terms", "searchTerms"):
            text = codex_web_search_query(value.get(key))
            if text:
                return text
        for key, item in value.items():
            if str(key).lower() in {"id", "call_id", "callid", "type", "kind", "name", "status", "method", "event", "role", "raw_type", "session_id", "run_id", "backend", "model", "usage"}:
                continue
            text = codex_web_search_query(item)
            if text:
                return text
    return ""


def codex_event_name(event: Any) -> str:
    if not isinstance(event, dict):
        return ""
    raw = str(event.get("method") or event.get("type") or event.get("event") or event.get("kind") or "")
    return re.sub(r"[\s._]+", "/", raw.strip().lower())


def codex_event_params(event: Any) -> dict[str, Any]:
    if not isinstance(event, dict):
        return {}
    params = event.get("params")
    return params if isinstance(params, dict) else event


def codex_event_item(event: Any) -> dict[str, Any]:
    if not isinstance(event, dict):
        return {}
    params = codex_event_params(event)
    item = params.get("item") if isinstance(params.get("item"), dict) else event.get("item")
    return item if isinstance(item, dict) else {}


def is_ignored_codex_lifecycle_event(event: Any) -> bool:
    if not isinstance(event, dict):
        return False
    if (
        "result" in event
        and "id" in event
        and not any(key in event for key in ("method", "type", "event", "kind"))
    ):
        return True
    raw_type = codex_event_name(event)
    if "delta" in raw_type:
        return True
    if raw_type.startswith(("account/", "remotecontrol/", "thread/")):
        return True
    if raw_type.startswith("mcpserver/") and "toolcall" not in raw_type:
        return True
    if raw_type.startswith("turn/"):
        payload = codex_event_params(event)
        has_result_text = any(
            key in payload or key in event
            for key in ("text", "message", "content", "output", "result", "success")
        )
        return not has_result_text
    if raw_type in {
        "thread/started",
        "turn/started",
        "thread/settings/updated",
        "thread/status/changed",
        "thread/tokenusage/updated",
        "thread/token-usage/updated",
        "thread/token_usage/updated",
        "thread/token/usage/updated",
        "account/ratelimits/updated",
        "account/rate-limits/updated",
        "account/rate_limits/updated",
        "account/rate/limits/updated",
        "mcpserver/startupstatus/updated",
        "mcpserver/startup-status/updated",
        "mcpserver/startup_status/updated",
        "mcpserver/startup/status/updated",
    }:
        return True
    item = codex_event_item(event)
    item_type = str(item.get("type") or item.get("kind") or item.get("role") or "").lower()
    if raw_type == "item/started":
        return True
    return raw_type == "item/completed" and item_type in {"reasoning", "agentmessage", "agent_message", "message", "plan", "usermessage", "user_message"}


def claude_event_label(event: Any) -> tuple[str, str, str, str]:
    if not isinstance(event, dict):
        return ("", "", "", "")
    event_type = str(event.get("type") or "event").strip() or "event"
    subtype = str(event.get("subtype") or "").strip()
    label = event_type if "." in event_type or not subtype else f"{event_type}.{subtype}"
    return event_type, subtype, label, label.lower()


def is_ignored_claude_lifecycle_event(event: Any) -> bool:
    if not isinstance(event, dict):
        return False
    nested = event.get("event") if isinstance(event.get("event"), dict) else event.get("raw_event") if isinstance(event.get("raw_event"), dict) else None
    if nested is not None and nested is not event:
        return is_ignored_claude_lifecycle_event(nested)
    event_type, subtype, _label, label_lower = claude_event_label(event)
    event_family = event_type.split(".", 1)[0].lower()
    if event_family == "system" and subtype == "init":
        return True
    return "delta" in label_lower or "partial" in label_lower


def should_suppress_agent_event_summary(line: str, backend: str) -> bool:
    try:
        event = json.loads(str(line or "").strip())
    except (json.JSONDecodeError, TypeError, ValueError):
        return False
    if normalize_agent_backend(backend) == "claude":
        return is_ignored_claude_lifecycle_event(event)
    return is_ignored_codex_lifecycle_event(event)


def transcript_from_codex_line(line: str) -> dict[str, Any] | None:
    stripped = line.strip()
    if not stripped:
        return None
    try:
        event = json.loads(stripped)
    except json.JSONDecodeError:
        if stripped.startswith("Started:"):
            return {"role": "command", "kind": "command", "title": "Agent command", "content": stripped.removeprefix("Started:").strip(), "raw_type": "process.started", "editable": False}
        if re.match(r"^(?:\d{4}-\d{2}-\d{2}T\S+\s+)?WARN(?:ING)?\b", stripped):
            return {"role": "tool", "kind": "warning", "title": "Runtime warning", "content": stripped, "raw_type": "process.message", "editable": False}
        if "error" in stripped.lower() or "failed" in stripped.lower():
            return {"role": "tool", "kind": "error", "title": "Runtime message", "content": stripped, "raw_type": "process.message", "editable": False}
        return None

    if not isinstance(event, dict):
        text = event_payload_text(event)
        if text and ("error" in text.lower() or "failed" in text.lower()):
            return {
                "role": "tool",
                "kind": "error",
                "title": "Runtime message",
                "content": text[:8000],
                "raw_type": "process.message",
                "editable": False,
            }
        return None

    raw_type = str(event.get("method") or event.get("type") or event.get("event") or event.get("kind") or "event")
    raw_type_lower = raw_type.lower()
    raw_type_key = codex_event_name(event)
    if raw_type_key in {"thread/started", "turn/started"}:
        return None
    if "delta" in raw_type_lower or raw_type_lower.endswith("/delta"):
        return None
    if raw_type_key == "turn/completed" and set(event.keys()).issubset({"type", "usage"}):
        return None

    item = codex_event_item(event)
    item_type = str(item.get("type") or item.get("kind") or item.get("role") or "").lower()
    type_text = f"{raw_type_lower} {item_type}".strip()
    completed_message = raw_type_key == "item/completed" and item_type in {"agentmessage", "agent_message", "message"}
    if is_ignored_codex_lifecycle_event(event) and not completed_message:
        return None
    if "web_search" in type_text or "websearch" in type_text:
        query = codex_web_search_query(item) or codex_web_search_query(event)
        content = f"Searching the web: {query}" if query else "Searching the web"
        return {"role": "tool", "kind": "tool", "title": "Web search", "content": content[:8000], "raw_type": raw_type, "editable": False}

    content_source: Any = item or event
    content = event_payload_text(content_source)
    if not content or content in {raw_type, item_type}:
        return None

    role = "assistant"
    kind = "assistant"
    title = "Assistant"
    editable = False

    if any(token in type_text for token in ("tool", "exec", "command", "shell", "patch", "file", "stdout", "stderr")):
        role = "tool"
        kind = "tool"
        title = "Tool"
    if raw_type_lower in {"turn.completed"} or any(token in type_text for token in ("final", "result")):
        role = "final"
        kind = "final"
        title = "Final"
    if "error" in type_text or "failed" in type_text:
        role = "tool"
        kind = "error"
        title = "Error"
    if "user" in type_text:
        role = "user"
        kind = "user"
        title = "User"
        editable = True
    if "assistant" in type_text or "agent" in type_text or "message" in type_text:
        if role not in {"user", "tool", "final"}:
            role = "assistant"
            kind = "assistant"
            title = "Assistant"

    return {"role": role, "kind": kind, "title": title, "content": content[:8000], "raw_type": raw_type, "editable": editable}


def claude_content_blocks(value: Any) -> list[dict[str, Any]]:
    if isinstance(value, dict):
        content = value.get("content")
        if isinstance(content, list):
            return [item for item in content if isinstance(item, dict)]
        if isinstance(content, dict):
            return [content]
    if isinstance(value, list):
        return [item for item in value if isinstance(item, dict)]
    return []


def claude_block_text(block: dict[str, Any]) -> str:
    block_type = str(block.get("type") or "").strip()
    if block_type == "text":
        return str(block.get("text") or "").strip()
    if block_type == "tool_use":
        name = str(block.get("name") or "tool").strip()
        tool_input = block.get("input")
        if isinstance(tool_input, (dict, list)):
            detail = json.dumps(tool_input, ensure_ascii=False)
        else:
            detail = str(tool_input or "").strip()
        return f"{name}: {detail}".strip()
    if block_type == "tool_result":
        content = event_payload_text(block.get("content"))
        return content or event_payload_text(block)
    return event_payload_text(block)


def claude_message_content_text(message: Any, include_tools: bool = True) -> str:
    blocks = claude_content_blocks(message)
    if blocks:
        parts = []
        for block in blocks:
            if not include_tools and str(block.get("type") or "") != "text":
                continue
            text = claude_block_text(block)
            if text:
                parts.append(text)
        return "\n".join(parts).strip()
    return event_payload_text(message)


def claude_message_has_tool_use(message: Any) -> bool:
    return any(str(block.get("type") or "") in {"tool_use", "tool_result"} for block in claude_content_blocks(message))


def claude_result_text(event: dict[str, Any]) -> str:
    for key in ("success", "result", "message", "content", "output", "text", "error"):
        text = event_payload_text(event.get(key))
        if text:
            return text
    return ""


def transcript_from_claude_line(line: str) -> dict[str, Any] | None:
    stripped = line.strip()
    if not stripped:
        return None
    try:
        event = json.loads(stripped)
    except json.JSONDecodeError:
        if "error" in stripped.lower() or "failed" in stripped.lower():
            return {"role": "tool", "kind": "error", "title": "Claude Code", "content": stripped, "raw_type": "process.message", "editable": False}
        return None
    if not isinstance(event, dict):
        return None

    event_type = str(event.get("type") or "event").strip() or "event"
    subtype = str(event.get("subtype") or "").strip()
    raw_type = event_type if "." in event_type or not subtype else f"{event_type}.{subtype}"
    raw_type_lower = raw_type.lower()
    event_family = event_type.split(".", 1)[0].lower()
    if raw_type_lower in {"system.init"}:
        return None
    if "delta" in raw_type_lower or "partial" in raw_type_lower:
        return None

    if event_family == "assistant":
        message = event.get("message") if isinstance(event.get("message"), dict) else event
        stop_reason = message.get("stop_reason") if isinstance(message, dict) else None
        if stop_reason in {None, ""} and not claude_message_has_tool_use(message):
            return None
        if claude_message_has_tool_use(message):
            content = claude_message_content_text(message)
            if not content:
                return None
            return {"role": "tool", "kind": "tool", "title": "Tool", "content": content[:8000], "raw_type": raw_type, "editable": False}
        content = claude_message_content_text(message, include_tools=False)
        if not content:
            return None
        return {"role": "assistant", "kind": "assistant", "title": "Assistant", "content": content[:8000], "raw_type": raw_type, "editable": False}

    if event_family == "user":
        message = event.get("message") if isinstance(event.get("message"), dict) else event
        if claude_message_has_tool_use(message):
            content = claude_message_content_text(message)
            if content:
                is_error = any(bool(block.get("is_error")) for block in claude_content_blocks(message))
                return {
                    "role": "tool",
                    "kind": "error" if is_error else "tool",
                    "title": "Tool result" if not is_error else "Tool error",
                    "content": content[:8000],
                    "raw_type": raw_type,
                    "editable": False,
                }
        return None

    if event_family == "result":
        is_error = bool(event.get("is_error")) or "error" in raw_type_lower or subtype == "error"
        content = claude_result_text(event)
        if not content:
            return None
        return {
            "role": "tool" if is_error else "final",
            "kind": "error" if is_error else "final",
            "title": "Error" if is_error else "Final",
            "content": content[:8000],
            "raw_type": raw_type,
            "editable": False,
        }

    if "error" in raw_type_lower or "failed" in raw_type_lower or "retry" in raw_type_lower:
        content = event_payload_text(event)
        if content:
            return {"role": "tool", "kind": "error" if "retry" not in raw_type_lower else "tool", "title": "Claude Code", "content": content[:8000], "raw_type": raw_type, "editable": False}
    return None


def transcript_from_agent_line(line: str, backend: str) -> dict[str, Any] | None:
    return transcript_from_claude_line(line) if normalize_agent_backend(backend) == "claude" else transcript_from_codex_line(line)


def transcript_dedupe_key(entry: dict[str, Any] | None) -> tuple[str, str, str, str]:
    if not isinstance(entry, dict):
        return ("", "", "", "")
    return (
        str(entry.get("role") or "").strip().lower(),
        str(entry.get("kind") or "").strip().lower(),
        str(entry.get("raw_type") or "").strip().lower(),
        compact_single_line(str(entry.get("content") or ""), 800),
    )


def research_event_session_patch(extra: dict[str, Any] | None = None) -> dict[str, Any]:
    with RESEARCH_LOCK:
        settings = RESEARCH_SESSION.get("settings") if isinstance(RESEARCH_SESSION.get("settings"), dict) else {}
        patch = {
            "session_id": str(RESEARCH_SESSION.get("session_id") or ""),
            "last_event_at": str(RESEARCH_SESSION.get("last_event_at") or ""),
            "last_event_summary": str(RESEARCH_SESSION.get("last_event_summary") or ""),
            "agent_notice": dict(RESEARCH_SESSION.get("agent_notice") if isinstance(RESEARCH_SESSION.get("agent_notice"), dict) else {}),
            "returncode": RESEARCH_SESSION.get("returncode"),
            "backend": normalize_agent_backend(RESEARCH_SESSION.get("backend") or settings.get("backend") or ""),
            "mode": str(RESEARCH_SESSION.get("mode") or ""),
            "status": str(RESEARCH_SESSION.get("status") or ""),
            "loop_iteration": int(RESEARCH_SESSION.get("loop_iteration") or 0),
            "run_settings": dict(RESEARCH_SESSION.get("run_settings") or {}),
        }
    if extra:
        patch.update(extra)
    return patch


def emit_research_event(kind: str, payload: dict[str, Any] | None = None) -> dict[str, Any]:
    context = current_project_context()
    payload = dict(payload or {})
    created_at = now_iso()
    with context.lock:
        session = context.session
        settings = session.get("settings") if isinstance(session.get("settings"), dict) else {}
        backend = normalize_agent_backend(session.get("backend") or settings.get("backend") or "")
        event = {
            "schema_version": 1,
            "event_id": 0,
            "kind": str(kind or "agent_event"),
            "project_id": context.id,
            "run_id": str(session.get("id") or ""),
            "backend": backend,
            "mode": str(session.get("mode") or ""),
            "status": str(session.get("status") or ""),
            "created_at": created_at,
            "session_patch": research_event_session_patch(),
        }
    event.update(payload)
    if not isinstance(event.get("session_patch"), dict):
        event["session_patch"] = research_event_session_patch()
    with context.research_event_condition:
        context.research_event_id += 1
        event["event_id"] = context.research_event_id
        context.research_events.append(event)
        if len(context.research_events) > RESEARCH_EVENT_BUFFER_MAX:
            context.research_events = context.research_events[-RESEARCH_EVENT_BUFFER_MAX:]
        context.research_event_condition.notify_all()
    return event


def emit_v2_semantic_phase(
    phase: str,
    status: str,
    message: str,
    details: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Append one redacted, schema-valid lifecycle event to the existing SSE stream."""

    context = current_project_context()
    with RESEARCH_LOCK:
        sequence = int(RESEARCH_SESSION.get("v2_trace_sequence") or 0) + 1
        RESEARCH_SESSION["v2_trace_sequence"] = sequence
        v2_state = RESEARCH_SESSION.get("v2") if isinstance(RESEARCH_SESSION.get("v2"), dict) else {}
        run_id = str(v2_state.get("run_id") or RESEARCH_SESSION.get("id") or "service")
        trial_id = str(v2_state.get("trial_id") or "") or None
    artifact = semantic_event(
        project_id=str(v2_state.get("project_id") or context.id),
        run_id=run_id,
        trial_id=trial_id,
        sequence=sequence,
        phase=phase,
        status=status,
        message=message,
        details=details,
    )
    envelope = semantic_envelope(artifact)
    persist_research_session()
    return emit_research_event(
        "semantic_trace",
        {
            "event_type": "semantic_trace",
            "stage": envelope["stage"],
            "message": envelope["message"],
            "semantic_trace": envelope["payload"],
        },
    )


def research_events_since(context: ProjectContext, since_id: int) -> list[dict[str, Any]]:
    with context.research_event_condition:
        return [dict(event) for event in context.research_events if int(event.get("event_id") or 0) > since_id]


def parse_research_event_since(value: Any) -> int:
    try:
        return max(0, int(str(value or "").strip()))
    except (TypeError, ValueError):
        return 0


def format_research_sse_event(event: dict[str, Any]) -> str:
    event_id = int(event.get("event_id") or 0)
    data = json.dumps(event, ensure_ascii=False)
    return f"id: {event_id}\nevent: research\ndata: {data}\n\n"


def stream_payload_value(payload: dict[str, Any], key: str) -> Any:
    if key in payload:
        return payload.get(key)
    key_lower = key.lower()
    for candidate, value in payload.items():
        if str(candidate).lower() == key_lower:
            return value
    return None


def stream_text_value(value: Any, keys: tuple[str, ...] = ()) -> str:
    if value is None:
        return ""
    if isinstance(value, str):
        return value
    if isinstance(value, (int, float, bool)):
        return str(value)
    if isinstance(value, list):
        return "".join(stream_text_value(item, keys) for item in value)
    if isinstance(value, dict):
        for key in keys:
            text = stream_text_value(stream_payload_value(value, key), keys)
            if text:
                return text
        for key in ("delta", "text_delta", "textDelta", "output_delta", "outputDelta", "summaryTextDelta", "content", "message", "item"):
            nested = stream_payload_value(value, key)
            if nested is value:
                continue
            text = stream_text_value(nested, keys)
            if text:
                return text
    return ""


def normalized_stream_method(value: Any) -> str:
    return re.sub(r"[\s._]+", "/", str(value or "").strip().lower())


def stream_item_identifier(*payloads: Any) -> str:
    for payload in payloads:
        if not isinstance(payload, dict):
            continue
        for key in ("itemId", "item_id", "blockId", "block_id", "id", "callId", "call_id", "index"):
            value = stream_payload_value(payload, key)
            if value is not None and str(value).strip() != "":
                return slugify(str(value), "active")
    return "active"


def streaming_update_from_codex_event(event: dict[str, Any]) -> dict[str, Any] | None:
    method = str(event.get("method") or event.get("type") or event.get("event") or event.get("kind") or "").strip()
    method_key = normalized_stream_method(method)
    if "plan/delta" in method_key:
        return None
    params = event.get("params") if isinstance(event.get("params"), dict) else event
    item = params.get("item") if isinstance(params.get("item"), dict) else event.get("item") if isinstance(event.get("item"), dict) else {}
    item_type = normalized_stream_method(item.get("type") or item.get("kind") or item.get("role") or "")
    type_blob = f"{method_key} {item_type}"
    item_id = stream_item_identifier(params, item, event)

    if (
        "agentmessage/delta" in method_key
        or "agent/message/delta" in method_key
        or ("delta" in method_key and ("agent/message" in type_blob or "agent_message" in type_blob or "message" in item_type))
    ):
        text = stream_text_value(params, ("delta", "text", "textDelta", "text_delta", "content"))
        if not text:
            return None
        return {
            "key": f"assistant:{item_id}",
            "family": "assistant",
            "role": "assistant",
            "kind": "assistant",
            "title": "Assistant",
            "text": text,
            "raw_type": method or "item.agentMessage.delta",
            "mode": "append",
        }

    if "reasoning" in type_blob and ("delta" in method_key or "summarytextdelta" in method_key):
        text = stream_text_value(params, ("delta", "summaryTextDelta", "text", "content"))
        if not text:
            return None
        return {
            "key": f"reasoning:{item_id}",
            "family": "reasoning",
            "role": "assistant",
            "kind": "reasoning",
            "title": "Reasoning",
            "text": text,
            "raw_type": method or "item.reasoning.summaryTextDelta",
            "mode": "append",
        }

    if (
        "commandexecution/outputdelta" in method_key
        or "command/execution/outputdelta" in method_key
        or "outputdelta" in method_key
        or ("delta" in method_key and any(token in type_blob for token in ("command", "exec", "stdout", "stderr", "tool")))
    ):
        text = stream_text_value(params, ("delta", "outputDelta", "output_delta", "output", "stdout", "stderr", "text", "content"))
        if not text:
            return None
        return {
            "key": f"tool:{item_id}",
            "family": "tool",
            "role": "tool",
            "kind": "tool",
            "title": "Tool",
            "text": text,
            "raw_type": method or "item.commandExecution.outputDelta",
            "mode": "append",
        }

    return None


def streaming_update_from_claude_event(event: dict[str, Any]) -> dict[str, Any] | None:
    nested = event.get("event") if isinstance(event.get("event"), dict) else event.get("raw_event") if isinstance(event.get("raw_event"), dict) else event
    if not isinstance(nested, dict):
        return None
    event_type = str(nested.get("type") or event.get("type") or "event").strip() or "event"
    subtype = str(nested.get("subtype") or event.get("subtype") or "").strip()
    raw_type = event_type if "." in event_type or not subtype else f"{event_type}.{subtype}"
    raw_type_lower = raw_type.lower()
    event_family = event_type.split(".", 1)[0].lower()

    if event_family == "content_block_delta":
        delta = nested.get("delta") if isinstance(nested.get("delta"), dict) else {}
        delta_type = str(delta.get("type") or "").strip().lower()
        index = stream_item_identifier({"index": nested.get("index", 0)})
        if delta_type == "text_delta":
            text = stream_text_value(delta, ("text",))
            family = "assistant"
            role = "assistant"
            kind = "assistant"
            title = "Assistant"
        elif "thinking" in delta_type:
            text = stream_text_value(delta, ("thinking", "text"))
            family = "reasoning"
            role = "assistant"
            kind = "reasoning"
            title = "Reasoning"
        elif delta_type == "input_json_delta":
            text = stream_text_value(delta, ("partial_json", "text"))
            family = "tool"
            role = "tool"
            kind = "tool"
            title = "Tool"
        else:
            return None
        if not text:
            return None
        return {
            "key": f"{family}:{index}",
            "family": family,
            "role": role,
            "kind": kind,
            "title": title,
            "text": text,
            "raw_type": raw_type,
            "mode": "append",
        }

    if "partial" in raw_type_lower or event_family == "assistant":
        message = nested.get("message") if isinstance(nested.get("message"), dict) else nested
        if not isinstance(message, dict):
            return None
        stop_reason = message.get("stop_reason")
        if stop_reason not in {None, ""} or claude_message_has_tool_use(message):
            return None
        text = claude_message_content_text(message, include_tools=False)
        if not text:
            return None
        return {
            "key": f"assistant:{stream_item_identifier(message, nested)}",
            "family": "assistant",
            "role": "assistant",
            "kind": "assistant",
            "title": "Assistant",
            "text": text,
            "raw_type": raw_type,
            "mode": "snapshot",
        }

    return None


def streaming_update_from_agent_line(line: str, backend: str) -> dict[str, Any] | None:
    stripped = line.strip()
    if not stripped:
        return None
    try:
        event = json.loads(stripped)
    except json.JSONDecodeError:
        return None
    if not isinstance(event, dict):
        return None
    return streaming_update_from_claude_event(event) if normalize_agent_backend(backend) == "claude" else streaming_update_from_codex_event(event)


def parsed_transcript_entry(parsed: dict[str, Any], entry_id: str = "", streaming: bool = False, created_at: str = "", *, run_id: str = "") -> dict[str, Any]:
    entry = transcript_entry(
        str(parsed.get("role") or "assistant"),
        str(parsed.get("kind") or "assistant"),
        str(parsed.get("title") or "Assistant"),
        str(parsed.get("content") or "")[:STREAMING_TRANSCRIPT_MAX_CHARS],
        str(parsed.get("raw_type") or ""),
        bool(parsed.get("editable")),
        run_id=run_id,
    )
    if entry_id:
        entry["id"] = entry_id
    if created_at:
        entry["created_at"] = created_at
    if streaming:
        entry["streaming"] = True
    elif "streaming" in entry:
        entry.pop("streaming", None)
    return entry


def compact_trace_payload_for_persistence(payload: Any) -> Any:
    if not isinstance(payload, dict):
        return payload
    compacted = dict(payload)
    ptype = str(compacted.get("type") or "")
    if ptype == "command":
        output = str(compacted.get("output") or "")
        if len(output) > 1200:
            compacted["output"] = "[trimmed persisted command output]\n" + output[-1200:]
    elif ptype == "tool_call":
        result = str(compacted.get("result") or "")
        if len(result) > 1200:
            compacted["result"] = "[trimmed persisted tool result]\n" + result[-1200:]
        args = compacted.get("args")
        if isinstance(args, str) and len(args) > 1200:
            compacted["args"] = args[:1200] + "\n[trimmed persisted args]"
    elif ptype == "file_change":
        changes = []
        for change in compacted.get("changes") if isinstance(compacted.get("changes"), list) else []:
            if not isinstance(change, dict):
                continue
            next_change = dict(change)
            diff = str(next_change.get("diff") or "")
            if diff:
                next_change["diff"] = ""
                next_change["truncated"] = True
                next_change["persisted_diff_trimmed"] = True
            changes.append(next_change)
        compacted["changes"] = changes
    return compacted


def trim_transcript_entries(entries: list[Any], cap: int = 600) -> list[Any]:
    kept = [entry for entry in entries[-cap:] if isinstance(entry, dict)]
    if len(kept) <= 360:
        return kept
    compact_count = max(0, len(kept) - 240)
    compacted: list[dict[str, Any]] = []
    for index, entry in enumerate(kept):
        if index >= compact_count or not isinstance(entry.get("payload"), dict):
            compacted.append(entry)
            continue
        next_entry = dict(entry)
        next_entry["payload"] = compact_trace_payload_for_persistence(next_entry.get("payload"))
        compacted.append(next_entry)
    return compacted


def trim_transcript_locked(cap: int = 600) -> None:
    RESEARCH_SESSION["transcript"] = trim_transcript_entries(list(RESEARCH_SESSION.get("transcript", [])), cap)
    contexts = RESEARCH_SESSION.get("review_contexts")
    if isinstance(contexts, dict):
        retained_runs = {entry.get("run_id") for entry in RESEARCH_SESSION["transcript"]}
        retained_runs.add(RESEARCH_SESSION.get("id"))
        RESEARCH_SESSION["review_contexts"] = {key: value for key, value in contexts.items() if key in retained_runs}


def trace_transcript_entry(update: dict[str, Any], run_id: str = "", entry_count: int = 0) -> dict[str, Any]:
    key = str(update.get("entry_key") or update.get("raw_type") or "trace")
    session_run_id = str(run_id or RESEARCH_SESSION.get("id") or "run")
    id_base = re.sub(r"[^A-Za-z0-9._-]+", "_", f"{session_run_id}_{key}").strip("._-")[:90] or "trace"
    digest = hashlib.sha1(f"{session_run_id}:{key}".encode("utf-8", "replace")).hexdigest()[:10]
    entry = parsed_transcript_entry(
        update,
        entry_id=f"T{id_base}_{digest}",
        streaming=bool(update.get("streaming")),
        run_id=session_run_id,
    )
    payload = update.get("payload")
    if isinstance(payload, dict):
        entry["payload"] = payload
    if update.get("streaming") is False:
        entry["streaming"] = False
    if not entry.get("content") and isinstance(payload, dict):
        entry["content"] = str(payload.get("type") or "trace")
    if not entry.get("content"):
        entry["content"] = f"Trace update {entry_count + 1}"
    return entry


def rich_trace_enabled(settings: Any) -> bool:
    if not isinstance(settings, dict):
        return True
    return settings.get("richTrace") is not False


def trace_read_repo_file(path: str) -> str | None:
    try:
        resolved = repo_path(path)
        if not resolved.exists() or not resolved.is_file():
            return None
        if resolved.stat().st_size > MAX_TEXT_BYTES:
            return None
        return resolved.read_text(encoding="utf-8", errors="replace")
    except (OSError, ValueError):
        return None


def make_research_trace_normalizer(backend: str, flavor: str, settings: dict[str, Any] | None = None) -> Any:
    if not rich_trace_enabled(settings):
        return None
    return make_trace_normalizer(backend, flavor, read_file=trace_read_repo_file)


def upsert_trace_updates_locked(updates: list[dict[str, Any]]) -> list[dict[str, Any]]:
    entries: list[dict[str, Any]] = []
    for update in updates:
        if not isinstance(update, dict):
            continue
        entry = trace_transcript_entry(update, entry_count=len(RESEARCH_SESSION.get("transcript", [])))
        entries.append(upsert_transcript_entry_locked(entry))
    return entries


def emit_trace_transcript_entries(entries: list[dict[str, Any]], session_patch: dict[str, Any], display: str = "") -> None:
    for index, entry in enumerate(entries):
        payload: dict[str, Any] = {"session_patch": session_patch, "transcript_entry": entry}
        if display and index == 0:
            payload["log"] = display
        emit_research_event("transcript", payload)


def append_trace_updates(updates: list[dict[str, Any]], display: str = "") -> list[dict[str, Any]]:
    if not updates:
        return []
    with RESEARCH_LOCK:
        entries = upsert_trace_updates_locked(updates)
        session_patch = research_event_session_patch()
    if entries:
        persist_research_session()
        emit_trace_transcript_entries(entries, session_patch, display)
    return entries


def upsert_transcript_entry_locked(entry: dict[str, Any]) -> dict[str, Any]:
    entry_id = str(entry.get("id") or "").strip()
    if not entry_id:
        RESEARCH_SESSION["transcript"].append(entry)
        trim_transcript_locked()
        return entry
    for index, existing in enumerate(RESEARCH_SESSION.get("transcript", [])):
        if str(existing.get("id") or "") == entry_id:
            merged = {**existing, **entry}
            if existing.get("created_at"):
                merged["created_at"] = existing["created_at"]
            if entry.get("streaming") is False:
                merged.pop("streaming", None)
            RESEARCH_SESSION["transcript"][index] = merged
            trim_transcript_locked()
            return merged
    RESEARCH_SESSION["transcript"].append(entry)
    trim_transcript_locked()
    return entry


def streaming_transcript_state_locked() -> dict[str, dict[str, Any]]:
    state = RESEARCH_SESSION.get("streaming_transcript")
    if not isinstance(state, dict):
        state = {}
        RESEARCH_SESSION["streaming_transcript"] = state
    return state


def upsert_streaming_transcript_locked(update: dict[str, Any]) -> dict[str, Any] | None:
    key = str(update.get("key") or "assistant:active")
    text = str(update.get("text") or "")
    state = streaming_transcript_state_locked()
    existing = state.get(key) if isinstance(state.get(key), dict) else None
    if not text and not existing:
        return None
    if not text.strip() and not existing:
        return None
    mode = str(update.get("mode") or "append")
    content = text if mode == "snapshot" else f"{existing.get('content', '') if existing else ''}{text}"
    content = content[:STREAMING_TRANSCRIPT_MAX_CHARS]
    if not content.strip():
        return None
    entry_id = str(existing.get("id") or "") if existing else f"T{now_id()}_stream_{len(RESEARCH_SESSION.get('transcript', [])) + 1:04d}"
    created_at = str(existing.get("created_at") or "") if existing else now_iso()
    parsed = {
        "role": update.get("role") or "assistant",
        "kind": update.get("kind") or "assistant",
        "title": update.get("title") or "Assistant",
        "content": content,
        "raw_type": update.get("raw_type") or "stream.delta",
        "editable": False,
    }
    entry = parsed_transcript_entry(parsed, entry_id=entry_id, streaming=True, created_at=created_at)
    entry = upsert_transcript_entry_locked(entry)
    state[key] = {
        "id": entry_id,
        "created_at": created_at,
        "content": content,
        "family": str(update.get("family") or update.get("kind") or "assistant"),
        "role": str(update.get("role") or "assistant"),
        "kind": str(update.get("kind") or "assistant"),
    }
    return entry


def finalize_streaming_transcript_locked(parsed: dict[str, Any]) -> dict[str, Any] | None:
    content = str(parsed.get("content") or "").strip()
    if not content:
        return None
    role = str(parsed.get("role") or "").strip().lower()
    kind = str(parsed.get("kind") or "").strip().lower()
    families: list[str] = []
    if role in {"assistant", "final"} or kind in {"assistant", "final"}:
        families.append("assistant")
    if role == "tool" or kind in {"tool", "error"}:
        families.append("tool")
    if kind == "reasoning":
        families.append("reasoning")
    state = streaming_transcript_state_locked()
    candidate_key = ""
    for key, item in state.items():
        if str(item.get("family") or "") in families:
            candidate_key = key
    if candidate_key:
        item = state.pop(candidate_key)
        entry = parsed_transcript_entry(parsed, entry_id=str(item.get("id") or ""), streaming=False, created_at=str(item.get("created_at") or ""))
        entry["streaming"] = False
        return upsert_transcript_entry_locked(entry)
    entry = parsed_transcript_entry(parsed)
    RESEARCH_SESSION["transcript"].append(entry)
    trim_transcript_locked()
    return entry


def finalize_active_streaming_transcripts_locked(interrupted: bool = False) -> list[dict[str, Any]]:
    state = RESEARCH_SESSION.get("streaming_transcript")
    finalized: list[dict[str, Any]] = []
    if isinstance(state, dict) and state:
        ids = {str(item.get("id") or "") for item in state.values() if isinstance(item, dict)}
        for index, entry in enumerate(RESEARCH_SESSION.get("transcript", [])):
            if str(entry.get("id") or "") in ids and entry.get("streaming"):
                next_entry = dict(entry)
                next_entry.pop("streaming", None)
                RESEARCH_SESSION["transcript"][index] = next_entry
                finalized.append(next_entry)
    for index, entry in enumerate(RESEARCH_SESSION.get("transcript", [])):
        if not isinstance(entry, dict) or not entry.get("streaming") or not isinstance(entry.get("payload"), dict):
            continue
        payload = dict(entry.get("payload") or {})
        status = str(payload.get("status") or "")
        if status in {"running", "in_progress"}:
            ptype = str(payload.get("type") or "")
            if ptype == "command":
                payload["status"] = "failed" if interrupted else "completed"
                if interrupted and not str(payload.get("output") or "").strip():
                    payload["output"] = "Interrupted by user."
            elif ptype == "tool_call":
                payload["status"] = "failed" if interrupted else "succeeded"
            elif ptype in {"file_change", "web_search"}:
                payload["status"] = "failed" if interrupted else "completed"
        next_entry = dict(entry)
        next_entry["payload"] = payload
        next_entry.pop("streaming", None)
        RESEARCH_SESSION["transcript"][index] = next_entry
        finalized.append(next_entry)
    RESEARCH_SESSION["streaming_transcript"] = {}
    trim_transcript_locked()
    return finalized


def backfill_claude_result_transcript_from_raw_logs() -> bool:
    with RESEARCH_LOCK:
        settings = RESEARCH_SESSION.get("settings") if isinstance(RESEARCH_SESSION.get("settings"), dict) else {}
        backend = normalize_agent_backend(RESEARCH_SESSION.get("backend") or settings.get("backend") or "")
        if backend != "claude":
            return False
        status = str(RESEARCH_SESSION.get("status") or "").strip().lower()
        if status in {"running", "stopping"}:
            return False
        raw_logs = list(RESEARCH_SESSION.get("raw_logs") or [])
        if not raw_logs:
            return False
        existing = {transcript_dedupe_key(item) for item in RESEARCH_SESSION.get("transcript", []) if isinstance(item, dict)}
        added = False
        for line in raw_logs:
            parsed = transcript_from_claude_line(str(line or ""))
            if not parsed:
                continue
            raw_type = str(parsed.get("raw_type") or "").strip().lower()
            role = str(parsed.get("role") or "").strip().lower()
            if role != "final" or (raw_type != "result" and not raw_type.startswith("result.")):
                continue
            key = transcript_dedupe_key(parsed)
            if key in existing:
                continue
            RESEARCH_SESSION["transcript"].append(transcript_entry(**parsed))
            trim_transcript_locked()
            existing.add(key)
            added = True
        return added


def backfill_trace_transcript_from_raw_logs() -> bool:
    with RESEARCH_LOCK:
        settings = RESEARCH_SESSION.get("settings") if isinstance(RESEARCH_SESSION.get("settings"), dict) else {}
        if not rich_trace_enabled(settings):
            return False
        status = str(RESEARCH_SESSION.get("status") or "").strip().lower()
        if status in {"running", "stopping"}:
            return False
        backend = normalize_agent_backend(RESEARCH_SESSION.get("backend") or settings.get("backend") or "")
        mode = str(RESEARCH_SESSION.get("mode") or "")
        returncode = RESEARCH_SESSION.get("returncode")
        raw_logs = list(RESEARCH_SESSION.get("raw_logs") or [])
        existing_ids = {str(entry.get("id") or "") for entry in RESEARCH_SESSION.get("transcript", []) if isinstance(entry, dict)}
    if not raw_logs:
        return False
    normalizer = make_research_trace_normalizer(backend, "app-server" if mode == "plan" else "exec", settings)
    if normalizer is None:
        return False
    updates: list[dict[str, Any]] = []
    for line in raw_logs:
        try:
            updates.extend(update for update in normalizer.feed(str(line or "")) if isinstance(update, dict) and isinstance(update.get("payload"), dict))
        except Exception:
            continue
    try:
        updates.extend(update for update in normalizer.finish(returncode) if isinstance(update, dict) and isinstance(update.get("payload"), dict))
    except Exception:
        pass
    if not updates:
        return False
    added = False
    with RESEARCH_LOCK:
        for update in updates:
            entry = trace_transcript_entry(update, entry_count=len(RESEARCH_SESSION.get("transcript", [])))
            if str(entry.get("id") or "") in existing_ids:
                continue
            upsert_transcript_entry_locked(entry)
            existing_ids.add(str(entry.get("id") or ""))
            added = True
    return added


def slugify(value: str, fallback: str = "item") -> str:
    value = re.sub(r"[^A-Za-z0-9._-]+", "_", value.strip()).strip("._-")
    return value[:80] or fallback


def repo_path(relative_path: str | Path) -> Path:
    text = str(relative_path).replace("\\", "/").lstrip("/")
    lexical_path = (REPO_ROOT / text).absolute()
    root = REPO_ROOT.resolve()
    try:
        lexical_path.relative_to(root)
    except ValueError as exc:
        raise ValueError("Path escapes repository root") from exc
    path = lexical_path.resolve()
    if path != root and root not in path.parents and not text.startswith("resources/"):
        raise ValueError("Path escapes repository root")
    return path


def repo_file_reference_candidates(reference: str | Path) -> list[str]:
    text = unquote(str(reference or "")).strip().strip("`'\"")
    text = re.sub(r"^file://", "", text, flags=re.IGNORECASE)
    text = text.replace("\\", "/").split("#", 1)[0].split("?", 1)[0].strip()
    if not text:
        return []

    candidates: list[str] = []

    def add(candidate: str) -> None:
        normalized = candidate.replace("\\", "/").strip().lstrip("/")
        normalized = re.sub(r"/+", "/", normalized)
        if normalized and normalized not in candidates:
            candidates.append(normalized)

    root = REPO_ROOT.resolve().as_posix().rstrip("/")
    if text == root:
        add(".")
    elif text.startswith(f"{root}/"):
        add(text[len(root) + 1 :])
    add(text)

    parts = [part for part in text.split("/") if part]
    for index in range(len(parts)):
        add("/".join(parts[index:]))

    basename = parts[-1] if parts else Path(text).name
    canonical_basename_paths = {
        "PROJECT.md": "PROJECT.md",
        "RESOURCE_MANIFEST.md": RESOURCE_MANIFEST_RELATIVE_PATH,
        "STATE.md": "research_trajectory/STATE.md",
        "CURRENT_FINDINGS.md": "research_trajectory/CURRENT_FINDINGS.md",
        "BLUEPRINT.md": "manuscript/BLUEPRINT.md",
        "FIGURE_SPECS.md": "manuscript/figures/FIGURE_SPECS.md",
    }
    if basename in canonical_basename_paths:
        add(canonical_basename_paths[basename])
    return candidates


def resolve_repo_file_reference(reference: str | Path, prefer_existing: bool = True) -> tuple[Path, str]:
    candidates = repo_file_reference_candidates(reference)
    if not candidates:
        raise ValueError("File path is required")
    first_valid: tuple[Path, str] | None = None
    first_error: Exception | None = None
    for candidate in candidates:
        try:
            path = repo_path(candidate)
        except ValueError as exc:
            if first_error is None:
                first_error = exc
            continue
        if first_valid is None:
            first_valid = (path, candidate)
        if not prefer_existing or path.exists():
            return path, rel_path(path) if path.exists() else candidate
    if first_valid is not None:
        return first_valid
    if first_error is not None:
        raise first_error
    raise ValueError("Path escapes repository root")


def rel_path(path: Path) -> str:
    root = REPO_ROOT.absolute()
    absolute = path if path.is_absolute() else REPO_ROOT / path
    try:
        return absolute.absolute().relative_to(root).as_posix()
    except ValueError:
        return absolute.resolve().relative_to(REPO_ROOT.resolve()).as_posix()


def path_exists(path: Path) -> bool:
    return path.exists() or path.is_symlink()


def remove_path(path: Path) -> None:
    if path.is_symlink() or path.is_file():
        path.unlink()
    elif path.is_dir():
        shutil.rmtree(path)


def hash_file(path: Path) -> str:
    digest = hashlib.sha256()
    try:
        with path.open("rb") as handle:
            for chunk in iter(lambda: handle.read(1024 * 1024), b""):
                digest.update(chunk)
    except OSError:
        return ""
    return digest.hexdigest()


def protected_path_signature(path: Path) -> dict[str, Any]:
    if not path_exists(path):
        return {"exists": False}
    if path.is_symlink():
        try:
            target = os.readlink(path)
        except OSError:
            target = ""
        return {"exists": True, "kind": "symlink", "target": target}
    if path.is_file():
        try:
            stat = path.stat()
        except OSError:
            return {"exists": False}
        return {"exists": True, "kind": "file", "size": stat.st_size, "hash": hash_file(path)}
    if path.is_dir():
        entries: list[dict[str, Any]] = []
        for child in sorted(path.rglob("*"), key=lambda item: item.as_posix()):
            relative = child.relative_to(path).as_posix()
            if child.is_symlink():
                try:
                    target = os.readlink(child)
                except OSError:
                    target = ""
                entries.append({"path": relative, "kind": "symlink", "target": target})
            elif child.is_file():
                try:
                    stat = child.stat()
                except OSError:
                    continue
                entries.append({"path": relative, "kind": "file", "size": stat.st_size, "hash": hash_file(child)})
            elif child.is_dir():
                entries.append({"path": relative, "kind": "dir"})
        return {"exists": True, "kind": "dir", "entries": entries}
    return {"exists": True, "kind": "other"}


def create_chat_protected_snapshot() -> dict[str, Any]:
    snapshot_id = f"{now_id()}_{uuid.uuid4().hex[:8]}"
    snapshot_root = RUNTIME_DIR / "chat_protected_snapshots" / snapshot_id
    files_root = snapshot_root / "files"
    entries: list[dict[str, Any]] = []
    snapshot_root.mkdir(parents=True, exist_ok=True)
    for relative in CHAT_PROTECTED_PATHS:
        source = repo_path(relative)
        entry = {
            "path": relative,
            "signature": protected_path_signature(source),
        }
        if path_exists(source):
            target = files_root / relative
            target.parent.mkdir(parents=True, exist_ok=True)
            if source.is_symlink() or source.is_file():
                shutil.copy2(source, target, follow_symlinks=False)
                ensure_path_user_writable(target)
            elif source.is_dir():
                shutil.copytree(source, target, symlinks=True)
                ensure_tree_user_writable(target)
        entries.append(entry)
    manifest = {"id": snapshot_id, "created_at": now_iso(), "protected_paths": entries}
    (snapshot_root / "MANIFEST.json").write_text(json.dumps(manifest, indent=2, ensure_ascii=False) + "\n", encoding="utf-8")
    return {"id": snapshot_id, "root": str(snapshot_root), "paths": list(CHAT_PROTECTED_PATHS)}


def restore_chat_protected_snapshot(snapshot: dict[str, Any] | None) -> list[str]:
    if not isinstance(snapshot, dict) or not snapshot.get("root"):
        return []
    snapshot_root = Path(str(snapshot["root"]))
    manifest_path = snapshot_root / "MANIFEST.json"
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return []
    entries = manifest.get("protected_paths")
    if not isinstance(entries, list):
        return []
    changed_paths: list[str] = []
    for entry in entries:
        if not isinstance(entry, dict):
            continue
        relative = str(entry.get("path") or "").strip()
        if not relative:
            continue
        source = repo_path(relative)
        before = entry.get("signature") if isinstance(entry.get("signature"), dict) else {"exists": False}
        if protected_path_signature(source) == before:
            continue
        backup = snapshot_root / "files" / relative
        if path_exists(source):
            ensure_existing_destination_user_writable(source)
            remove_path(source)
        if before.get("exists"):
            source.parent.mkdir(parents=True, exist_ok=True)
            if backup.is_symlink() or backup.is_file():
                shutil.copy2(backup, source, follow_symlinks=False)
                ensure_path_user_writable(source)
            elif backup.is_dir():
                shutil.copytree(backup, source, symlinks=True)
                ensure_tree_user_writable(source)
        changed_paths.append(relative)
    return changed_paths


def file_kind(path: Path) -> str:
    suffix = path.suffix.lower()
    if suffix in {".md", ".markdown"}:
        return "markdown"
    if suffix in {".html", ".htm"}:
        return "html"
    if suffix in {".json", ".ipynb"}:
        return "json"
    if suffix in {".jsonl"}:
        return "jsonl"
    if suffix == ".csv":
        return "csv"
    if suffix == ".tsv":
        return "tsv"
    if suffix in {".yaml", ".yml"}:
        return "yaml"
    if suffix in {".xml"}:
        return "xml"
    if suffix in IMAGE_PREVIEW_SUFFIXES:
        return "image"
    if suffix in PDF_PREVIEW_SUFFIXES:
        return "pdf"
    if suffix in OFFICE_PREVIEW_SUFFIXES:
        return suffix.lstrip(".")
    if suffix in TEXT_PREVIEW_SUFFIXES:
        return "text"
    return "binary"


def file_mime(path: Path) -> str:
    guessed, _ = mimetypes.guess_type(path.name)
    if guessed:
        return guessed
    kind = file_kind(path)
    if kind == "markdown":
        return "text/markdown; charset=utf-8"
    if kind in {"json", "jsonl"}:
        return "application/json; charset=utf-8"
    if kind == "csv":
        return "text/csv; charset=utf-8"
    if kind == "tsv":
        return "text/tab-separated-values; charset=utf-8"
    if kind in {"yaml", "text"}:
        return "text/plain; charset=utf-8"
    if kind == "xml":
        return "application/xml; charset=utf-8"
    return "application/octet-stream"


def file_content_disposition(filename: str, *, download: bool = False) -> str:
    fallback = re.sub(r'[^\x20-\x7e]|["\\]', "_", filename)
    disposition = "attachment" if download else "inline"
    return f'{disposition}; filename="{fallback}"; filename*=UTF-8\'\'{quote(filename, safe="")}'


def file_raw_url(relative_path: str) -> str:
    return f"/api/file/raw?project={quote(current_project_context().id)}&path={quote(relative_path)}"


def _xml_local_name(tag: str) -> str:
    return str(tag).rsplit("}", 1)[-1]


def _paragraph_texts(xml_bytes: bytes) -> list[str]:
    root = ET.fromstring(xml_bytes)
    paragraphs: list[str] = []
    for para in root.iter():
        if _xml_local_name(para.tag) != "p":
            continue
        parts: list[str] = []
        for node in para.iter():
            name = _xml_local_name(node.tag)
            if name in {"t", "instrText"} and node.text:
                parts.append(node.text)
            elif name == "tab":
                parts.append("\t")
            elif name == "br":
                parts.append("\n")
        text = "".join(parts).strip()
        if text:
            paragraphs.append(text)
    return paragraphs


def office_text_preview(path: Path, limit: int = MAX_TEXT_BYTES) -> tuple[str, bool]:
    suffix = path.suffix.lower()
    try:
        with zipfile.ZipFile(path) as archive:
            if suffix == ".docx":
                text = "\n".join(_paragraph_texts(archive.read("word/document.xml")))
            elif suffix == ".pptx":
                slide_names = sorted(name for name in archive.namelist() if re.match(r"ppt/slides/slide\d+\.xml$", name))
                blocks = []
                for index, name in enumerate(slide_names, start=1):
                    slide_text = "\n".join(_paragraph_texts(archive.read(name))).strip()
                    if slide_text:
                        blocks.append(f"Slide {index}\n{slide_text}")
                text = "\n\n".join(blocks)
            elif suffix == ".xlsx":
                shared: list[str] = []
                if "xl/sharedStrings.xml" in archive.namelist():
                    root = ET.fromstring(archive.read("xl/sharedStrings.xml"))
                    for item in root.iter():
                        if _xml_local_name(item.tag) != "si":
                            continue
                        value = "".join(node.text or "" for node in item.iter() if _xml_local_name(node.tag) == "t").strip()
                        shared.append(value)
                rows: list[str] = []
                sheet_names = sorted(name for name in archive.namelist() if re.match(r"xl/worksheets/sheet\d+\.xml$", name))
                for sheet_index, name in enumerate(sheet_names, start=1):
                    root = ET.fromstring(archive.read(name))
                    sheet_rows: list[str] = []
                    for row in root.iter():
                        if _xml_local_name(row.tag) != "row":
                            continue
                        values: list[str] = []
                        for cell in row:
                            if _xml_local_name(cell.tag) != "c":
                                continue
                            value_node = next((child for child in cell if _xml_local_name(child.tag) == "v"), None)
                            raw_value = value_node.text if value_node is not None and value_node.text is not None else ""
                            if cell.attrib.get("t") == "s" and raw_value.isdigit() and int(raw_value) < len(shared):
                                raw_value = shared[int(raw_value)]
                            values.append(raw_value)
                        if any(value.strip() for value in values):
                            sheet_rows.append("\t".join(values))
                    if sheet_rows:
                        rows.append(f"Sheet {sheet_index}\n" + "\n".join(sheet_rows))
                text = "\n\n".join(rows)
            else:
                text = ""
    except Exception as exc:
        text = f"Office preview unavailable: {exc}"
    text = text.strip() or "No extractable text found in this Office file."
    truncated = len(text) > limit
    if truncated:
        text = text[:limit] + "\n\n… (truncated)"
    return text, truncated


def is_checkpoint_manuscript_path(relative_path: str) -> bool:
    normalized = str(relative_path or "").replace("\\", "/").lstrip("/")
    return normalized.startswith("research_trajectory/checkpoints/") and "/manuscript/" in normalized


def read_text_file(relative_path: str, limit: int = MAX_TEXT_BYTES, *, exact: bool = False) -> dict[str, Any]:
    display_path = str(relative_path).replace("\\", "/").lstrip("/")
    try:
        if exact:
            path = repo_path(relative_path)
        else:
            path, display_path = resolve_repo_file_reference(relative_path)
    except ValueError as exc:
        return {"path": relative_path, "exists": False, "error": str(exc)}

    if not path.exists():
        return {"path": relative_path, "exists": False, "text": ""}
    if path.is_dir():
        return {"path": display_path, "exists": True, "is_dir": True, "text": ""}

    try:
        stat = path.stat()
        relative = display_path
        kind = file_kind(path)
        previewable = path.suffix.lower() in PREVIEWABLE_SUFFIXES
        root = REPO_ROOT.resolve()
        resolved = path.resolve()
        editable = (
            path.suffix.lower() in EDITABLE_SUFFIXES
            and (resolved == root or root in resolved.parents)
            and not is_checkpoint_manuscript_path(relative)
        )
        if kind in {"image", "pdf", "binary"}:
            return {
                "path": relative,
                "exists": True,
                "is_dir": False,
                "text": "",
                "truncated": False,
                "mtime": stat.st_mtime,
                "mtime_display": datetime.fromtimestamp(stat.st_mtime).astimezone().isoformat(timespec="seconds"),
                "size": stat.st_size,
                "kind": kind,
                "mime": file_mime(path),
                "editable": False,
                "previewable": previewable,
                "url": file_raw_url(relative),
            }

        if kind in {"docx", "xlsx", "pptx"}:
            text, truncated = office_text_preview(path, limit)
            return {
                "path": relative,
                "exists": True,
                "is_dir": False,
                "text": text,
                "truncated": truncated,
                "mtime": stat.st_mtime,
                "mtime_display": datetime.fromtimestamp(stat.st_mtime).astimezone().isoformat(timespec="seconds"),
                "size": stat.st_size,
                "kind": kind,
                "mime": file_mime(path),
                "editable": False,
                "previewable": previewable,
                "url": file_raw_url(relative),
            }

        raw = path.read_bytes()[: limit + 1]
        truncated = len(raw) > limit
        text = raw[:limit].decode("utf-8", errors="replace")
        return {
            "path": relative,
            "exists": True,
            "is_dir": False,
            "text": text,
            "truncated": truncated,
            "mtime": stat.st_mtime,
            "mtime_display": datetime.fromtimestamp(stat.st_mtime).astimezone().isoformat(timespec="seconds"),
            "size": stat.st_size,
            "kind": kind,
            "mime": file_mime(path),
            "editable": editable,
            "previewable": previewable,
            "url": file_raw_url(relative),
        }
    except OSError as exc:
        return {"path": relative_path, "exists": False, "error": str(exc), "text": ""}


def write_text_file(relative_path: str, text: str) -> dict[str, Any]:
    ensure_current_project_writeable()
    path = repo_path(relative_path)
    relative = rel_path(path)
    if is_checkpoint_manuscript_path(relative):
        raise ValueError("Checkpoint manuscript snapshots are read-only.")
    root = REPO_ROOT.resolve()
    resolved = path.resolve()
    if resolved != root and root not in resolved.parents:
        raise ValueError("Linked external resources are read-only in the UI.")
    if path.suffix.lower() not in EDITABLE_SUFFIXES:
        raise ValueError(f"Unsupported editable file type: {path.suffix or path.name}")
    encoded = text.encode("utf-8")
    if len(encoded) > MAX_TEXT_BYTES:
        raise ValueError(f"File is too large to save from the UI: {relative_path}")
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_bytes(encoded)
    return read_text_file(relative, exact=True)


def safe_read(path: Path, limit: int = MAX_TEXT_BYTES) -> str:
    try:
        raw = path.read_bytes()[: limit + 1]
    except OSError:
        return ""
    return raw[:limit].decode("utf-8", errors="replace")


CRITICAL_PATH_INCOMPLETE_STATUSES = {"open", "in_progress", "blocked_on_human"}


def normalize_cp_status(value: str) -> str:
    return str(value or "").strip().lower().replace("-", "_").replace(" ", "_")


def critical_path_state(state_text: str | None = None) -> dict[str, Any]:
    text = state_text if state_text is not None else (safe_read(RESEARCH_STATE_PATH) if RESEARCH_STATE_PATH.exists() else "")
    section = markdown_section(text, "Critical Path") if text else ""
    if not section:
        return {"exists": False, "items": [], "current_bottleneck": "", "incomplete": False, "blocked_on_human": []}
    items: list[dict[str, str]] = []
    for raw_line in section.splitlines():
        line = raw_line.strip()
        if not line.startswith("|") or re.match(r"^\|\s*-+", line):
            continue
        cells = [cell.strip() for cell in line.strip("|").split("|")]
        if len(cells) < 5 or cells[0].lower() == "id" or not re.match(r"^CP\d+\b", cells[0], re.IGNORECASE):
            continue
        items.append({
            "id": cells[0],
            "dependency": cells[1],
            "status": normalize_cp_status(cells[2]),
            "evidence": cells[3],
            "owner": cells[4],
        })
    current_bottleneck = regex_first_value(section, [r"^\s*Current bottleneck:\s*(.+?)\s*$"])
    consecutive_raw = regex_first_value(section, [r"^\s*Consecutive non-empirical trials:\s*(\d+)\s*$"])
    incomplete = any(item["status"] in CRITICAL_PATH_INCOMPLETE_STATUSES for item in items)
    blocked = [item for item in items if item["status"] == "blocked_on_human"]
    return {
        "exists": True,
        "items": items,
        "current_bottleneck": compact_single_line(current_bottleneck, 260),
        "consecutive_non_empirical_trials": int(consecutive_raw or 0),
        "incomplete": incomplete,
        "blocked_on_human": blocked,
    }


def critical_human_task_ids() -> set[str]:
    state = critical_path_state()
    if not state.get("exists"):
        return set()
    text = " ".join(
        [
            str(state.get("current_bottleneck") or ""),
            *[
                f"{item.get('id', '')} {item.get('dependency', '')} {item.get('evidence', '')}"
                for item in state.get("blocked_on_human") or []
                if isinstance(item, dict)
            ],
        ]
    )
    return {match.group(0) for match in re.finditer(r"\bHT\d{4,}\b", text)}


def trial_report_empirical_progress(trial_dir: Path) -> str:
    report_path = trial_dir / "REPORT.md"
    if not report_path.exists():
        return ""
    report = safe_read(report_path)
    value = regex_first_value(report, [r"^\s*Empirical progress:\s*`?(yes|no)`?\b"])
    return str(value or "").strip().lower()


def recent_non_empirical_stall() -> dict[str, Any]:
    threshold = 2
    cp = critical_path_state()
    if not cp.get("exists") or not cp.get("incomplete"):
        return {"stalled": False, "critical_path": cp, "trials": [], "threshold": threshold}
    trials = closed_active_trial_dirs()[-threshold:]
    if len(trials) < threshold:
        return {"stalled": False, "critical_path": cp, "trials": [rel_path(path) for path in trials], "threshold": threshold}
    statuses = [trial_report_empirical_progress(path) for path in trials]
    stalled = bool(statuses and all(status == "no" for status in statuses))
    return {
        "stalled": stalled,
        "critical_path": cp,
        "trials": [rel_path(path) for path in trials],
        "statuses": statuses,
        "threshold": threshold,
    }


