def aux_workspace_list(session_id: str, parsed: Any) -> dict[str, Any]:
    """List files/dirs in a session's workspace at the given relative path."""
    session = aux_manager().get(session_id)
    ws = session.workspace_dir
    query = parse_qs(parsed.query)
    rel = str(query.get("path", [""])[0] or "").strip()
    # Safety: prevent path traversal outside workspace
    target = (ws / rel).resolve() if rel else ws.resolve()
    try:
        target.relative_to(ws.resolve())
    except ValueError:
        return {"items": []}
    items: list[dict[str, Any]] = []
    if target.is_dir():
        try:
            for entry in sorted(target.iterdir(), key=lambda p: (not p.is_dir(), p.name.lower())):
                if entry.name.startswith(".") and entry.name not in (".", ".."):
                    continue
                items.append({
                    "name": entry.name,
                    "path": str(entry.relative_to(ws)),
                    "is_dir": entry.is_dir(),
                    "size": entry.stat().st_size if entry.is_file() else 0,
                })
        except OSError:
            pass
    return {"items": items}


def serve_aux_workspace_file(self: Any, session_id: str, parsed: Any) -> None:
    """Serve a file from a session's workspace for preview or download."""
    session = aux_manager().get(session_id)
    ws = session.workspace_dir
    query = parse_qs(parsed.query)
    rel = str(query.get("path", [""])[0] or "").strip()
    download = str(query.get("download", [""])[0]).strip().lower() in {"1", "true", "yes"}
    raw_inline = str(query.get("raw", [""])[0]).strip().lower() in {"1", "true", "yes"}
    if not rel:
        self.send_json({"ok": False, "error": "Missing path parameter"}, status=400)
        return
    target = (ws / rel).resolve()
    try:
        target.relative_to(ws.resolve())
    except ValueError:
        self.send_json({"ok": False, "error": "Forbidden"}, status=403)
        return
    if not target.exists() or not target.is_file():
        self.send_json({"ok": False, "error": "File not found"}, status=404)
        return
    content_type = file_mime(target)
    kind = file_kind(target)
    data = target.read_bytes()
    if download or raw_inline:
        self.send_response(200)
        self.send_header("Content-Type", content_type)
        self.send_header("Content-Disposition", file_content_disposition(target.name, download=download))
        self.send_header("Content-Length", str(len(data)))
        self.send_header("Cache-Control", "no-store")
        self.end_headers()
        self.wfile.write(data)
        return

    if kind in {"image", "pdf", "html"}:
        self.send_json({
            "ok": True,
            "name": target.name,
            "kind": kind,
            "content_type": content_type,
            "content": base64.b64encode(data).decode("ascii") if kind == "image" else "",
        })
        return
    if kind in {"docx", "xlsx", "pptx"}:
        text, truncated = office_text_preview(target, 100_000)
        self.send_json({
            "ok": True,
            "name": target.name,
            "kind": kind,
            "content_type": content_type,
            "content": text,
            "truncated": truncated,
        })
        return
    try:
        text = data.decode("utf-8")
        # Truncate very large files for preview
        if len(text) > 100_000:
            text = text[:100_000] + "\n\n… (truncated, file is larger than 100KB)"
        self.send_json({
            "ok": True,
            "name": target.name,
            "kind": kind,
            "content_type": content_type,
            "content": text,
        })
    except UnicodeDecodeError:
        self.send_json({
            "ok": True,
            "name": target.name,
            "kind": kind,
            "content_type": content_type,
            "content": "(binary file, use download instead)",
        })



def pre_exec_script_for_settings(settings: dict[str, Any]) -> str:
    return normalize_pre_exec_script(settings.get("preExecScript"))


def create_agent_pre_exec_wrapper(settings: dict[str, Any]) -> Path | None:
    script = pre_exec_script_for_settings(settings)
    if not script:
        return None
    if os.name == "nt":
        backend = normalize_agent_backend(settings.get("backend"))
        raise ValueError(
            f"Shell setup before {agent_display_name(backend)} is supported on macOS/Linux UI servers. "
            "On Windows, use Settings environment fields or start CoAutoResearch from a configured shell."
        )
    wrapper_dir = Path(os.fspath(RUNTIME_DIR)) / "agent-shell-setup"
    wrapper_dir.mkdir(parents=True, exist_ok=True)
    wrapper_path = wrapper_dir / f"agent_setup_{now_id()}_{uuid.uuid4().hex[:8]}.sh"
    wrapper_path.write_text(f"set -e\n{script}\nexec \"$@\"\n", encoding="utf-8")
    wrapper_path.chmod(stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR)
    return wrapper_path


def shell_for_pre_exec(env: dict[str, str]) -> str:
    path = env.get("PATH") or os.environ.get("PATH") or None
    return shutil.which("bash", path=path) or shutil.which("sh", path=path) or "/bin/sh"


def popen_command_for_agent(
    command: list[str],
    settings: dict[str, Any],
    env: dict[str, str],
    windows: bool | None = None,
) -> tuple[list[str], bool, Path | None]:
    wrapper_path = create_agent_pre_exec_wrapper(settings)
    if wrapper_path:
        return [shell_for_pre_exec(env), str(wrapper_path), *command], False, wrapper_path
    return windows_agent_command_argv(command, env, windows), False, None


def _windows_job_structures() -> tuple[Any, Any]:
    """Return the two Win32 Job Object structures used by this module."""

    import ctypes
    from ctypes import wintypes

    class IoCounters(ctypes.Structure):
        _fields_ = [
            ("ReadOperationCount", ctypes.c_ulonglong),
            ("WriteOperationCount", ctypes.c_ulonglong),
            ("OtherOperationCount", ctypes.c_ulonglong),
            ("ReadTransferCount", ctypes.c_ulonglong),
            ("WriteTransferCount", ctypes.c_ulonglong),
            ("OtherTransferCount", ctypes.c_ulonglong),
        ]

    class BasicLimitInformation(ctypes.Structure):
        _fields_ = [
            ("PerProcessUserTimeLimit", ctypes.c_longlong),
            ("PerJobUserTimeLimit", ctypes.c_longlong),
            ("LimitFlags", wintypes.DWORD),
            ("MinimumWorkingSetSize", ctypes.c_size_t),
            ("MaximumWorkingSetSize", ctypes.c_size_t),
            ("ActiveProcessLimit", wintypes.DWORD),
            ("Affinity", ctypes.c_size_t),
            ("PriorityClass", wintypes.DWORD),
            ("SchedulingClass", wintypes.DWORD),
        ]

    class ExtendedLimitInformation(ctypes.Structure):
        _fields_ = [
            ("BasicLimitInformation", BasicLimitInformation),
            ("IoInfo", IoCounters),
            ("ProcessMemoryLimit", ctypes.c_size_t),
            ("JobMemoryLimit", ctypes.c_size_t),
            ("PeakProcessMemoryUsed", ctypes.c_size_t),
            ("PeakJobMemoryUsed", ctypes.c_size_t),
        ]

    class BasicAccountingInformation(ctypes.Structure):
        _fields_ = [
            ("TotalUserTime", ctypes.c_longlong),
            ("TotalKernelTime", ctypes.c_longlong),
            ("ThisPeriodTotalUserTime", ctypes.c_longlong),
            ("ThisPeriodTotalKernelTime", ctypes.c_longlong),
            ("TotalPageFaultCount", wintypes.DWORD),
            ("TotalProcesses", wintypes.DWORD),
            ("ActiveProcesses", wintypes.DWORD),
            ("TotalTerminatedProcesses", wintypes.DWORD),
        ]

    return ExtendedLimitInformation, BasicAccountingInformation


def _windows_create_agent_job() -> int:
    import ctypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateJobObjectW.argtypes = [ctypes.c_void_p, ctypes.c_wchar_p]
    kernel32.CreateJobObjectW.restype = ctypes.c_void_p
    kernel32.SetInformationJobObject.argtypes = [
        ctypes.c_void_p,
        ctypes.c_int,
        ctypes.c_void_p,
        ctypes.c_uint,
    ]
    kernel32.SetInformationJobObject.restype = ctypes.c_int
    handle = kernel32.CreateJobObjectW(None, None)
    if not handle:
        raise ctypes.WinError(ctypes.get_last_error())
    extended_type, _accounting_type = _windows_job_structures()
    limits = extended_type()
    limits.BasicLimitInformation.LimitFlags = 0x00002000  # JOB_OBJECT_LIMIT_KILL_ON_JOB_CLOSE
    if not kernel32.SetInformationJobObject(
        handle, 9, ctypes.byref(limits), ctypes.sizeof(limits)
    ):
        error = ctypes.WinError(ctypes.get_last_error())
        _windows_close_handle(int(handle))
        raise error
    return int(handle)


def _windows_close_handle(handle: int) -> None:
    if not handle:
        return
    import ctypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CloseHandle.argtypes = [ctypes.c_void_p]
    kernel32.CloseHandle.restype = ctypes.c_int
    kernel32.CloseHandle(ctypes.c_void_p(handle))


def _windows_assign_process_to_job(job: int, proc: subprocess.Popen[str]) -> None:
    import ctypes

    process_handle = int(getattr(proc, "_handle", 0) or 0)
    if not process_handle:
        raise RuntimeError("Windows agent process handle is unavailable for Job Object binding.")
    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.AssignProcessToJobObject.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
    kernel32.AssignProcessToJobObject.restype = ctypes.c_int
    if not kernel32.AssignProcessToJobObject(
        ctypes.c_void_p(job), ctypes.c_void_p(process_handle)
    ):
        raise ctypes.WinError(ctypes.get_last_error())


def _windows_resume_suspended_process(pid: int) -> None:
    """Resume the initial thread only after its process is safely job-bound."""

    import ctypes
    from ctypes import wintypes

    class ThreadEntry32(ctypes.Structure):
        _fields_ = [
            ("dwSize", wintypes.DWORD),
            ("cntUsage", wintypes.DWORD),
            ("th32ThreadID", wintypes.DWORD),
            ("th32OwnerProcessID", wintypes.DWORD),
            ("tpBasePri", wintypes.LONG),
            ("tpDeltaPri", wintypes.LONG),
            ("dwFlags", wintypes.DWORD),
        ]

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.CreateToolhelp32Snapshot.argtypes = [wintypes.DWORD, wintypes.DWORD]
    kernel32.CreateToolhelp32Snapshot.restype = ctypes.c_void_p
    kernel32.Thread32First.argtypes = [ctypes.c_void_p, ctypes.POINTER(ThreadEntry32)]
    kernel32.Thread32First.restype = wintypes.BOOL
    kernel32.Thread32Next.argtypes = [ctypes.c_void_p, ctypes.POINTER(ThreadEntry32)]
    kernel32.Thread32Next.restype = wintypes.BOOL
    kernel32.OpenThread.argtypes = [wintypes.DWORD, wintypes.BOOL, wintypes.DWORD]
    kernel32.OpenThread.restype = ctypes.c_void_p
    kernel32.ResumeThread.argtypes = [ctypes.c_void_p]
    kernel32.ResumeThread.restype = wintypes.DWORD

    snapshot = kernel32.CreateToolhelp32Snapshot(0x00000004, 0)  # TH32CS_SNAPTHREAD
    if not snapshot or int(snapshot) == ctypes.c_void_p(-1).value:
        raise ctypes.WinError(ctypes.get_last_error())
    resumed = False
    try:
        entry = ThreadEntry32()
        entry.dwSize = ctypes.sizeof(entry)
        found = bool(kernel32.Thread32First(snapshot, ctypes.byref(entry)))
        while found:
            if int(entry.th32OwnerProcessID) == int(pid):
                thread_handle = kernel32.OpenThread(0x0002, False, entry.th32ThreadID)
                if not thread_handle:
                    raise ctypes.WinError(ctypes.get_last_error())
                try:
                    if kernel32.ResumeThread(thread_handle) == 0xFFFFFFFF:
                        raise ctypes.WinError(ctypes.get_last_error())
                    resumed = True
                finally:
                    _windows_close_handle(int(thread_handle))
                break
            found = bool(kernel32.Thread32Next(snapshot, ctypes.byref(entry)))
    finally:
        _windows_close_handle(int(snapshot))
    if not resumed:
        raise RuntimeError("Could not find the suspended Windows agent thread.")


def _windows_terminate_job(job: int) -> None:
    import ctypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.TerminateJobObject.argtypes = [ctypes.c_void_p, ctypes.c_uint]
    kernel32.TerminateJobObject.restype = ctypes.c_int
    if not kernel32.TerminateJobObject(ctypes.c_void_p(job), 1):
        raise ctypes.WinError(ctypes.get_last_error())


def _windows_job_active_process_count(job: int) -> int:
    import ctypes

    kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
    kernel32.QueryInformationJobObject.argtypes = [
        ctypes.c_void_p,
        ctypes.c_int,
        ctypes.c_void_p,
        ctypes.c_uint,
        ctypes.c_void_p,
    ]
    kernel32.QueryInformationJobObject.restype = ctypes.c_int
    _extended_type, accounting_type = _windows_job_structures()
    accounting = accounting_type()
    if not kernel32.QueryInformationJobObject(
        ctypes.c_void_p(job),
        1,
        ctypes.byref(accounting),
        ctypes.sizeof(accounting),
        None,
    ):
        raise ctypes.WinError(ctypes.get_last_error())
    return int(accounting.ActiveProcesses)


def _agent_spawn_kwargs(
    popen_kwargs: dict[str, Any], process_tree_id: str | None = None
) -> tuple[dict[str, Any], str]:
    """Seed cooperative descendants for crash-time process-table discovery."""

    tree_id = process_tree_id or uuid.uuid4().hex
    kwargs = dict(popen_kwargs)
    inherited = kwargs.get("env")
    environment = dict(os.environ if inherited is None else inherited)
    environment[PROCESS_TREE_ID_ENV] = tree_id
    kwargs["env"] = environment
    return kwargs, tree_id


def _spawn_windows_agent_process(
    command: Any, popen_kwargs: dict[str, Any]
) -> subprocess.Popen[str]:
    """Create a suspended process, bind its inheritable tree, then resume it."""

    job = _windows_create_agent_job()
    proc: subprocess.Popen[str] | None = None
    try:
        kwargs, tree_id = _agent_spawn_kwargs(popen_kwargs)
        kwargs.pop("start_new_session", None)
        kwargs["creationflags"] = int(kwargs.get("creationflags") or 0) | int(
            getattr(subprocess, "CREATE_SUSPENDED", 0x00000004)
        )
        proc = subprocess.Popen(command, **kwargs)
        _windows_assign_process_to_job(job, proc)
        setattr(proc, "_coauto_windows_job", job)
        setattr(proc, "_coauto_tree_lock", threading.RLock())
        setattr(proc, "_coauto_tree_drained", False)
        setattr(proc, "_coauto_process_tree_id", tree_id)
        _windows_resume_suspended_process(proc.pid)
        return proc
    except Exception:
        try:
            _windows_terminate_job(job)
        except Exception:
            pass
        if proc is not None:
            # AssignProcessToJobObject can fail while the new root is still
            # suspended.  Terminating the then-empty Job succeeds but does not
            # touch that unbound process, so always terminate the root handle.
            try:
                proc.kill()
            except Exception:
                pass
            try:
                proc.wait(timeout=1)
            except Exception:
                pass
        _windows_close_handle(job)
        raise


def spawn_agent_process(command: Any, **popen_kwargs: Any) -> subprocess.Popen[str]:
    """Launch in a POSIX process group or a kill-on-close Windows Job."""

    if os.name == "nt":
        return _spawn_windows_agent_process(command, popen_kwargs)
    kwargs, tree_id = _agent_spawn_kwargs(popen_kwargs)
    use_shell = bool(kwargs.pop("shell", False))
    if use_shell:
        command_argv = ["/bin/sh", "-c", str(command)]
    elif isinstance(command, (list, tuple)) and command:
        command_argv = [os.fspath(value) for value in command]
    else:
        raise ValueError("POSIX agent command must be a non-empty argument list.")
    marker = f"{PROCESS_TREE_ID_ENV}={tree_id}"
    sentinel_marker = f"{PROCESS_TREE_SENTINEL_ENV}={tree_id}"
    command = [
        sys.executable,
        "-c",
        POSIX_AGENT_SENTINEL,
        marker,
        sentinel_marker,
        *command_argv,
    ]
    kwargs["start_new_session"] = True
    proc = subprocess.Popen(command, **kwargs)
    setattr(proc, "_coauto_process_group_id", int(proc.pid))
    setattr(proc, "_coauto_tree_lock", threading.RLock())
    setattr(proc, "_coauto_tree_drained", False)
    setattr(proc, "_coauto_process_tree_id", tree_id)
    return proc


def agent_process_tree_active(proc: Any) -> bool:
    return bool(proc is not None and not getattr(proc, "_coauto_tree_drained", False))


def agent_process_tree_identity(proc: subprocess.Popen[str]) -> dict[str, Any]:
    tree_id = str(getattr(proc, "_coauto_process_tree_id", "") or "")
    if not re.fullmatch(r"[0-9a-f]{32}", tree_id):
        raise RuntimeError("Agent process tree has no valid recovery identity.")
    identity: dict[str, Any] = {
        "schema_version": 1,
        "kind": "windows_job" if os.name == "nt" else "posix_process_group",
        "root_pid": int(proc.pid),
        "service_pid": os.getpid(),
        "service_instance_id": PROCESS_TREE_SERVICE_ID,
        "process_tree_id": tree_id,
    }
    if os.name != "nt":
        process_group_id = int(
            getattr(proc, "_coauto_process_group_id", 0) or 0
        )
        if process_group_id <= 0:
            raise RuntimeError("POSIX agent process has no isolated process group.")
        identity["process_group_id"] = process_group_id
    elif not int(getattr(proc, "_coauto_windows_job", 0) or 0):
        raise RuntimeError("Windows agent process has no bound Job Object.")
    return identity


def _process_id_alive(pid: Any) -> bool:
    try:
        value = int(pid)
    except (TypeError, ValueError):
        return False
    if value <= 0:
        return False
    if os.name == "nt":
        if value > 0xFFFFFFFF:
            raise RuntimeError("Windows process liveness could not be verified.")
        import ctypes

        kernel32 = ctypes.WinDLL("kernel32", use_last_error=True)
        kernel32.OpenProcess.argtypes = [
            ctypes.c_uint,
            ctypes.c_int,
            ctypes.c_uint,
        ]
        kernel32.OpenProcess.restype = ctypes.c_void_p
        kernel32.WaitForSingleObject.argtypes = [ctypes.c_void_p, ctypes.c_uint]
        kernel32.WaitForSingleObject.restype = ctypes.c_uint
        handle = kernel32.OpenProcess(0x00100000, False, value)
        if not handle:
            if ctypes.get_last_error() == 87:
                return False
            raise RuntimeError("Windows process liveness could not be verified.")
        try:
            result = int(kernel32.WaitForSingleObject(handle, 0))
        finally:
            _windows_close_handle(int(handle))
        if result == 0:
            return False
        if result == 0x00000102:
            return True
        raise RuntimeError("Windows process liveness could not be verified.")
    try:
        os.kill(value, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True
    except OSError as exc:
        raise RuntimeError("POSIX process liveness could not be verified.") from exc


def _posix_process_group_alive(process_group_id: int) -> bool:
    return bool(_posix_process_group_members(process_group_id))


def _linux_process_entry(
    entry: Path, process_tree_id: str | None
) -> tuple[int, int, str, bool | None, bool | None] | None:
    try:
        uid = int(os.stat(entry, follow_symlinks=False).st_uid)
    except (FileNotFoundError, ProcessLookupError, PermissionError):
        return None
    except OSError as exc:
        raise RuntimeError("Linux process identity could not be verified.") from exc
    try:
        stat_line = (entry / "stat").read_text(encoding="utf-8", errors="replace")
    except (FileNotFoundError, ProcessLookupError):
        return None
    except PermissionError as exc:
        if uid != os.geteuid():
            return None
        raise RuntimeError("A same-user Linux process identity could not be verified.") from exc
    except OSError as exc:
        raise RuntimeError("Linux process identity could not be verified.") from exc
    close = stat_line.rfind(")")
    fields = stat_line[close + 2 :].split() if close >= 0 else []
    if len(fields) < 20:
        raise RuntimeError("Linux process identity could not be verified.")
    try:
        process_group_id = int(fields[2])
        start_token = str(int(fields[19]))
    except ValueError as exc:
        raise RuntimeError("Linux process identity could not be verified.") from exc
    if fields[0] in {"Z", "X"}:
        return None
    marker_matches: bool | None = None
    sentinel_matches: bool | None = None
    if process_tree_id and uid == os.geteuid():
        marker = f"{PROCESS_TREE_ID_ENV}={process_tree_id}".encode("ascii")
        sentinel_marker = (
            f"{PROCESS_TREE_SENTINEL_ENV}={process_tree_id}".encode("ascii")
        )
        try:
            environment = (entry / "environ").read_bytes()
        except (FileNotFoundError, ProcessLookupError):
            return None
        except OSError:
            marker_matches = None
            sentinel_matches = None
        else:
            variables = environment.split(b"\0")
            marker_matches = marker in variables
            sentinel_matches = sentinel_marker in variables
    return process_group_id, uid, start_token, marker_matches, sentinel_matches


def _linux_process_table(
    process_tree_id: str | None = None,
) -> dict[int, tuple[int, int, str, bool | None, bool | None]]:
    table: dict[int, tuple[int, int, str, bool | None, bool | None]] = {}
    try:
        entries = tuple(Path("/proc").iterdir())
    except OSError as exc:
        raise RuntimeError("Linux process table could not be verified.") from exc
    for entry in entries:
        if not entry.name.isdigit():
            continue
        value = _linux_process_entry(entry, process_tree_id)
        if value is not None:
            table[int(entry.name)] = value
    return table


def _darwin_process_table(
    process_tree_id: str | None = None,
) -> dict[int, tuple[int, int, str, bool | None, bool | None]]:
    fields = "pid=,pgid=,uid=,state=,lstart="
    command = ["/bin/ps", "-axo", fields]
    if process_tree_id:
        fields += ",command="
        command = ["/bin/ps", "eww", "-axo", fields]
    try:
        result = subprocess.run(
            command,
            stdout=subprocess.PIPE,
            stderr=subprocess.DEVNULL,
            text=True,
            timeout=2,
            check=False,
            env=POSIX_INSPECTION_ENV,
        )
    except (OSError, subprocess.TimeoutExpired) as exc:
        raise RuntimeError("macOS process table could not be verified.") from exc
    if result.returncode != 0:
        raise RuntimeError("macOS process table could not be verified.")
    marker = f"{PROCESS_TREE_ID_ENV}={process_tree_id}" if process_tree_id else ""
    sentinel_marker = (
        f"{PROCESS_TREE_SENTINEL_ENV}={process_tree_id}" if process_tree_id else ""
    )
    table: dict[int, tuple[int, int, str, bool | None, bool | None]] = {}
    for line in result.stdout.splitlines():
        values = line.split(None, 9)
        if len(values) < 9:
            if line.strip():
                raise RuntimeError("macOS process table could not be verified.")
            continue
        try:
            pid, group_id, uid = (int(value) for value in values[:3])
        except ValueError as exc:
            raise RuntimeError("macOS process table could not be verified.") from exc
        if values[3].startswith(("Z", "X")):
            continue
        start_token = " ".join(values[4:9])
        marker_matches: bool | None = None
        sentinel_matches: bool | None = None
        if marker and uid == os.geteuid():
            process_command = values[9] if len(values) > 9 else ""
            command_parts = process_command.split()
            marker_matches = marker in command_parts
            sentinel_matches = sentinel_marker in command_parts
        table[pid] = (
            group_id,
            uid,
            start_token,
            marker_matches,
            sentinel_matches,
        )
    return table


def _posix_process_table(
    process_tree_id: str | None = None,
) -> dict[int, tuple[int, int, str, bool | None, bool | None]]:
    if sys.platform.startswith("linux"):
        return _linux_process_table(process_tree_id)
    if sys.platform == "darwin":
        return _darwin_process_table(process_tree_id)
    raise RuntimeError("This POSIX platform cannot verify agent process trees.")


def _posix_process_identity(
    pid: int, process_tree_id: str
) -> tuple[int, int, str, bool | None, bool | None] | None:
    if sys.platform.startswith("linux"):
        return _linux_process_entry(Path("/proc") / str(pid), process_tree_id)
    return _posix_process_table(process_tree_id).get(pid)


def _posix_process_group_members(process_group_id: int) -> set[int]:
    return {
        pid
        for pid, value in _posix_process_table().items()
        if value[0] == process_group_id
    }


def _is_process_tree_sentinel(value: tuple[Any, ...]) -> bool:
    """Recognize the dedicated anchor; four-field test/legacy rows use marker."""

    return bool(value[4] is True if len(value) > 4 else value[3] is True)


def _verified_posix_tree_members(
    process_group_id: int,
    process_tree_id: str,
    trusted_after_anchor: dict[int, tuple[Any, ...]] | None = None,
) -> dict[int, tuple[Any, ...]]:
    if not re.fullmatch(r"[0-9a-f]{32}", process_tree_id):
        raise RuntimeError("Recorded agent process-tree identity is invalid.")
    deadline = time.monotonic() + PROCESS_TREE_VERIFY_TIMEOUT_SECONDS
    last_snapshot_error: RuntimeError | None = None
    while True:
        try:
            before = _posix_process_table(process_tree_id)
            after = _posix_process_table(process_tree_id)
        except RuntimeError as exc:
            last_snapshot_error = exc
            if time.monotonic() >= deadline:
                raise RuntimeError(
                    "POSIX process table remained unavailable during the "
                    "bounded verification window."
                ) from exc
            time.sleep(PROCESS_TREE_SCAN_INTERVAL_SECONDS)
            continue
        before_group = {
            (pid, *value[:3])
            for pid, value in before.items()
            if value[0] == process_group_id
        }
        after_group = {
            (pid, *value[:3])
            for pid, value in after.items()
            if value[0] == process_group_id
        }
        if before_group != after_group:
            if time.monotonic() >= deadline:
                break
            continue
        unstable = False
        for pid, value in tuple(after.items()):
            if value[0] != process_group_id or value[3] is True:
                continue
            confirmed = _posix_process_identity(pid, process_tree_id)
            if confirmed is None or confirmed[:3] != value[:3]:
                unstable = True
                break
            after[pid] = confirmed
        if unstable:
            if time.monotonic() >= deadline:
                break
            continue
        group = {
            pid: value
            for pid, value in after.items()
            if value[0] == process_group_id
        }
        if group:
            if any(value[1] != os.geteuid() for value in group.values()):
                raise RuntimeError(
                    "Recorded process group contains a member owned by another user."
                )
            if not any(_is_process_tree_sentinel(value) for value in group.values()):
                # A continuous drain is allowed to outlive the marker-bearing
                # sentinel that established ownership. Every remaining group
                # member must still be the exact pid/pgid/uid/start-time
                # identity authenticated while that anchor was alive. This
                # preserves fail-closed behaviour for a reused group while
                # allowing SIGKILL to finish descendants that ignored SIGTERM.
                trusted = trusted_after_anchor or {}
                if not all(
                    pid in trusted and trusted[pid][:3] == value[:3]
                    for pid, value in group.items()
                ):
                    raise RuntimeError(
                        "Recorded process group has no bound agent-identity sentinel."
                    )
        members: dict[int, tuple[Any, ...]] = {}
        for pid, value in after.items():
            if value[1] != os.geteuid():
                continue
            if value[0] == process_group_id and group:
                members[pid] = value
                continue
            if value[3] is None:
                confirmed = _posix_process_identity(pid, process_tree_id)
                if confirmed is None or confirmed[:3] != value[:3]:
                    continue
                if confirmed[3] is None:
                    raise RuntimeError(
                        "A same-user process environment could not be verified."
                    )
                value = confirmed
            if value[3] is True:
                members[pid] = value
        return members
    if last_snapshot_error is not None:
        raise RuntimeError(
            "Recorded agent process-tree identity could not be verified."
        ) from last_snapshot_error
    raise RuntimeError("Recorded agent process-tree identity could not be verified.")


def _signal_verified_posix_process(
    pid: int,
    expected: tuple[Any, ...],
    process_tree_id: str,
    sig: int,
    trusted_process_group_id: int = 0,
) -> bool:
    def confirmed() -> tuple[Any, ...] | None:
        current = _posix_process_identity(pid, process_tree_id)
        if current is None or current[:3] != expected[:3]:
            return None
        trusted_group_member = bool(
            trusted_process_group_id > 0
            and current[0] == trusted_process_group_id
            and expected[0] == trusted_process_group_id
            and current[1] == os.geteuid()
        )
        if current[3] is None and not trusted_group_member:
            raise RuntimeError("A same-user process environment could not be verified.")
        if current[3] is not True and not trusted_group_member:
            raise ProcessTreeObservationChanged(
                "Agent process-tree identity changed before signaling."
            )
        return current

    if confirmed() is None:
        return False
    pidfd_open = getattr(os, "pidfd_open", None)
    pidfd_signal = getattr(signal, "pidfd_send_signal", None)
    if sys.platform.startswith("linux") and callable(pidfd_open) and callable(pidfd_signal):
        try:
            descriptor = pidfd_open(pid, 0)
        except ProcessLookupError:
            return False
        except OSError as exc:
            if exc.errno not in {errno.ENOSYS, errno.EINVAL}:
                raise RuntimeError("Linux pidfd identity could not be opened safely.") from exc
        else:
            try:
                if confirmed() is None:
                    return False
                try:
                    pidfd_signal(descriptor, sig, None, 0)
                except ProcessLookupError:
                    return False
                except OSError as exc:
                    raise RuntimeError("Verified Linux process could not be signaled.") from exc
                return True
            finally:
                os.close(descriptor)
    if confirmed() is None:
        return False
    try:
        os.kill(pid, sig)
    except ProcessLookupError:
        return False
    except OSError as exc:
        raise RuntimeError("Verified POSIX process could not be signaled.") from exc
    return True


def _signal_posix_tree_until_empty(
    process_group_id: int,
    process_tree_id: str,
    sig: int,
    timeout: float,
    trusted_members: dict[int, tuple[Any, ...]] | None = None,
) -> bool:
    deadline = time.monotonic() + max(PROCESS_TREE_SCAN_INTERVAL_SECONDS, timeout)
    empty_scans = 0
    signaled: set[tuple[int, int, int, str]] = set()
    while True:
        members = _verified_posix_tree_members(
            process_group_id,
            process_tree_id,
            trusted_after_anchor=trusted_members,
        )
        if not members:
            empty_scans += 1
            if empty_scans >= PROCESS_TREE_EMPTY_SCANS:
                return True
        else:
            empty_scans = 0
            if trusted_members is not None:
                trusted_members.update(members)
            anchors = {
                pid for pid, value in members.items() if _is_process_tree_sentinel(value)
            }
            # Keep at least one dedicated ownership anchor alive while other
            # members are being terminated. Programs such as macOS /bin/sleep
            # do not expose inherited environment through ps, so killing the
            # sentinel first would make an otherwise authenticated group
            # impossible to finish safely. Once no other member remains, the
            # sentinel itself is terminated and consecutive empty scans close
            # the boundary.
            signalable = (
                members.items()
                if not anchors or len(anchors) == len(members)
                else (
                    (pid, value)
                    for pid, value in members.items()
                    if pid not in anchors
                )
            )
            observation_changed = False
            for pid, value in signalable:
                identity = (pid, value[0], value[1], value[2])
                if identity in signaled:
                    continue
                try:
                    _signal_verified_posix_process(
                        pid,
                        value,
                        process_tree_id,
                        sig,
                        trusted_process_group_id=process_group_id,
                    )
                except ProcessTreeObservationChanged:
                    # The process table is inherently live.  Never signal an
                    # identity that no longer matches the verified scan; give
                    # the next complete scan a chance to prove that it exited
                    # or to bind its new, still-agent-owned identity.  A
                    # persistent mismatch still exhausts the deadline and
                    # fails closed.
                    observation_changed = True
                    break
                signaled.add(identity)
            if observation_changed:
                if time.monotonic() >= deadline:
                    return False
                time.sleep(PROCESS_TREE_SCAN_INTERVAL_SECONDS)
                continue
            if time.monotonic() >= deadline:
                return False
        time.sleep(PROCESS_TREE_SCAN_INTERVAL_SECONDS)


def _drain_posix_process_tree(
    process_group_id: int,
    process_tree_id: str,
    *,
    grace_seconds: float,
    kill_seconds: float,
) -> None:
    trusted_members: dict[int, tuple[Any, ...]] = {}
    if _signal_posix_tree_until_empty(
        process_group_id,
        process_tree_id,
        signal.SIGTERM,
        grace_seconds,
        trusted_members,
    ):
        return
    if _signal_posix_tree_until_empty(
        process_group_id,
        process_tree_id,
        signal.SIGKILL,
        kill_seconds,
        trusted_members,
    ):
        return
    raise RuntimeError("POSIX agent process tree still has members after SIGKILL.")


def drain_recorded_agent_process_tree(identity: Any) -> None:
    """Drain a crash-surviving recorded group before startup guard recovery."""

    if not isinstance(identity, dict) or identity.get("schema_version") != 1:
        raise RuntimeError("Active guard has no valid agent process-tree identity.")
    kind = str(identity.get("kind") or "")
    try:
        root_pid = int(identity.get("root_pid") or 0)
        service_pid = int(identity.get("service_pid") or 0)
    except (TypeError, ValueError) as exc:
        raise RuntimeError("Active guard has no valid agent process-tree identity.") from exc
    process_tree_id = str(identity.get("process_tree_id") or "")
    service_instance_id = str(identity.get("service_instance_id") or "")
    if (
        kind not in {"posix_process_group", "windows_job"}
        or root_pid <= 0
        or service_pid <= 0
        or not re.fullmatch(r"[0-9a-f]{32}", process_tree_id)
        or not re.fullmatch(r"[0-9a-f]{32}", service_instance_id)
    ):
        raise RuntimeError("Active guard has no valid agent process-tree identity.")
    if service_instance_id == PROCESS_TREE_SERVICE_ID:
        raise RuntimeError("Recorded agent isolation still belongs to this server instance.")
    if service_pid != os.getpid() and _process_id_alive(service_pid):
        raise RuntimeError("Recorded agent isolation owner is still active.")
    if kind == "posix_process_group":
        if os.name == "nt":
            raise RuntimeError("Recorded agent process isolation belongs to another platform.")
        try:
            process_group_id = int(identity.get("process_group_id") or 0)
        except (TypeError, ValueError) as exc:
            raise RuntimeError("Recorded POSIX agent process group is invalid.") from exc
        if process_group_id <= 0 or root_pid <= 0 or process_group_id != root_pid:
            raise RuntimeError("Recorded POSIX agent process group is invalid.")
        _drain_posix_process_tree(
            process_group_id,
            process_tree_id,
            grace_seconds=1.0,
            kill_seconds=3.0,
        )
        return
    if kind == "windows_job":
        if os.name != "nt":
            raise RuntimeError("Recorded agent process isolation belongs to another platform.")
        deadline = time.monotonic() + 3.0
        while _process_id_alive(root_pid) and time.monotonic() < deadline:
            time.sleep(0.02)
        if _process_id_alive(root_pid):
            raise RuntimeError(
                "Recorded Windows agent is still active after its server Job Object closed."
            )
        return


def drain_agent_process_tree(
    proc: subprocess.Popen[str], *, grace_seconds: float = 1.0, kill_seconds: float = 3.0
) -> int | None:
    """Drain and verify the platform-tracked agent processes that remain discoverable."""

    if bool(getattr(proc, "_coauto_tree_drained", False)):
        return proc.poll()
    lock = getattr(proc, "_coauto_tree_lock", None)
    if lock is None:
        raise RuntimeError("Refusing to drain an agent process without an isolation boundary.")
    with lock:
        if bool(getattr(proc, "_coauto_tree_drained", False)):
            return proc.poll()
        try:
            if proc.stdin:
                proc.stdin.close()
        except OSError:
            pass
        if os.name == "nt":
            job = int(getattr(proc, "_coauto_windows_job", 0) or 0)
            if not job:
                raise RuntimeError("Windows agent process has no bound Job Object.")
            try:
                if _windows_job_active_process_count(job):
                    _windows_terminate_job(job)
                deadline = time.monotonic() + max(0.0, kill_seconds)
                while _windows_job_active_process_count(job):
                    if time.monotonic() >= deadline:
                        raise RuntimeError("Windows agent Job Object still has active processes after termination.")
                    time.sleep(0.02)
                try:
                    proc.wait(timeout=max(0.1, kill_seconds))
                except subprocess.TimeoutExpired as exc:
                    raise RuntimeError("Windows agent root process did not terminate with its Job Object.") from exc
            finally:
                _windows_close_handle(job)
                setattr(proc, "_coauto_windows_job", 0)
        else:
            process_group_id = int(getattr(proc, "_coauto_process_group_id", 0) or 0)
            process_tree_id = str(getattr(proc, "_coauto_process_tree_id", "") or "")
            if process_group_id <= 0:
                raise RuntimeError("POSIX agent process has no isolated process group.")
            if int(getattr(proc, "pid", 0) or 0) != process_group_id:
                raise RuntimeError("Live POSIX agent process-group identity is invalid.")
            _drain_posix_process_tree(
                process_group_id,
                process_tree_id,
                grace_seconds=grace_seconds,
                kill_seconds=kill_seconds,
            )
            try:
                proc.wait(timeout=max(0.1, kill_seconds))
            except subprocess.TimeoutExpired as exc:
                raise RuntimeError("POSIX agent root process did not drain with its process group.") from exc
        setattr(proc, "_coauto_tree_drained", True)
        return proc.poll()


def ensure_agent_process_tree_drained(proc: subprocess.Popen[str]) -> bool:
    """Fail closed unless the tracked process group or Job is proven empty."""

    try:
        drain_agent_process_tree(proc)
        return True
    except Exception as exc:
        append_research_log(
            "Agent process group/Job could not be drained; canonical boundary work is blocked. "
            + redact_sensitive_text(exc)
        )
        with RESEARCH_LOCK:
            if RESEARCH_SESSION.get("process") is proc:
                RESEARCH_SESSION["status"] = "interrupted"
                RESEARCH_SESSION["loop_active"] = False
                RESEARCH_SESSION["loop_stop_reason"] = "recovery_required"
                RESEARCH_SESSION["ended_at"] = now_iso()
                RESEARCH_SESSION["returncode"] = proc.poll()
        persist_research_session()
        return False


def signal_research_process(proc: subprocess.Popen[str], force: bool = False) -> None:
    if os.name == "nt":
        job = int(getattr(proc, "_coauto_windows_job", 0) or 0)
        if not job:
            raise RuntimeError("Windows agent process has no bound Job Object.")
        _windows_terminate_job(job)
        return
    sig = signal.SIGKILL if force else signal.SIGTERM
    process_group_id = int(getattr(proc, "_coauto_process_group_id", 0) or 0)
    process_tree_id = str(getattr(proc, "_coauto_process_tree_id", "") or "")
    if process_group_id <= 0:
        raise RuntimeError("POSIX agent process has no isolated process group.")
    if int(getattr(proc, "pid", 0) or 0) != process_group_id:
        raise RuntimeError("Live POSIX agent process-group identity is invalid.")
    members = _verified_posix_tree_members(process_group_id, process_tree_id)
    anchors = {
        pid for pid, value in members.items() if _is_process_tree_sentinel(value)
    }
    signalable = (
        members.items()
        if not anchors or len(anchors) == len(members)
        else ((pid, value) for pid, value in members.items() if pid not in anchors)
    )
    for pid, value in signalable:
        _signal_verified_posix_process(
            pid,
            value,
            process_tree_id,
            sig,
            trusted_process_group_id=process_group_id,
        )


def should_resume_research_session(settings_payload: Any | None = None) -> bool:
    status = str(RESEARCH_SESSION.get("status") or "").strip().lower()
    if status in {"interrupted", "failed"}:
        return False
    mode = str(RESEARCH_SESSION.get("mode") or "").strip().lower()
    if mode == "plan":
        return False
    session_id = str(RESEARCH_SESSION.get("session_id") or "").strip()
    if not session_id:
        return False
    if session_id == str(RESEARCH_SESSION.get("plan_thread_id") or "").strip():
        return False
    session_settings = RESEARCH_SESSION.get("settings") if isinstance(RESEARCH_SESSION.get("settings"), dict) else {}
    current_backend = normalize_agent_backend(RESEARCH_SESSION.get("backend") or session_settings.get("backend"))
    if current_backend == "claude":
        session_permission = infer_claude_permission_preset(session_settings)
        session_mode = str(session_settings.get("permissionMode") or "").strip()
        if session_permission == "plan" or session_mode == "plan":
            return False
    if settings_payload is not None:
        target_backend = normalize_agent_backend(implementation_settings_from_payload(settings_payload).get("backend"))
        if current_backend and target_backend != current_backend:
            return False
    return True


def ensure_restored_project_writable() -> None:
    startup = getattr(current_project_context(), "v2_startup", {})
    if isinstance(startup, dict) and startup.get("recovery_pending"):
        raise ValueError(
            "Project startup recovery is still running; write and run controls "
            "remain disabled until its guard audit completes."
        )
    restore_status = restore_recovery_status(REPO_ROOT)
    if restore_status.get("recovery_required"):
        raise ValueError(
            "This restored project is read-only until an operator completes "
            "restore acknowledgement; write and run controls are disabled."
        )


def ensure_project_protocol_runnable() -> dict[str, Any]:
    with RESEARCH_LOCK:
        blocked_reason = str(RESEARCH_SESSION.get("loop_stop_reason") or "")
    if blocked_reason == "recovery_required":
        raise ValueError(
            "Research is disabled until the retained v2 write guard is recovered."
        )
    if blocked_reason == "stage_resolution_required":
        raise ValueError(
            "Research is disabled until the unpublished v2 stage is explicitly resolved."
        )
    try:
        ensure_restored_project_writable()
    except ValueError as exc:
        raise ValueError(f"Research is disabled. {exc}") from exc
    classification = classify_project(REPO_ROOT)
    kind = str(classification.get("classification") or "corrupt")
    if kind not in {"legacy", "v2"}:
        details = "; ".join(str(item) for item in classification.get("errors", [])[:3])
        raise ValueError(
            f"Research is disabled because the project protocol is {kind}."
            + (f" {details}" if details else " Run recovery or use a supported project version.")
        )
    project_manifest = REPO_ROOT / TEMPLATE_MANIFEST_RELATIVE_PATH
    if project_manifest.is_file():
        template_status = project_reviewer_baseline_status(REPO_ROOT)
        drift = [
            *template_status.get("missing", []),
            *template_status.get("changed", []),
            *template_status.get("metadata_missing", []),
            *template_status.get("protocol_missing", []),
            *template_status.get("protocol_changed", []),
            *template_status.get("protocol_metadata_missing", []),
            *template_status.get("managed_missing", []),
            *template_status.get("managed_changed", []),
            *template_status.get("manifest_changed", []),
        ]
        if drift or template_status.get("baseline_version") != REVIEWER_BASELINE_VERSION:
            detail = ", ".join(str(item) for item in drift[:3])
            raise ValueError(
                "Research is disabled because package-managed project files are out of date. "
                "Update the project template before starting research."
                + (f" Drift: {detail}." if detail else "")
            )
    if kind == "v2":
        health = v2_transaction_health(REPO_ROOT)
        if health.get("recovery_required"):
            raise ValueError("Research is disabled until incomplete canonical transactions are recovered.")
    return classification


def ensure_bound_v2_phase_runnable() -> None:
    """Validate the service binding used to repair or advance one v2 phase."""

    with RESEARCH_LOCK:
        state = dict(
            RESEARCH_SESSION.get("v2")
            if isinstance(RESEARCH_SESSION.get("v2"), dict)
            else {}
        )
        blocked_reason = str(RESEARCH_SESSION.get("loop_stop_reason") or "")
    if blocked_reason in {"recovery_required", "stage_resolution_required"}:
        raise ValueError(
            "Research is disabled until the retained v2 recovery boundary is resolved."
        )
    binding = v2_load_active_binding()
    guard_key = v2_phase_guard_key(state.get("phase"))
    if not (
        isinstance(binding, dict)
        and binding.get("kind") == "trial"
        and binding.get("trial_id") == state.get("trial_id")
        and binding.get("stage_id") == state.get("stage_id")
        and binding.get("phase") == state.get("phase")
        and binding.get("guard_dir") == state.get(guard_key)
    ):
        raise ValueError("The v2 phase is not bound to its trusted write guard.")
    ensure_restored_project_writable()
    if v2_transaction_health(REPO_ROOT).get("recovery_required"):
        raise ValueError(
            "Research is disabled until incomplete canonical transactions are recovered."
        )


@serialized_research_admission
def start_research_run(
    prompt: str,
    mode: str,
    resume: bool,
    settings_payload: Any | None = None,
    display_prompt: str | None = None,
    loop_active: bool | None = None,
    reset_review_checkpoint: bool = False,
    loop_iteration_override: int | None = None,
    model_preflighted: bool = False,
    review_context: dict[str, str] | None = None,
) -> dict[str, Any]:
    ensure_server_accepting_runs()
    prompt = prompt.strip()
    if not prompt:
        raise ValueError("Prompt is required.")
    reconcile_research_process_state()
    if mode == "v2_trial":
        ensure_bound_v2_phase_runnable()
    else:
        ensure_project_protocol_runnable()
    settings = implementation_settings_from_payload(settings_payload)
    backend = normalize_agent_backend(settings.get("backend"))
    process_env = agent_process_env(backend, settings)
    ensure_project_agents_idle(
        f"Wait for the active agent or figure-image job before starting {agent_display_name(backend)}.",
        allow_discussions=True,
    )
    if not model_preflighted:
        ensure_agent_ready(
            backend,
            env=process_env,
            settings=settings,
            force_refresh=True,
        )
    ensure_project_agents_idle(
        f"Wait for the active agent or figure-image job before starting {agent_display_name(backend)}.",
        allow_discussions=True,
    )
    with RESEARCH_LOCK:
        if resume and not should_resume_research_session(settings):
            resume = False
        previous_session_id = str(RESEARCH_SESSION.get("session_id") or "")
        use_codex_app_server = mode in {"chat", "framing"} and backend == "codex" and bool(settings.get("codexAppServerChat"))
        if use_codex_app_server and str(settings.get("approvalPolicy") or "on-request") != "never":
            raise ValueError(
                "Codex app-server chat cannot answer interactive approval requests in this UI. "
                "Choose Auto-review/Full access (approval policy `never`) or turn off app-server chat."
            )
        previous_session_source = str(RESEARCH_SESSION.get("session_id_source") or "")
        if resume and backend == "codex":
            if use_codex_app_server and previous_session_source == "exec":
                resume = False
            if not use_codex_app_server and previous_session_source == "app_server":
                resume = False
        command = codex_app_server_command(settings) if use_codex_app_server else agent_command_for_prompt(resume, settings)
        protected_snapshot = create_chat_protected_snapshot() if mode == "chat" else None
        # Capture service-owned recovery bytes before the v2 agent baseline so
        # the backup is protected by, rather than mistaken for a write through,
        # the non-publish boundary.
        aux_guard_dir = start_v2_aux_guard(mode)
        if mode == "goal":
            record_project_scope_hash_at_launch(sync_trajectory_state("start_goal_run"))
        previous_loop_iteration = latest_active_trial_iteration() if mode == "goal" else int(RESEARCH_SESSION.get("loop_iteration") or 0)
        next_loop_active = bool(RESEARCH_SESSION.get("loop_active")) if loop_active is None else bool(loop_active)
        if loop_iteration_override is not None:
            next_loop_iteration = max(0, int(loop_iteration_override))
        elif next_loop_active and mode == "goal":
            next_loop_iteration = next_active_trial_iteration()
        else:
            next_loop_iteration = previous_loop_iteration
        review_checkpoint_interval = normalize_review_checkpoint_interval(settings.get("reviewCheckpointInterval"))
        loop_review_checkpoint_iteration = int(RESEARCH_SESSION.get("loop_review_checkpoint_iteration") or 0)
        if next_loop_active and (reset_review_checkpoint or loop_review_checkpoint_iteration <= 0):
            checkpoint_base = max(0, next_loop_iteration - 1) if mode == "goal" else previous_loop_iteration
            loop_review_checkpoint_iteration = checkpoint_base + review_checkpoint_interval
        if next_loop_active and mode == "goal" and next_loop_iteration > 0:
            trajectory = read_trajectory_state()
            write_expected_trial_marker(
                next_loop_iteration,
                reason=mode,
                base_trial=str(trajectory.get("base_trial") or ""),
                fork_id=str(trajectory.get("fork_id") or ""),
            )
        if not resume and mode != "v2_trial":
            RESEARCH_SESSION["logs"] = []
            RESEARCH_SESSION["raw_logs"] = []
            RESEARCH_SESSION["transcript"] = []
            RESEARCH_SESSION["streaming_transcript"] = {}
            RESEARCH_SESSION["review_contexts"] = {}
        run_id = f"S{now_id()}_{slugify(mode, 'research')}"
        if any(entry.get("run_id") == run_id for entry in RESEARCH_SESSION.get("transcript", []) if isinstance(entry, dict)):
            run_id += "_" + uuid.uuid4().hex[:8]
        context = valid_review_context(review_context) if mode == "v2_trial" else {}
        if context:
            RESEARCH_SESSION["review_contexts"] = {
                **dict(RESEARCH_SESSION.get("review_contexts") or {}), run_id: context,
            }
        RESEARCH_SESSION.update(
            {
                "id": run_id,
                "session_id": previous_session_id if resume else "",
                "status": "running",
                "backend": backend,
                "mode": mode,
                "command": command,
                "settings": settings,
                "run_settings": dict(settings),
                "started_at": now_iso(),
                "ended_at": "",
                "returncode": None,
                "streaming_transcript": {},
                "loop_active": next_loop_active,
                "loop_iteration": next_loop_iteration,
                "loop_max_iterations": review_checkpoint_interval,
                "loop_review_checkpoint_iteration": loop_review_checkpoint_iteration,
                "loop_stop_reason": "" if next_loop_active else RESEARCH_SESSION.get("loop_stop_reason", ""),
                "process": None,
                "last_event_at": now_iso(),
                "last_event_summary": "Starting selected agent.",
                "agent_notice": {},
                "protected_snapshot": protected_snapshot,
                "app_thread_id": "",
                "app_turn_id": "",
                "session_id_source": RESEARCH_SESSION.get("session_id_source", "") if resume else "",
                "v2_aux_guard_dir": aux_guard_dir,
                "boundary_audit_pending": False,
            }
        )
        display_text = prompt if display_prompt is None else str(display_prompt).strip()
        if mode == "command":
            RESEARCH_SESSION["transcript"].append(transcript_entry("user", "user", "User", display_text, "ui.command", False))
        else:
            title = "Cold start request" if mode == "cold_start" else "User"
            RESEARCH_SESSION["transcript"].append(transcript_entry("user", "user", title, display_text, f"ui.{mode}", mode in {"chat", "research"}))
        trim_transcript_locked()
        session_patch = research_event_session_patch()
    persist_research_session()
    run_id, trial_id = operation_correlation_ids()
    emit_operation_event(
        "agent_run",
        "started",
        "running",
        run_id=run_id,
        trial_id=trial_id,
        details={
            "backend": backend,
            "mode": mode,
            "executable": Path(command[0]).name if command else "",
        },
    )
    emit_research_event("session", {"session_patch": session_patch})

    wrapper_path: Path | None = None
    proc: subprocess.Popen[str] | None = None
    try:
        ensure_server_accepting_runs()
        ensure_current_project_writeable()
        popen_command, use_shell, wrapper_path = popen_command_for_agent(command, settings, process_env)
        proc = spawn_agent_process(
            popen_command,
            cwd=REPO_ROOT,
            env=process_env,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
            shell=use_shell,
        )
        if wrapper_path:
            setattr(proc, "_coauto_pre_exec_wrapper", wrapper_path)
        with RESEARCH_LOCK:
            RESEARCH_SESSION["process"] = proc
            RESEARCH_SESSION["pre_exec_script_applied"] = bool(wrapper_path)
        record_research_process_tree(proc)
        if not use_codex_app_server:
            assert proc.stdin is not None
            proc.stdin.write(prompt)
            proc.stdin.write("\n")
            proc.stdin.close()
    except (OSError, ValueError, RuntimeError) as exc:
        if proc is not None and not ensure_agent_process_tree_drained(proc):
            return research_session_snapshot()
        if wrapper_path:
            try:
                wrapper_path.unlink(missing_ok=True)
            except OSError:
                pass
        if isinstance(exc, OSError):
            append_research_log(agent_start_error_message(exc, command, backend))
        else:
            append_research_log(str(exc))
        finish_research_run(127)
        if mode == "v2_trial":
            advance_v2_trial(127)
        else:
            audit_v2_aux_guard()
        return research_session_snapshot()

    assert proc is not None
    append_research_log(f"Started: {' '.join(command)}")
    if wrapper_path:
        append_research_log(f"Applied shell setup before starting {agent_display_name(backend)}.")
    context = current_project_context()
    if use_codex_app_server:
        thread = threading.Thread(target=run_in_project, args=(context, process_codex_app_server_interactive_run, proc, prompt, settings, resume), daemon=True)
    else:
        normalizer = make_research_trace_normalizer(backend, "exec", settings)
        thread = threading.Thread(target=run_in_project, args=(context, process_research_run, proc, normalizer, run_id), daemon=True)
    with RESEARCH_LOCK:
        RESEARCH_SESSION["process_thread"] = thread
    thread.start()
    return research_session_snapshot()


def codex_app_server_command(settings: dict[str, Any]) -> list[str]:
    executable = resolve_agent_executable("codex", agent_process_env("codex", settings))
    args = [executable]
    if settings.get("webSearch"):
        args.extend(["-c", 'web_search="live"'])
    args.extend(extra_config_args(str(settings.get("extraConfig") or "")))
    args.extend(["-c", "project_root_markers=[]"])
    args.extend(["app-server", "--listen", "stdio://"])
    return args


def json_rpc_write(proc: subprocess.Popen[str], message: dict[str, Any]) -> None:
    codex_app_server_rpc.json_rpc_write(proc, message)


def extract_nested_id(payload: Any, names: tuple[str, ...]) -> str:
    return codex_app_server_rpc.extract_nested_id(payload, names)


def codex_plan_event_parts(event: dict[str, Any]) -> tuple[str, dict[str, Any]]:
    return codex_app_server_rpc.event_parts(event)


def codex_server_request_result(method: str) -> dict[str, Any] | None:
    lowered = str(method or "").lower()
    if "approval" not in lowered:
        return None
    if "permission" in lowered:
        return {"permissions": {}}
    return {"decision": "decline"}


def plan_steps_from_payload(value: Any) -> list[dict[str, str]]:
    if not isinstance(value, list):
        return []
    steps: list[dict[str, str]] = []
    for item in value:
        if not isinstance(item, dict):
            continue
        step = str(item.get("step") or item.get("text") or "").strip()
        status = str(item.get("status") or "").strip()
        if step:
            steps.append({"step": step, "status": status})
    return steps


def initialize_plan_research_session(
    plan_id: str,
    display_message: str,
    settings: dict[str, Any],
    command: list[str],
    backend: str,
) -> None:
    ensure_server_accepting_runs()
    aux_guard_dir = start_v2_aux_guard("plan")
    with RESEARCH_LOCK:
        proc = RESEARCH_SESSION.get("process")
        status = str(RESEARCH_SESSION.get("status") or "")
        if agent_process_tree_active(proc) or session_startup_without_process(status, RESEARCH_SESSION.get("started_at")):
            raise ValueError(f"A {agent_display_name(backend)} run is already active.")
        RESEARCH_SESSION.update(
            {
                "id": f"S{now_id()}_plan",
                "session_id": "",
                "status": "running",
                "backend": backend,
                "mode": "plan",
                "command": command,
                "settings": settings,
                "run_settings": dict(settings),
                "started_at": now_iso(),
                "ended_at": "",
                "returncode": None,
                "logs": [],
                "raw_logs": [],
                "transcript": [],
                "streaming_transcript": {},
                "loop_active": False,
                "loop_stop_reason": RESEARCH_SESSION.get("loop_stop_reason", ""),
                "process": None,
                "last_event_at": now_iso(),
                "last_event_summary": "Starting plan mode.",
                "agent_notice": {},
                "protected_snapshot": None,
                "plan_id": plan_id,
                "plan_thread_id": "",
                "plan_turn_id": "",
                "v2_aux_guard_dir": aux_guard_dir,
            }
        )
        RESEARCH_SESSION["transcript"].append(transcript_entry("user", "user", "User", display_message, "ui.plan", True))
        trim_transcript_locked()
        session_patch = research_event_session_patch()
    persist_research_session()
    emit_research_event("session", {"session_patch": session_patch})


def start_plan_process(
    command: list[str],
    settings: dict[str, Any],
    backend: str,
    plan_id: str,
    processor: Any,
    prompt: str,
) -> dict[str, Any]:
    ensure_server_accepting_runs()
    wrapper_path: Path | None = None
    proc: subprocess.Popen[str] | None = None
    try:
        process_env = agent_process_env(backend, settings)
        popen_command, use_shell, wrapper_path = popen_command_for_agent(command, settings, process_env)
        proc = spawn_agent_process(
            popen_command,
            cwd=REPO_ROOT,
            env=process_env,
            stdin=subprocess.PIPE,
            stdout=subprocess.PIPE,
            stderr=subprocess.STDOUT,
            text=True,
            bufsize=1,
            shell=use_shell,
        )
        if wrapper_path:
            setattr(proc, "_coauto_pre_exec_wrapper", wrapper_path)
        with RESEARCH_LOCK:
            RESEARCH_SESSION["process"] = proc
            RESEARCH_SESSION["pre_exec_script_applied"] = bool(wrapper_path)
        record_research_process_tree(proc)
    except (OSError, ValueError, RuntimeError) as exc:
        if proc is not None and not ensure_agent_process_tree_drained(proc):
            return research_session_snapshot()
        if wrapper_path:
            try:
                wrapper_path.unlink(missing_ok=True)
            except OSError:
                pass
        message = agent_start_error_message(exc, command, backend) if isinstance(exc, OSError) else str(exc)
        append_research_log(message)
        mark_plan_artifact_failed(plan_id, message)
        finish_research_run(127)
        audit_v2_aux_guard()
        return research_session_snapshot()

    assert proc is not None
    append_research_log(f"Started: {' '.join(command)}")
    if wrapper_path:
        append_research_log(f"Applied shell setup before starting {agent_display_name(backend)}.")
    context = current_project_context()
    thread = threading.Thread(target=run_in_project, args=(context, processor, proc, plan_id, prompt, settings), daemon=True)
    with RESEARCH_LOCK:
        RESEARCH_SESSION["process_thread"] = thread
    thread.start()
    return research_session_snapshot()


def process_codex_app_server_plan_run(
    proc: subprocess.Popen[str],
    plan_id: str,
    prompt: str,
    settings: dict[str, Any],
) -> None:
    returncode: int | None = None
    thread_id = ""
    turn_id = ""
    plan_text_parts: dict[str, list[str]] = {}
    final_plan_text = ""
    sent_thread_start = False
    sent_turn_start = False
    next_request_id = 1
    normalizer = make_research_trace_normalizer("codex", "app-server", settings)

    def request(method: str, params: dict[str, Any] | None = None) -> int:
        nonlocal next_request_id
        request_id = next_request_id
        next_request_id += 1
        json_rpc_write(proc, {"jsonrpc": "2.0", "id": request_id, "method": method, "params": params or {}})
        return request_id

    try:
        assert proc.stdout is not None
        request(
            "initialize",
            {
                "clientInfo": {"name": "co-auto-research-ui", "version": "1.0", "title": "CoAutoResearch UI"},
                "capabilities": {"experimentalApi": True},
            },
        )
        for line in proc.stdout:
            append_research_log(line, normalizer)
            stripped = line.strip()
            if not stripped:
                continue
            try:
                event = json.loads(stripped)
            except json.JSONDecodeError:
                continue
            if not isinstance(event, dict):
                continue
            rpc_request_id = event.get("id") if "id" in event else None
            request_method = str(event.get("method") or "").strip()
            if rpc_request_id is not None and request_method:
                result = codex_server_request_result(request_method)
                try:
                    if result is None:
                        json_rpc_write(
                            proc,
                            {
                                "jsonrpc": "2.0",
                                "id": rpc_request_id,
                                "error": {
                                    "code": -32601,
                                    "message": f"CoAutoResearch does not handle {request_method} requests.",
                                },
                            },
                        )
                    else:
                        json_rpc_write(proc, {"jsonrpc": "2.0", "id": rpc_request_id, "result": result})
                        if normalizer is not None:
                            resolved = normalizer.resolve_approval(str(rpc_request_id), "declined", "auto_policy")
                            if resolved:
                                append_trace_updates([resolved])
                except Exception:
                    pass
                continue
            if event.get("error"):
                error_text = event_payload_text(event.get("error")) or "Codex app-server returned an error."
                raise RuntimeError(
                    f"{error_text} Codex plan mode requires app-server experimental collaborationMode support; upgrade Codex CLI."
                )

            method, params = codex_plan_event_parts(event)
            if method in {"thread/started", "thread.started"}:
                thread_id = extract_nested_id(params, ("threadId", "thread_id", "id")) or thread_id
            if method in {"turn/started", "turn.started"}:
                turn_id = extract_nested_id(params, ("turnId", "turn_id", "id")) or turn_id
                if turn_id:
                    with RESEARCH_LOCK:
                        RESEARCH_SESSION["plan_turn_id"] = turn_id
                    update_plan_artifact(plan_id, thread_id=thread_id, session_id=thread_id, status="running")

            response_id = int(event.get("id") or 0) if str(event.get("id") or "").isdigit() else 0
            if response_id == 1 and not sent_thread_start:
                json_rpc_write(proc, {"jsonrpc": "2.0", "method": "initialized", "params": {}})
                request(
                    "thread/start",
                    {
                        "cwd": str(REPO_ROOT),
                        "model": normalize_codex_model(settings.get("model")),
                        "sandbox": "read-only",
                        "approvalPolicy": "never",
                    },
                )
                sent_thread_start = True
                continue

            if sent_thread_start and not sent_turn_start:
                candidate_thread_id = extract_nested_id(event, ("threadId", "thread_id", "id"))
                if candidate_thread_id:
                    thread_id = thread_id or candidate_thread_id
                    with RESEARCH_LOCK:
                        RESEARCH_SESSION["plan_thread_id"] = thread_id
                    model = normalize_codex_model(settings.get("model"))
                    reasoning = normalize_reasoning_effort(settings.get("reasoningEffort"), "codex", model)
                    request(
                        "turn/start",
                        {
                            "threadId": thread_id,
                            "input": [{"type": "text", "text": prompt, "text_elements": []}],
                            "cwd": str(REPO_ROOT),
                            "model": model,
                            "approvalPolicy": "never",
                            "sandboxPolicy": {"type": "readOnly", "networkAccess": bool(settings.get("webSearch"))},
                            "collaborationMode": {
                                "mode": "plan",
                                "settings": {
                                    "model": model,
                                    "reasoning_effort": reasoning or None,
                                    "developer_instructions": None,
                                },
                            },
                        },
                    )
                    sent_turn_start = True
                    update_plan_artifact(plan_id, thread_id=thread_id, session_id=thread_id, status="running")
                    continue

            if method in {"item/plan/delta", "item.plan.delta"}:
                item_id = str(params.get("itemId") or params.get("item_id") or "plan")
                delta = str(params.get("delta") or "")
                if delta:
                    plan_text_parts.setdefault(item_id, []).append(delta)
                    plan_text = "".join(plan_text_parts[item_id]).strip()
                    artifact = update_plan_artifact(plan_id, status="running", plan_text=plan_text, thread_id=thread_id, session_id=thread_id)
                    append_plan_transcript(artifact)
                continue

            if method in {"turn/plan/updated", "turn.plan.updated"}:
                steps = plan_steps_from_payload(params.get("plan"))
                artifact = update_plan_artifact(
                    plan_id,
                    status="running",
                    steps=steps,
                    explanation=str(params.get("explanation") or ""),
                    thread_id=thread_id,
                    session_id=thread_id,
                )
                append_plan_transcript(artifact)
                continue

            if method in {"item/completed", "item.completed"}:
                item = params.get("item") if isinstance(params.get("item"), dict) else {}
                if str(item.get("type") or "").lower() == "plan":
                    final_plan_text = str(item.get("text") or "").strip()
                    if final_plan_text:
                        artifact = update_plan_artifact(
                            plan_id,
                            status="ready",
                            plan_text=final_plan_text,
                            thread_id=thread_id,
                            session_id=thread_id,
                        )
                        append_plan_transcript(artifact)
                continue

            if method in {"turn/completed", "turn.completed"}:
                break
        try:
            if proc.stdin:
                proc.stdin.close()
        except OSError:
            pass
        try:
            returncode = proc.wait(timeout=3)
        except subprocess.TimeoutExpired:
            # `codex app-server` is a long-lived server process. After the
            # plan turn completes, stop the stdio server explicitly so the UI
            # session can complete instead of waiting for the server forever.
            signal_research_process(proc)
            try:
                returncode = proc.wait(timeout=3)
            except subprocess.TimeoutExpired:
                signal_research_process(proc, force=True)
                returncode = proc.wait(timeout=1)
    except Exception as exc:  # pragma: no cover - defensive adapter handling
        append_research_log(f"Codex plan mode error: {exc}")
        mark_plan_artifact_failed(plan_id, str(exc))
        returncode = proc.poll()
    finally:
        try:
            if proc.stdin:
                proc.stdin.close()
        except OSError:
            pass

    with RESEARCH_LAUNCH_LOCK:
        finalize_codex_plan_run_after_drain(
            proc, plan_id, returncode, normalizer, final_plan_text, thread_id
        )


def finalize_codex_plan_run_after_drain(
    proc: subprocess.Popen[str],
    plan_id: str,
    returncode: int | None,
    normalizer: Any,
    final_plan_text: str,
    thread_id: str,
) -> None:
    if not ensure_agent_process_tree_drained(proc):
        mark_plan_artifact_failed(plan_id, "Agent process group/Job did not drain.")
        return
    wrapper_path = getattr(proc, "_coauto_pre_exec_wrapper", None)
    if wrapper_path:
        try:
            Path(wrapper_path).unlink(missing_ok=True)
        except OSError:
            pass
    with RESEARCH_LOCK:
        if RESEARCH_SESSION.get("process") is not proc:
            return
    if normalizer is not None:
        try:
            append_trace_updates(normalizer.finish(returncode))
        except Exception as exc:  # pragma: no cover - defensive trace finalization
            append_research_log(f"Structured trace finalization warning: {exc}")
    artifact = read_plan_artifact(plan_id)
    if str(artifact.get("status") or "") != "ready":
        text = str(artifact.get("plan_text") or final_plan_text or "").strip()
        if text:
            artifact = update_plan_artifact(plan_id, status="ready", plan_text=text, thread_id=thread_id, session_id=thread_id)
            append_plan_transcript(artifact)
            returncode = 0
        else:
            mark_plan_artifact_failed(
                plan_id,
                "Codex app-server did not return a plan item. Upgrade Codex CLI; CoAutoResearch does not fallback to sending `/plan` through codex exec.",
            )
            returncode = returncode if returncode not in {0, None} else 1
    finish_research_run(0 if str(read_plan_artifact(plan_id).get("status") or "") == "ready" else returncode)
    audit_v2_aux_guard()


def codex_app_server_sandbox_policy(settings: dict[str, Any]) -> dict[str, Any]:
    sandbox = str(settings.get("sandbox") or "workspace-write").strip()
    policy_type = {
        "read-only": "readOnly",
        "workspace-write": "workspaceWrite",
        "danger-full-access": "dangerFullAccess",
    }.get(sandbox, "workspaceWrite")
    policy: dict[str, Any] = {"type": policy_type}
    if policy_type != "dangerFullAccess":
        policy["networkAccess"] = bool(settings.get("webSearch"))
    return policy


def process_codex_app_server_interactive_run(
    proc: subprocess.Popen[str],
    prompt: str,
    settings: dict[str, Any],
    resume: bool,
) -> None:
    returncode: int | None = None
    thread_id = ""
    turn_id = ""
    sent_initialized = False
    sent_turn_start = False
    thread_request_id = 0
    resume_requested = bool(resume and str(RESEARCH_SESSION.get("session_id") or "").strip())
    next_request_id = 1
    normalizer = make_research_trace_normalizer("codex", "app-server", settings)
    model = normalize_codex_model(settings.get("model"))
    sandbox = str(settings.get("sandbox") or "workspace-write")
    approval = str(settings.get("approvalPolicy") or "on-request")
    effort = normalize_reasoning_effort(settings.get("reasoningEffort"), "codex", model)

    def request(method: str, params: dict[str, Any] | None = None) -> int:
        nonlocal next_request_id
        request_id = next_request_id
        next_request_id += 1
        json_rpc_write(proc, {"jsonrpc": "2.0", "id": request_id, "method": method, "params": params or {}})
        return request_id

    def request_thread_start() -> int:
        return request(
            "thread/start",
            {
                "cwd": str(REPO_ROOT),
                "model": model,
                "sandbox": sandbox,
                "approvalPolicy": approval,
            },
        )

    def request_thread_resume(session_id: str) -> int:
        return request(
            "thread/resume",
            {
                "threadId": session_id,
                "cwd": str(REPO_ROOT),
                "model": model,
                "sandbox": sandbox,
                "approvalPolicy": approval,
            },
        )

    def start_turn() -> None:
        nonlocal sent_turn_start
        if sent_turn_start or not thread_id:
            return
        request(
            "turn/start",
            {
                "threadId": thread_id,
                "input": [{"type": "text", "text": prompt, "text_elements": []}],
                "cwd": str(REPO_ROOT),
                "model": model,
                "effort": effort,
                "approvalPolicy": approval,
                "sandboxPolicy": codex_app_server_sandbox_policy(settings),
            },
        )
        sent_turn_start = True

    try:
        assert proc.stdout is not None
        request(
            "initialize",
            {
                "clientInfo": {"name": "co-auto-research-ui", "version": "1.0", "title": "CoAutoResearch UI"},
                "capabilities": {"experimentalApi": True},
            },
        )
        for line in proc.stdout:
            append_research_log(line, normalizer)
            stripped = line.strip()
            if not stripped:
                continue
            try:
                event = json.loads(stripped)
            except json.JSONDecodeError:
                continue
            if not isinstance(event, dict):
                continue

            rpc_request_id = event.get("id") if "id" in event else None
            request_method = str(event.get("method") or "").strip()
            if rpc_request_id is not None and request_method:
                result = codex_server_request_result(request_method)
                try:
                    if result is None:
                        json_rpc_write(
                            proc,
                            {
                                "jsonrpc": "2.0",
                                "id": rpc_request_id,
                                "error": {
                                    "code": -32601,
                                    "message": f"CoAutoResearch does not handle {request_method} requests.",
                                },
                            },
                        )
                    else:
                        json_rpc_write(proc, {"jsonrpc": "2.0", "id": rpc_request_id, "result": result})
                    if result is not None and normalizer is not None:
                        resolved = normalizer.resolve_approval(str(rpc_request_id), "declined", "auto_policy")
                        if resolved:
                            append_trace_updates([resolved])
                except Exception:
                    pass
                continue

            method, params = codex_plan_event_parts(event)
            request_id = int(event.get("id") or 0) if str(event.get("id") or "").isdigit() else 0

            if event.get("error"):
                if request_id == thread_request_id and resume_requested:
                    resume_requested = False
                    thread_request_id = request_thread_start()
                    continue
                error_text = event_payload_text(event.get("error")) or "Codex app-server returned an error."
                raise RuntimeError(error_text)

            if request_id == 1 and not sent_initialized:
                json_rpc_write(proc, {"jsonrpc": "2.0", "method": "initialized", "params": {}})
                session_id = str(RESEARCH_SESSION.get("session_id") or "").strip()
                thread_request_id = request_thread_resume(session_id) if resume_requested and session_id else request_thread_start()
                sent_initialized = True
                continue

            if method in {"thread/started", "thread.started"}:
                thread_id = extract_nested_id(params, ("threadId", "thread_id", "id")) or thread_id
            if request_id == thread_request_id and not thread_id:
                thread_id = extract_nested_id(event, ("threadId", "thread_id", "id")) or thread_id
            if thread_id:
                with RESEARCH_LOCK:
                    RESEARCH_SESSION["app_thread_id"] = thread_id
                    RESEARCH_SESSION["session_id"] = thread_id
                    RESEARCH_SESSION["session_id_source"] = "app_server"
                start_turn()

            if method in {"turn/started", "turn.started"}:
                turn_id = extract_nested_id(params, ("turnId", "turn_id", "id")) or turn_id
                if turn_id:
                    with RESEARCH_LOCK:
                        RESEARCH_SESSION["app_turn_id"] = turn_id

            if method in {"turn/completed", "turn.completed", "turn/failed", "turn.failed"}:
                break

        try:
            if proc.stdin:
                proc.stdin.close()
        except OSError:
            pass
        try:
            returncode = proc.wait(timeout=3)
        except subprocess.TimeoutExpired:
            signal_research_process(proc)
            try:
                returncode = proc.wait(timeout=3)
            except subprocess.TimeoutExpired:
                signal_research_process(proc, force=True)
                returncode = proc.wait(timeout=1)
    except Exception as exc:  # pragma: no cover - defensive adapter handling
        append_research_log(f"Codex app-server chat error: {exc}")
        returncode = proc.poll()
    finally:
        try:
            if proc.stdin:
                proc.stdin.close()
        except OSError:
            pass

    with RESEARCH_LAUNCH_LOCK:
        finalize_codex_interactive_run_after_drain(proc, returncode, normalizer)


def finalize_codex_interactive_run_after_drain(
    proc: subprocess.Popen[str], returncode: int | None, normalizer: Any
) -> None:
    if not ensure_agent_process_tree_drained(proc):
        return
    wrapper_path = getattr(proc, "_coauto_pre_exec_wrapper", None)
    if wrapper_path:
        try:
            Path(wrapper_path).unlink(missing_ok=True)
        except OSError:
            pass
    with RESEARCH_LOCK:
        if RESEARCH_SESSION.get("process") is not proc:
            return
        mode = str(RESEARCH_SESSION.get("mode") or "")
        protected_snapshot = RESEARCH_SESSION.get("protected_snapshot")
    if normalizer is not None:
        try:
            append_trace_updates(normalizer.finish(returncode))
        except Exception as exc:  # pragma: no cover - defensive trace finalization
            append_research_log(f"Structured trace finalization warning: {exc}")
    finish_research_run(returncode)
    if not audit_v2_aux_guard():
        return
    if mode == "chat":
        restored_paths = restore_chat_protected_snapshot(protected_snapshot if isinstance(protected_snapshot, dict) else None)
        if restored_paths:
            append_research_log(
                "Chat mode guard restored protected autoresearch artifacts; use the Start/Resume autoresearch controls to create trials: "
                + ", ".join(restored_paths)
            )
        sync_human_intervention_indexes("chat_completed")
        with RESEARCH_LOCK:
            RESEARCH_SESSION["protected_snapshot"] = None
        persist_research_session()
    maybe_start_queued_chat_after_run(mode, returncode)


def extract_claude_exit_plan(event: Any) -> str:
    if isinstance(event, dict):
        name = str(event.get("name") or event.get("tool_name") or event.get("tool") or "").strip()
        tool_input = event.get("input") if isinstance(event.get("input"), dict) else event.get("tool_input")
        if name == "ExitPlanMode" and isinstance(tool_input, dict):
            plan = str(tool_input.get("plan") or "").strip()
            if plan:
                return plan
        for value in event.values():
            plan = extract_claude_exit_plan(value)
            if plan:
                return plan
    if isinstance(event, list):
        for item in event:
            plan = extract_claude_exit_plan(item)
            if plan:
                return plan
    return ""


def claude_plan_hook_paths(plan_id: str) -> tuple[Path, Path]:
    hook_dir = ensure_private_directory(plan_runtime_dir(create=True) / "hooks")
    return hook_dir / f"{normalize_plan_id(plan_id)}_exit_plan_hook.py", hook_dir / f"{normalize_plan_id(plan_id)}_settings.json"


def write_claude_plan_hook(plan_id: str) -> Path:
    hook_path, settings_path = claude_plan_hook_paths(plan_id)
    artifact_path = plan_artifact_path(plan_id)
    hook_path.write_text(
        """#!/usr/bin/env python3
import json
import sys
from datetime import datetime, timezone
from pathlib import Path

def find_plan(value):
    if isinstance(value, dict):
        name = str(value.get("name") or value.get("tool_name") or value.get("tool") or "")
        tool_input = value.get("tool_input") if isinstance(value.get("tool_input"), dict) else value.get("input")
        if name == "ExitPlanMode" and isinstance(tool_input, dict):
            plan = str(tool_input.get("plan") or "").strip()
            if plan:
                return plan
        for key in ("tool_input", "input"):
            nested = value.get(key)
            if isinstance(nested, dict):
                plan = str(nested.get("plan") or "").strip()
                if plan:
                    return plan
        for nested in value.values():
            plan = find_plan(nested)
            if plan:
                return plan
    if isinstance(value, list):
        for nested in value:
            plan = find_plan(nested)
            if plan:
                return plan
    return ""

artifact_path = Path(sys.argv[1])
try:
    payload = json.loads(sys.stdin.read() or "{}")
except json.JSONDecodeError:
    payload = {}
plan = find_plan(payload)
if plan:
    artifact = json.loads(artifact_path.read_text(encoding="utf-8"))
    artifact["status"] = "ready"
    artifact["plan_text"] = plan
    artifact["updated_at"] = datetime.now(timezone.utc).isoformat()
    artifact_path.write_text(json.dumps(artifact, ensure_ascii=False, indent=2) + "\\n", encoding="utf-8")
print(json.dumps({
    "hookSpecificOutput": {
        "hookEventName": "PermissionRequest",
        "decision": {"behavior": "deny"}
    }
}))
""",
        encoding="utf-8",
    )
    hook_path.chmod(stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR)
    command = f"{shlex.quote(sys.executable)} {shlex.quote(str(hook_path))} {shlex.quote(str(artifact_path))}"
    settings_payload = {
        "hooks": {
            "PermissionRequest": [
                {
                    "matcher": "ExitPlanMode",
                    "hooks": [{"type": "command", "command": command}],
                }
            ]
        }
    }
    settings_path.write_text(json.dumps(settings_payload, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    return settings_path


def process_claude_plan_run(
    proc: subprocess.Popen[str],
    plan_id: str,
    prompt: str,
    settings: dict[str, Any],
) -> None:
    returncode: int | None = None
    try:
        assert proc.stdin is not None
        proc.stdin.write(prompt)
        proc.stdin.write("\n")
        proc.stdin.close()
        assert proc.stdout is not None
        for line in proc.stdout:
            append_research_log(line)
            stripped = line.strip()
            if not stripped:
                continue
            try:
                event = json.loads(stripped)
            except json.JSONDecodeError:
                continue
            plan = extract_claude_exit_plan(event)
            if plan:
                artifact = update_plan_artifact(plan_id, status="ready", plan_text=plan)
                append_plan_transcript(artifact)
        returncode = proc.wait()
    except Exception as exc:  # pragma: no cover - defensive adapter handling
        append_research_log(f"Claude plan mode error: {exc}")
        mark_plan_artifact_failed(plan_id, str(exc))
        returncode = proc.poll()
    with RESEARCH_LAUNCH_LOCK:
        finalize_claude_plan_run_after_drain(proc, plan_id, returncode)


def finalize_claude_plan_run_after_drain(
    proc: subprocess.Popen[str], plan_id: str, returncode: int | None
) -> None:
    if not ensure_agent_process_tree_drained(proc):
        mark_plan_artifact_failed(plan_id, "Agent process group/Job did not drain.")
        return
    wrapper_path = getattr(proc, "_coauto_pre_exec_wrapper", None)
    if wrapper_path:
        try:
            Path(wrapper_path).unlink(missing_ok=True)
        except OSError:
            pass
    with RESEARCH_LOCK:
        if RESEARCH_SESSION.get("process") is not proc:
            return
    artifact = read_plan_artifact(plan_id)
    if str(artifact.get("status") or "") != "ready" and str(artifact.get("plan_text") or "").strip():
        artifact = update_plan_artifact(plan_id, status="ready")
        append_plan_transcript(artifact)
    if str(read_plan_artifact(plan_id).get("status") or "") != "ready":
        mark_plan_artifact_failed(plan_id, "Claude plan mode did not provide an ExitPlanMode plan.")
        returncode = returncode if returncode not in {0, None} else 1
    finish_research_run(0 if str(read_plan_artifact(plan_id).get("status") or "") == "ready" else returncode)
    audit_v2_aux_guard()


def start_codex_plan_run(prompt: str, display_message: str, settings: dict[str, Any], artifact: dict[str, Any]) -> dict[str, Any]:
    backend = "codex"
    env = agent_process_env(backend, settings)
    ensure_agent_ready(backend, env=env, settings=settings, force_refresh=False)
    command = codex_app_server_command(settings)
    initialize_plan_research_session(str(artifact["id"]), display_message, settings, command, backend)
    update_plan_artifact(str(artifact["id"]), status="running")
    return start_plan_process(command, settings, backend, str(artifact["id"]), process_codex_app_server_plan_run, prompt)


def start_claude_plan_run(prompt: str, display_message: str, settings: dict[str, Any], artifact: dict[str, Any]) -> dict[str, Any]:
    backend = "claude"
    plan_settings = normalize_claude_settings({**settings, "permissionPreset": "plan", "permissionMode": "plan"}, settings)
    plan_settings["backend"] = "claude"
    env = agent_process_env(backend, plan_settings)
    ensure_agent_ready(backend, env=env, settings=plan_settings, force_refresh=False)
    settings_path = write_claude_plan_hook(str(artifact["id"]))
    executable = resolve_agent_executable("claude", env)
    command = [executable, *settings_to_claude_args(plan_settings, resume=False), "--settings", str(settings_path)]
    initialize_plan_research_session(str(artifact["id"]), display_message, plan_settings, command, backend)
    update_plan_artifact(str(artifact["id"]), status="running")
    return start_plan_process(command, plan_settings, backend, str(artifact["id"]), process_claude_plan_run, prompt)


def cold_start_prompt(payload: dict[str, Any]) -> str:
    brief = str(payload.get("brief", "")).strip()
    target_venue = str(payload.get("targetVenue", "")).strip()
    return f"""Run adaptive intake triage for this CoAutoResearch scaffold, then cold start or conversion only as appropriate.

User brief:
{brief}

Target venue / audience:
{target_venue or "Not provided"}

	{chat_history_prompt_section(payload.get("conversationHistory"))}
	{response_language_prompt_section()}
	{mandatory_conversion_prompt_section()}

Resource locations to inspect:
- ongoing work: resources/ongoing_work/
- proposals: resources/proposals/
- literature: resources/literature/
- data: resources/data_sources/
- other or mixed materials: resources/other/
- target venue notes: resources/target_venue/

Treat these resource folders as initial UI-side filing, not ground truth. Use the user brief,
target venue, file names, and file contents to infer whether each resource is ongoing work,
papers, proposal material, data, or miscellaneous context. If a resource appears misclassified,
note the corrected role in PROJECT.md / STATE.md and move or reference it appropriately.

Use the repository instructions:
- read AGENTS.md
- read instructions/COLD_START.md
- read instructions/RESOURCE_INTAKE.md
- read instructions/CONVERSION.md
- read resources/user_input/INITIAL_BRIEF.md
- read resources/user_input/RESOURCE_MANIFEST.md if present
- inspect relevant resource contents under the Content Inspection Gate in `instructions/RESOURCE_INTAKE.md` before making any venue-fit, contribution, evidence, methods, results, manuscript-status, or project-framing claim from them
- if RESOURCE_MANIFEST.md contains inferred resource references, unresolved resources, or ambiguous resources, complete or block Resource Intake before treating those materials as available
- initialize or update PROJECT.md, research_trajectory/STATE.md, the conversion trial, and manuscript/BLUEPRINT.md only as appropriate under the adaptive intake router

Continue until the cold-start state is genuinely reflected in repository files. Be concise in your final response."""


def framing_prompt(payload: dict[str, Any]) -> str:
    brief = str(payload.get("brief", "")).strip()
    target_venue = str(payload.get("targetVenue", "")).strip()
    return f"""Frame this CoAutoResearch project before the full autoresearch loop starts.

User brief:
{brief}

Target venue / audience:
{target_venue or "Not provided"}

{response_language_prompt_section()}

Resource locations to inspect:
- ongoing work: resources/ongoing_work/
- proposals: resources/proposals/
- literature: resources/literature/
- data: resources/data_sources/
- other or mixed materials: resources/other/
- target venue notes: resources/target_venue/

Use the repository instructions and inspect only the files needed to write a useful project frame.

Your task:
- read AGENTS.md
- read instructions/RESOURCE_INTAKE.md
- read instructions/PROJECT_FRAMING.md
- read instructions/COLD_START.md and instructions/CONVERSION.md only as needed
- read resources/user_input/INITIAL_BRIEF.md
- read resources/user_input/RESOURCE_MANIFEST.md if present
- if RESOURCE_MANIFEST.md contains inferred, unresolved, or ambiguous resource clues, run Resource Intake first and do not treat those clues as attached resources until they are filed or explicitly blocked
- inspect attached resource contents under the Content Inspection Gate in `instructions/RESOURCE_INTAKE.md` before making any venue-fit, contribution, evidence, methods, results, manuscript-status, or project-framing claim from them
- write or update PROJECT.md as a concrete, user-reviewable research framing document

Do not launch the full autoresearch loop. Do not create trials yet unless absolutely necessary.
Focus on PROJECT.md: research topic, problem, scope, target venue/audience, likely contribution type,
resources to use, uncertainties, and what would count as a useful result.

When PROJECT.md is ready for human review, stop and summarize briefly."""


def autoresearch_goal_prompt(launch_instruction: str = "", fast_mode: bool = False) -> str:
    instruction = str(launch_instruction or "").strip()
    instruction_section = ""
    if instruction:
        instruction_section = f"""

Additional user instruction for this launch:
{instruction}

Apply this launch instruction when choosing and executing the next research objective, but do not let it weaken the reviewer gate, provenance, or final-pass requirements below."""
    return f"""Start the CoAutoResearch autoresearch process from PROJECT.md. Complete exactly the next complete research-attempt boundary, update the autoresearch gate, then stop and return control to the UI.

This is after the user-facing framing pass. Do not rerun cold-start framing just to rewrite PROJECT.md.

This is one bounded agent invocation. The CoAutoResearch server owns the outer loop and will inspect the gate after this run to decide whether another trial is needed.
{instruction_section}
{fast_mode_prompt_section(fast_mode)}
	{pending_intervention_prompt_section()}
	{human_tasks_prompt_section()}
	{mandatory_conversion_prompt_section()}

Use the repository instructions:
- read AGENTS.md
- read instructions/EXECUTION_AGENT.md
- read PROJECT.md
- read research_trajectory/STATE.md
- read research_trajectory/CURRENT_FINDINGS.md
- if the next objective depends on user-provided resources, complete the Content Inspection Gate in instructions/RESOURCE_INTAKE.md before using those resources for content-grounded planning, evidence, venue, methods, results, manuscript, or state claims
- read instructions/RESOURCE_SCOUT.md
- read instructions/REVIEWER_SCOPE_ANALYST.md
- read instructions/reviewers/REVIEW_TAXONOMY.md
- read all eight core reviewer instructions under instructions/reviewers/
- read instructions/reviewers/FINAL_GATE_REVIEWER.md
- create or update the `Autoresearch Goal Gate` section in research_trajectory/STATE.md

{resource_scout_prompt_section()}
{reviewer_scope_analyst_prompt_section()}

Run exactly the next autoresearch iteration and maintain the reviewer gate:
1. choose the complete research objective required to make the current deliverable submission-ready for the target venue if provided, or deliverable-ready under PROJECT.md if no target venue is provided;
2. create the next trial under research_trajectory/trials/;
3. write PLAN.md before execution, including `## Resource Scout Brief`;
4. create `reviews/` and write PLAN_REVIEW.md before execution;
5. run Resource Scout work if required: use a real subagent when available, otherwise use the inline Resource Scout fallback, then revise PLAN.md and rerun PLAN_REVIEW.md if scout outputs change planning assumptions;
6. execute primarily in workspace/;
7. write REPORT.md after execution;
8. run Reviewer Scope Analyst work: use a real subagent when available, otherwise use the inline Reviewer Scope Analyst fallback, to decide whether the eight core reviewers cover the current trial's review risks;
9. if the reviewer spawn decision says `Spawn needed: yes`, run the specialized reviewer before core reviewers;
10. refresh all eight current-trial reviewer files after REPORT.md and reviewer-scope analysis: PLAN_REVIEW.md, PROCESS_REVIEW.md, EVIDENCE_REVIEW.md, VENUE_FIT_REVIEW.md, MANUSCRIPT_REVIEW.md, FIGURE_TABLE_REVIEW.md, REFERENCE_REVIEW.md, and FINAL_GATE_REVIEW.md;
11. update STATE.md, CURRENT_FINDINGS.md, manuscript-facing files, or notes only when their current state genuinely changes;
12. update the `Autoresearch Goal Gate` section in research_trajectory/STATE.md with:
   - `Status: pass`, `continue`, `blocked`, or `needs_human`;
   - one line for each required reviewer gate: Plan, Process, Evidence, Venue fit, Manuscript, Figure/table, Reference, Final gate;
   - the current trial reviewer file path on each reviewer gate line;
   - the next action if any gate is not pass;
   - if `Status: blocked` or `Status: needs_human`, `Response to human: <one concise user-facing question or decision request>`.

This invocation is complete after the current trial boundary is closed and the gate is updated, even if the gate remains `continue`, `blocked`, or `needs_human`. Do not start a later trial in this invocation.

Required reviewer gates must all be strict `pass` before the autoresearch goal is complete, including the Final gate reviewer. If any current-trial reviewer file is missing, not pass, or has any blocking issue, required action, unresolved qualification, active revision constraint, or critical unassessed area, set `Status: continue` unless human input is truly required.

Do not treat "approved", "completed", "ready", "plausible", "architecture pass", "supported with qualification", or "targeted revision ready" as pass. Those are partial results unless the relevant reviewer standard and Final gate standard are fully satisfied.

Before any final pass in a manuscript-facing project, run a final synthesis step:
update `manuscript/PAPER_PLAN.md`, `manuscript/BLUEPRINT.md`,
`research_trajectory/CURRENT_FINDINGS.md`, and
`manuscript/figures/FIGURE_SPECS.md` as needed. The final blueprint must be
non-stub, full-results, self-contained, and target-venue-ready in final
manuscript reading order:
architecture overview/table of contents, section/subsection architecture, local
claim/evidence/result explanations, inline figure/table/algorithm/dataset/
benchmark/result blocks with captions/content/source/provenance/venue rationale,
and Markdown preview images for image-source figures, reference/literature
grounding, appendix/supplement posture, required
qualifications, provenance/audit index, deprecated ideas, and
submission-readiness summary must all be current. Separate
claim/evidence maps, Figure Plan, Table Plan, or FIGURE_SPECS entries may
support audit only; they do not satisfy final readability by themselves. If
`BLUEPRINT.md` is a stub, if `PAPER_PLAN.md` still has blocking evidence, if an
active artifact lacks inline placement/caption/content/source/provenance/venue
rationale, if reviewer instructions are outdated, or if stale language such as
"tentative until source-level evidence checks are completed" remains, keep
`Status: continue`.

Treat PROJECT.md as the current goal definition. If PROJECT.md is insufficient or contradictory, do not silently invent a different project. Follow `instructions/EXECUTION_AGENT.md` for Critical Path escalation: continue while critical-path-advancing work or an acquisition/substitution rung remains; use `Status: needs_human` only for a documented human-gated Critical Path bottleneck with `Response to human:`."""


def compact_chat_history_items(items: Any, limit: int = CHAT_HISTORY_MAX_MESSAGES) -> list[dict[str, Any]]:
    if not isinstance(items, list):
        return []
    clean: list[dict[str, str]] = []
    for item in items[-limit:]:
        if not isinstance(item, dict):
            continue
        role = str(item.get("role") or "").strip().lower()
        if role not in {"user", "assistant"}:
            continue
        text = str(item.get("text") or item.get("content") or "").strip()
        if not text:
            continue
        clean_item: dict[str, Any] = {
            "id": str(item.get("id") or "").strip()[:120],
            "role": role,
            "kind": str(item.get("kind") or "text").strip()[:80],
            "text": text[:8000],
            "created_at": str(item.get("created_at") or "").strip()[:80],
        }
        attachments = item.get("attachments")
        if isinstance(attachments, list):
            clean_attachments: list[dict[str, str]] = []
            for attachment in attachments[:20]:
                if not isinstance(attachment, dict):
                    continue
                name = str(attachment.get("name") or "").strip()[:240]
                path = str(attachment.get("path") or "").strip()[:1000]
                if not name and not path:
                    continue
                clean_attachments.append(
                    {
                        "kind": str(attachment.get("kind") or "attachment").strip()[:80],
                        "name": name,
                        "path": path,
                        "category": str(attachment.get("category") or "").strip()[:80],
                    }
                )
            if clean_attachments:
                clean_item["attachments"] = clean_attachments
        clean.append(clean_item)
    return clean


def chat_history_prompt_section(conversation_history: Any = None) -> str:
    items = compact_chat_history_items(conversation_history)
    if not items:
        return ""
    lines = ["", "Authoritative UI conversation history for this chat turn:", ""]
    for item in items:
        item_id = f" `{item['id']}`" if item.get("id") else ""
        timestamp = f" ({item['created_at']})" if item.get("created_at") else ""
        lines.append(f"{item['role'].upper()}{item_id}{timestamp}:")
        lines.append(item["text"])
        attachments = item.get("attachments") if isinstance(item.get("attachments"), list) else []
        for attachment in attachments:
            label = attachment.get("path") or attachment.get("name") or "attachment"
            lines.append(f"- attachment: {label} ({attachment.get('kind') or 'attachment'}, {attachment.get('category') or 'resource'})")
        lines.append("")
    lines.append("Use this history as the current UI truth for this chat turn.")
    lines.append("")
    return "\n".join(lines)


def resend_prompt_section(resend_context: Any = None) -> str:
    if not isinstance(resend_context, dict):
        return ""
    edited = str(resend_context.get("editedMessageId") or "").strip()
    if not edited:
        return ""
    archived_count = int(resend_context.get("archivedCount") or 0)
    return f"""

Regenerated reply context:
- The user edited an earlier message `{edited}`.
- The UI has archived {archived_count} later message(s) from the visible conversation.
- Treat the supplied conversation history and current user message as authoritative.
- Ignore any stale context from a resumed CLI session that conflicts with this edited linear history.
"""


def queued_chat_prompt_section(queued_messages: Any = None) -> str:
    items = compact_chat_history_items(queued_messages, CHAT_QUEUE_MAX_MESSAGES)
    if not items:
        return ""
    lines = [
        "",
        "Queued user messages sent while autoresearch was running:",
        "",
        "Answer these messages together in order. They were not answered while the autoresearch run was active.",
        "",
    ]
    for item in items:
        item_id = f" `{item['id']}`" if item.get("id") else ""
        timestamp = f" ({item['created_at']})" if item.get("created_at") else ""
        lines.append(f"USER{item_id}{timestamp}:")
        lines.append(item["text"])
        lines.append("")
    return "\n".join(lines)


def response_language_prompt_section() -> str:
    return """
Response language:
- Match the user's latest message's primary language for user-facing final replies and brief progress updates.
- Preserve technical terms, file paths, code identifiers, titles, and quoted text in their original language.
- If the user explicitly asks for another language, follow that request.
- Do not translate repository artifacts unless the user explicitly asks; keep project files in their established language.
- In user-facing updates, describe the research action, the observation so far, and the next step. State evidence limits and distinguish a proposal from a recorded result. Keep updates short and useful; do not expose private reasoning or narrate schema maintenance.
- Describe discussion handoffs as drafts until the user sends them to the research session. Describe service publication as recording reviewed evidence in the project, not external publication or proof of scientific correctness.
- For delays or failures, say what remains unfinished, the confirmed cause (or that it is unknown), and the available recovery action. Do not claim work is saved, retrying or successful without the corresponding state.
"""


